// ============= MARKETING FUNNEL =============
//
// Customer journey for the selected period. Reach is shown as a contextual stat
// row above the funnel (input metric, not a journey stage). The funnel itself
// shows four stages: Interacted -> Considered -> Lead -> Closed.
//
// Visual: SVG bezier flow with three layered bands (outer wide halo, inner halo,
// main fill) for depth. Each stage has a value chip at the top with a vertical
// guide line connecting down to the stage label. A cumulative percentage chip
// sits on the funnel body itself.
//
// Interaction: hover any stage with ~250ms delay opens a popup showing the
// drill-in (sales/service split + contributors). Mouse-out dismisses with
// bridging so the user can move into the popup without losing it.

const FUNNEL_DATA = {
  period: 'April 2026',
  stages: [
    {
      id: 'interacted',
      label: 'Interacted',
      sublabel: 'Clicked, opened, or actively engaged with a touchpoint',
      total: 147000,
      sales: 88200,
      service: 58800,
      contributors: [
        { name: 'Paid search clicks', count: 64200 },
        { name: 'Social clicks and reactions', count: 42200 },
        { name: 'Email opens and clicks', count: 21300 },
        { name: 'Third-party listing clicks', count: 19300 }
      ]
    },
    {
      id: 'considered',
      label: 'Considered',
      sublabel: 'Landed on a VDP or service appointment page',
      total: 51450,
      sales: 32414,
      service: 19036,
      contributors: [
        { name: 'VDP views', count: 32100 },
        { name: 'Service detail pages', count: 14850 },
        { name: 'Inventory search results', count: 4500 }
      ]
    },
    {
      id: 'lead',
      label: 'Lead',
      sublabel: 'Submitted a form, called, or chatted',
      total: 4630,
      sales: 2825,
      service: 1805,
      contributors: [
        { name: 'Form fills', count: 2010 },
        { name: 'Phone calls', count: 1720 },
        { name: 'Chat sessions', count: 605 },
        { name: 'Service appointment requests', count: 295 }
      ]
    },
    {
      id: 'closed',
      label: 'Closed',
      sublabel: 'Vehicle sold or service work completed',
      total: 1620,
      sales: 358,
      service: 1262,
      contributors: [
        { name: 'Service ROs completed', count: 1262 },
        { name: 'Vehicles sold', count: 358 }
      ]
    }
  ],
  aiCommentary: 'Lead to Closed at 35% is up 6 points from last month, driven by stronger lease-end nurture conversion. Considered to Lead at 9% is the leak I would focus on; the VDP-to-form path is where most drop-off happens.'
};

function formatFunnelCount(n) {
  if (n >= 1000000) return (n / 1000000).toFixed(2).replace(/\.?0+$/, '') + 'M';
  if (n >= 1000) return (n / 1000).toFixed(n >= 100000 ? 0 : 1).replace(/\.0$/, '') + 'K';
  return n.toLocaleString();
}

function formatFunnelRate(r) {
  if (r < 0.1) return r.toFixed(2) + '%';
  if (r < 10) return r.toFixed(1) + '%';
  return Math.round(r) + '%';
}

function formatMoneyShort(amount) {
  if (amount >= 1000000) return '$' + (amount / 1000000).toFixed(2).replace(/\.?0+$/, '') + 'M';
  if (amount >= 1000) return '$' + Math.round(amount / 1000) + 'K';
  return '$' + amount.toLocaleString();
}

function ImpactFunnel({ onDiscuss }) {
  const [hoveredStage, setHoveredStage] = useState(null);
  const enterTimerRef = useRef(null);
  const leaveTimerRef = useRef(null);
  
  const stages = FUNNEL_DATA.stages;
  
  // Compute conversion rates between stages
  const conversions = [];
  for (let i = 1; i < stages.length; i++) {
    const rate = (stages[i].total / stages[i - 1].total) * 100;
    conversions.push({ from: stages[i - 1].id, to: stages[i].id, rate });
  }
  
  const handleStageEnter = (stageId) => {
    if (leaveTimerRef.current) {
      clearTimeout(leaveTimerRef.current);
      leaveTimerRef.current = null;
    }
    if (enterTimerRef.current) clearTimeout(enterTimerRef.current);
    enterTimerRef.current = setTimeout(() => {
      setHoveredStage(stageId);
    }, 250);
  };
  
  const handleStageLeave = () => {
    if (enterTimerRef.current) {
      clearTimeout(enterTimerRef.current);
      enterTimerRef.current = null;
    }
    if (leaveTimerRef.current) clearTimeout(leaveTimerRef.current);
    leaveTimerRef.current = setTimeout(() => {
      setHoveredStage(null);
    }, 200);
  };
  
  const handlePopupEnter = () => {
    if (leaveTimerRef.current) {
      clearTimeout(leaveTimerRef.current);
      leaveTimerRef.current = null;
    }
  };
  
  const handlePopupLeave = () => {
    if (leaveTimerRef.current) clearTimeout(leaveTimerRef.current);
    leaveTimerRef.current = setTimeout(() => {
      setHoveredStage(null);
    }, 200);
  };
  
  const hoveredStageData = hoveredStage ? stages.find(s => s.id === hoveredStage) : null;
  const hoveredConv = hoveredStage ? conversions.find(c => c.to === hoveredStage) : null;
  const hoveredIndex = hoveredStage ? stages.findIndex(s => s.id === hoveredStage) : -1;
  
  return (
    <div style={{
      background: t.surface,
      borderRadius: '14px',
      padding: '24px 28px',
      marginBottom: '40px',
      position: 'relative'
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: '24px', flexWrap: 'wrap', gap: '12px' }}>
        <div>
          <h2 style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, margin: 0, letterSpacing: '-0.005em' }}>
            Marketing funnel
          </h2>
          <p style={{ fontSize: '12px', color: t.textTertiary, margin: '4px 0 0', lineHeight: 1.5 }}>
            How AI's work converted into appointments and sales. Hover any stage for the breakdown.
          </p>
        </div>
        <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500 }}>
          {FUNNEL_DATA.period}
        </div>
      </div>
      
      {/* Funnel - extends edge to edge of card */}
      <div style={{ margin: '0 -28px', position: 'relative' }}>
        <FunnelFlowChart
          stages={stages}
          hoveredStage={hoveredStage}
          onStageEnter={handleStageEnter}
          onStageLeave={handleStageLeave}
        />
        
        {/* Hover popup, anchored relative to the funnel container */}
        {hoveredStageData && (
          <FunnelStagePopup
            stage={hoveredStageData}
            conversionFromPrev={hoveredConv}
            stageIndex={hoveredIndex}
            totalStages={stages.length}
            onEnter={handlePopupEnter}
            onLeave={handlePopupLeave}
          />
        )}
      </div>
      
      {/* AI commentary */}
      <div
        onClick={() => onDiscuss({
          label: 'Marketing funnel',
          prefilledQuestion: 'Walk me through the marketing funnel. Where are the biggest leaks and what would you change?'
        })}
        style={{
          marginTop: '24px',
          paddingTop: '20px',
          borderTop: '1px solid ' + t.surfaceMuted,
          display: 'flex',
          alignItems: 'flex-start',
          gap: '10px',
          cursor: 'pointer'
        }}
      >
        <img src={TEKION_AI_LOGO} alt="" style={{ width: '18px', height: '18px', flexShrink: 0, marginTop: '1px' }} />
        <div style={{ flex: 1, fontSize: '13px', color: t.textPrimary, lineHeight: 1.6 }}>
          {FUNNEL_DATA.aiCommentary}
        </div>
      </div>
    </div>
  );
}

// ============= FUNNEL FLOW CHART (SVG) =============
function FunnelFlowChart({ stages, hoveredStage, onStageEnter, onStageLeave }) {
  const VIEWBOX_W = 1100;
  const VIEWBOX_H = 380;
  
  // Top: breathing room and halo room
  const HEADER_H = 40;
  // Bottom: label + value stack + halo room + breathing space
  const FOOTER_H = 110;
  
  const FLOW_AREA_H = VIEWBOX_H - HEADER_H - FOOTER_H;
  const CENTER_Y = HEADER_H + FLOW_AREA_H / 2;
  
  const numStages = stages.length;
  const stageWidth = VIEWBOX_W / numStages;
  
  // Plateau ratio: each stage has a flat plateau in the center; transitions
  // happen across the outer portions. Lower ratio = smoother, more dramatic curves.
  const PLATEAU_RATIO = 0.4;
  
  const maxValue = stages[0].total;
  const minStageHeight = 6;
  
  const stageGeometry = stages.map((stage, i) => {
    const ratio = stage.total / maxValue;
    const rawHeight = ratio * FLOW_AREA_H;
    const halfH = Math.max(rawHeight, minStageHeight) / 2;
    const xLeft = i * stageWidth;
    const xRight = xLeft + stageWidth;
    const xCenter = (xLeft + xRight) / 2;
    
    const plateauHalfWidth = (stageWidth * PLATEAU_RATIO) / 2;
    const plateauStart = xCenter - plateauHalfWidth;
    const plateauEnd = xCenter + plateauHalfWidth;
    
    const yTop = CENTER_Y - halfH;
    const yBottom = CENTER_Y + halfH;
    
    const cumPct = (stage.total / maxValue) * 100;
    
    return {
      ...stage,
      xLeft, xRight, xCenter,
      plateauStart, plateauEnd,
      yTop, yBottom, halfH,
      cumPct
    };
  });
  
  // Compute the visual centerline of each stage's body. The visible band
  // for stage N extends from roughly the midpoint of (prev plateau end, this plateau start)
  // on the left to the midpoint of (this plateau end, next plateau start) on the right.
  // For first/last stages, the outer edge is the SVG edge.
  const stageBandCenters = stageGeometry.map((s, i) => {
    const prev = i > 0 ? stageGeometry[i - 1] : null;
    const next = i < stageGeometry.length - 1 ? stageGeometry[i + 1] : null;
    
    const bandLeft = prev ? (prev.plateauEnd + s.plateauStart) / 2 : s.xLeft;
    const bandRight = next ? (s.plateauEnd + next.plateauStart) / 2 : s.xRight;
    
    return (bandLeft + bandRight) / 2;
  });
  
  // Build a smooth path through stages with bezier transitions
  const buildPath = (geomList, padding = 0) => {
    if (geomList.length === 0) return '';
    
    let path = '';
    const first = geomList[0];
    const last = geomList[geomList.length - 1];
    
    // Top edge (left to right)
    path += 'M ' + first.xLeft + ' ' + (first.yTop - padding);
    path += ' L ' + first.plateauEnd + ' ' + (first.yTop - padding);
    
    for (let i = 0; i < geomList.length - 1; i++) {
      const cur = geomList[i];
      const next = geomList[i + 1];
      const x1 = cur.plateauEnd;
      const y1 = cur.yTop - padding;
      const x2 = next.plateauStart;
      const y2 = next.yTop - padding;
      const cx1 = x1 + (x2 - x1) * 0.5;
      const cx2 = x1 + (x2 - x1) * 0.5;
      path += ' C ' + cx1 + ' ' + y1 + ', ' + cx2 + ' ' + y2 + ', ' + x2 + ' ' + y2;
      path += ' L ' + next.plateauEnd + ' ' + y2;
    }
    
    path += ' L ' + last.xRight + ' ' + (last.yTop - padding);
    
    // Right edge
    path += ' L ' + last.xRight + ' ' + (last.yBottom + padding);
    
    // Bottom edge (right to left)
    path += ' L ' + last.plateauEnd + ' ' + (last.yBottom + padding);
    
    for (let i = geomList.length - 1; i > 0; i--) {
      const cur = geomList[i];
      const prev = geomList[i - 1];
      const x1 = cur.plateauStart;
      const y1 = cur.yBottom + padding;
      const x2 = prev.plateauEnd;
      const y2 = prev.yBottom + padding;
      const cx1 = x1 + (x2 - x1) * 0.5;
      const cx2 = x1 + (x2 - x1) * 0.5;
      path += ' L ' + x1 + ' ' + y1;
      path += ' C ' + cx1 + ' ' + y1 + ', ' + cx2 + ' ' + y2 + ', ' + x2 + ' ' + y2;
    }
    
    path += ' L ' + first.xLeft + ' ' + (first.yBottom + padding);
    path += ' Z';
    
    return path;
  };
  
  const innerPath = buildPath(stageGeometry, 0);
  const haloPath = buildPath(stageGeometry, 14);
  const outerHaloPath = buildPath(stageGeometry, 28);
  
  return (
    <svg
      viewBox={'0 0 ' + VIEWBOX_W + ' ' + VIEWBOX_H}
      preserveAspectRatio="xMidYMid meet"
      style={{ width: '100%', height: 'auto', display: 'block' }}
    >
      <defs>
        <linearGradient id="funnelMain" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="#7DA8F8" />
          <stop offset="100%" stopColor="#4285F4" />
        </linearGradient>
        <linearGradient id="funnelHaloInner" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="#A8C5F9" stopOpacity="0.5" />
          <stop offset="100%" stopColor="#6E9CF7" stopOpacity="0.5" />
        </linearGradient>
        <linearGradient id="funnelHaloOuter" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="#C5D8FB" stopOpacity="0.32" />
          <stop offset="100%" stopColor="#A2BEFA" stopOpacity="0.32" />
        </linearGradient>
      </defs>
      
      {/* Stage hover background tint - sits behind everything */}
      {stageGeometry.map((s) => {
        const isActive = hoveredStage === s.id;
        return (
          <rect
            key={s.id + '-bg'}
            x={s.xLeft}
            y={0}
            width={s.xRight - s.xLeft}
            height={VIEWBOX_H}
            fill={isActive ? 'rgba(22, 22, 22, 0.045)' : 'transparent'}
            pointerEvents="none"
            style={{ transition: 'fill 0.15s' }}
          />
        );
      })}
      
      {/* Three layered bands for depth */}
      <path d={outerHaloPath} fill="url(#funnelHaloOuter)" />
      <path d={haloPath} fill="url(#funnelHaloInner)" />
      <path d={innerPath} fill="url(#funnelMain)" />
      
      {/* Percentage chips centered on each stage's visible band centerline,
          all on the same horizontal axis (CENTER_Y) so they read consistently */}
      {stageGeometry.map((s, i) => {
        const pctText = formatFunnelRate(s.cumPct);
        const charWidth = 7.5;
        const chipPadX = 12;
        const chipW = Math.max(46, pctText.length * charWidth + chipPadX * 2);
        const chipH = 24;
        const chipCenterX = stageBandCenters[i];
        const chipX = chipCenterX - chipW / 2;
        const chipY = CENTER_Y - chipH / 2;
        
        return (
          <g key={s.id + '-pct'} pointerEvents="none">
            <rect
              x={chipX}
              y={chipY}
              width={chipW}
              height={chipH}
              rx={12}
              fill="rgba(22, 22, 22, 0.85)"
            />
            <text
              x={chipCenterX}
              y={chipY + chipH / 2 + 4}
              textAnchor="middle"
              style={{
                fontSize: '12px',
                fontWeight: 600,
                fill: '#FFFFFF',
                fontFamily: fontStack,
                fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.005em'
              }}
            >
              {pctText}
            </text>
          </g>
        );
      })}
      
      {/* Footer: stacked label + value below the funnel, centered on band */}
      {stageGeometry.map((s, i) => {
        const isActive = hoveredStage === s.id;
        const labelCenterX = stageBandCenters[i];
        const labelY = VIEWBOX_H - FOOTER_H + 64;
        const valueY = VIEWBOX_H - FOOTER_H + 92;
        return (
          <g key={s.id + '-footer'} pointerEvents="none">
            <text
              x={labelCenterX}
              y={labelY}
              textAnchor="middle"
              style={{
                fontSize: '12px',
                fontWeight: 500,
                fill: isActive ? t.textPrimary : t.textTertiary,
                fontFamily: fontStack,
                letterSpacing: '0.01em',
                transition: 'fill 0.15s'
              }}
            >
              {s.label}
            </text>
            <text
              x={labelCenterX}
              y={valueY}
              textAnchor="middle"
              style={{
                fontSize: '20px',
                fontWeight: 600,
                fill: t.textPrimary,
                fontFamily: fontStack,
                fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.015em'
              }}
            >
              {formatFunnelCount(s.total)}
            </text>
          </g>
        );
      })}
      
      {/* Interaction zones - rendered last so they sit on top */}
      {stageGeometry.map((s) => (
        <rect
          key={s.id + '-zone'}
          x={s.xLeft}
          y={0}
          width={s.xRight - s.xLeft}
          height={VIEWBOX_H}
          fill="transparent"
          style={{ cursor: 'pointer' }}
          onMouseEnter={() => onStageEnter(s.id)}
          onMouseLeave={onStageLeave}
        />
      ))}
    </svg>
  );
}
// ============= FUNNEL STAGE POPUP =============
function FunnelStagePopup({ stage, conversionFromPrev, stageIndex, totalStages, onEnter, onLeave }) {
  // Position popup above the funnel, with edge clamping so it always fits inside the card.
  // The popup container wrapper has margin: 0 -28px (extends past card edges).
  // We inset 28px to align with card content area, plus 4px breathing room.
  const POPUP_W = 360;
  const isFirst = stageIndex === 0;
  const isLast = stageIndex === totalStages - 1;
  
  // Position style: anchor first to left, last to right, middle stages centered on stage.
  let positionStyle;
  if (isFirst) {
    positionStyle = { left: '32px' };
  } else if (isLast) {
    positionStyle = { right: '32px' };
  } else {
    const stagePctCenter = ((stageIndex + 0.5) / totalStages) * 100;
    positionStyle = { left: stagePctCenter + '%', transform: 'translateX(-50%)' };
  }
  
  return (
    <div
      onMouseEnter={onEnter}
      onMouseLeave={onLeave}
      style={{
        position: 'absolute',
        bottom: 'calc(100% + 12px)',
        ...positionStyle,
        width: POPUP_W + 'px',
        maxWidth: 'calc(100% - 64px)',
        background: t.bgPrimary,
        borderRadius: '12px',
        boxShadow: '0 12px 32px rgba(22, 22, 22, 0.18), 0 0 0 1px rgba(22, 22, 22, 0.06)',
        padding: '18px 20px',
        zIndex: 10
      }}
    >
      <div style={{ marginBottom: '12px' }}>
        <div style={{ fontSize: '11px', fontWeight: 600, color: t.textTertiary, marginBottom: '2px', letterSpacing: '0.02em' }}>
          {stage.label}
        </div>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px', marginBottom: '4px' }}>
          <span style={{ fontSize: '22px', fontWeight: 600, color: t.textPrimary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.015em' }}>
            {formatFunnelCount(stage.total)}
          </span>
          {conversionFromPrev && (
            <span style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500 }}>
              {formatFunnelRate(conversionFromPrev.rate)} from previous
            </span>
          )}
        </div>
        <div style={{ fontSize: '12px', color: t.textSecondary, lineHeight: 1.5 }}>
          {stage.sublabel}
        </div>
      </div>
      
      {/* Sales / Service split */}
      {(stage.sales > 0 || stage.service > 0) && (
        <div style={{ marginBottom: '14px' }}>
          {(() => {
            const total = stage.sales + stage.service;
            const salesPct = total > 0 ? (stage.sales / total) * 100 : 0;
            const servicePct = total > 0 ? (stage.service / total) * 100 : 0;
            return (
              <>
                <div style={{
                  display: 'flex',
                  height: '6px',
                  borderRadius: '3px',
                  overflow: 'hidden',
                  marginBottom: '8px'
                }}>
                  <div style={{ width: salesPct + '%', height: '100%', background: t.accent }} />
                  <div style={{ width: servicePct + '%', height: '100%', background: t.textTertiary }} />
                </div>
                <div style={{ display: 'flex', gap: '16px', fontSize: '11px', flexWrap: 'wrap' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <div style={{ width: '7px', height: '7px', borderRadius: '50%', background: t.accent }} />
                    <span style={{ color: t.textPrimary, fontWeight: 500 }}>Sales</span>
                    <span style={{ color: t.textPrimary, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>{formatFunnelCount(stage.sales)}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <div style={{ width: '7px', height: '7px', borderRadius: '50%', background: t.textTertiary }} />
                    <span style={{ color: t.textPrimary, fontWeight: 500 }}>Service</span>
                    <span style={{ color: t.textPrimary, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>{formatFunnelCount(stage.service)}</span>
                  </div>
                </div>
              </>
            );
          })()}
        </div>
      )}
      
      {/* Contributors */}
      <div>
        <div style={{ fontSize: '11px', fontWeight: 600, color: t.textTertiary, marginBottom: '8px', letterSpacing: '0.02em' }}>
          Contributors
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          {stage.contributors.map((c, i) => {
            const pct = (c.count / stage.total) * 100;
            return (
              <div key={i} style={{
                display: 'grid',
                gridTemplateColumns: '1fr auto auto',
                gap: '12px',
                alignItems: 'baseline',
                fontSize: '12px',
                paddingTop: '4px',
                paddingBottom: '4px'
              }}>
                <span style={{ color: t.textSecondary, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {c.name}
                </span>
                <span style={{ color: t.textPrimary, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
                  {formatFunnelCount(c.count)}
                </span>
                <span style={{ color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', fontSize: '11px', minWidth: '36px', textAlign: 'right' }}>
                  {Math.round(pct)}%
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ============= HOME / ACTIVITY =============
function HomeActivity({ onDiscuss }) {
  const [areaFilter, setAreaFilter] = useState('all');
  const [typeFilter, setTypeFilter] = useState('all');
  const [showOlder, setShowOlder] = useState(false);

  const log = [
    // Today
    { time: '7:14 AM', day: 'today', action: 'Optimized Google bid strategy across 14 campaigns based on weekend conversion patterns', type: 'autonomous', area: 'Campaigns', icon: Megaphone, undoable: true },
    { time: '6:42 AM', day: 'today', action: 'Refreshed lease-end audience with 23 new equity matches', type: 'autonomous', area: 'Audiences', icon: Users, undoable: true },
    { time: '6:15 AM', day: 'today', action: 'Tested 4 new creative variants for Spring Service Special, top performer at +23% CTR', type: 'autonomous', area: 'Creative', icon: ImageIcon, undoable: false },
    { time: '5:48 AM', day: 'today', action: 'Suppressed 847 customers from outreach, recent complaints filter', type: 'autonomous', area: 'Audiences', icon: Users, undoable: true },
    // Yesterday
    { time: '8:31 PM', day: 'yesterday', action: 'You approved: Shift $18K to lease-end campaign', type: 'approved', area: 'Campaigns', icon: Megaphone, undoable: false },
    { time: '4:02 PM', day: 'yesterday', action: 'Paused Civic conquest campaign, CPA breached threshold', type: 'policy', area: 'Campaigns', icon: Megaphone, undoable: true },
    { time: '2:18 PM', day: 'yesterday', action: 'You declined: Black Friday flash sale on used inventory', type: 'declined', area: 'Strategy', icon: Compass, undoable: false },
    { time: '11:00 AM', day: 'yesterday', action: 'Negotiated $127K in OEM co-op claims with regional offices', type: 'autonomous', area: 'Co-Op', icon: Award, undoable: false },
    { time: '9:14 AM', day: 'yesterday', action: 'You overrode: Reactivated Civic awareness campaign in 3 zips', type: 'override', area: 'Campaigns', icon: Megaphone, undoable: true },
    // Older
    { time: '6:30 PM', day: 'two_days', action: 'Generated weekly performance report for ownership', type: 'autonomous', area: 'Reporting', icon: FileCheck, undoable: false },
    { time: '3:45 PM', day: 'two_days', action: 'Adjusted email send time for service reminders based on engagement data', type: 'autonomous', area: 'Journeys', icon: Route, undoable: true },
    { time: '11:20 AM', day: 'two_days', action: 'Triggered 47 review requests post-service appointment', type: 'autonomous', area: 'Reputation', icon: Star, undoable: false }
  ];

  const typeStyle = {
    autonomous: { color: t.success, label: 'Autonomous' },
    approved: { color: t.accent, label: 'Approved' },
    declined: { color: t.warning, label: 'Declined' },
    override: { color: t.textSecondary, label: 'Override' },
    policy: { color: t.warning, label: 'Policy stop' }
  };

  const dayLabel = {
    today: 'Today',
    yesterday: 'Yesterday',
    two_days: 'Two days ago'
  };

  const areaFilters = ['all', 'Campaigns', 'Audiences', 'Creative', 'Journeys', 'Co-Op', 'Reputation', 'Strategy'];
  const typeFilters = ['all', 'autonomous', 'approved', 'declined', 'override', 'policy'];

  const filtered = log.filter(e => {
    if (areaFilter !== 'all' && e.area !== areaFilter) return false;
    if (typeFilter !== 'all' && e.type !== typeFilter) return false;
    if (!showOlder && e.day === 'two_days') return false;
    return true;
  });

  // Group by day
  const grouped = {};
  filtered.forEach(e => {
    if (!grouped[e.day]) grouped[e.day] = [];
    grouped[e.day].push(e);
  });

  return (
    <div>
      <p style={{ fontSize: '15px', color: t.textSecondary, marginTop: 0, marginBottom: '20px', maxWidth: '720px', lineHeight: 1.55 }}>
        Every action AI took. Filter by area or type. Click discuss on any item to ask why, give feedback, or undo.
      </p>

      {/* Filters */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '24px', flexWrap: 'wrap' }}>
        <FilterDropdown
          label="Area"
          value={areaFilter}
          onChange={setAreaFilter}
          options={[
            { value: 'all', label: 'All areas' },
            ...areaFilters.filter(a => a !== 'all').map(a => ({ value: a, label: a }))
          ]}
        />
        <FilterDropdown
          label="Type"
          value={typeFilter}
          onChange={setTypeFilter}
          options={[
            { value: 'all', label: 'All types' },
            ...typeFilters.filter(tf => tf !== 'all').map(tf => ({ value: tf, label: typeStyle[tf]?.label || tf }))
          ]}
        />
      </div>

      {/* Activity log grouped by day */}
      {Object.entries(grouped).map(([day, entries]) => (
        <div key={day} style={{ marginBottom: '24px' }}>
          <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 600, marginBottom: '8px', paddingLeft: '4px' }}>
            {dayLabel[day]}
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {entries.map((entry, i) => {
              const ts = typeStyle[entry.type];
              return (
                <Discussable
                  key={i}
                  label={entry.action}
                  prefilledQuestion={`Why did you do this: ${entry.action}`}
                  onDiscuss={onDiscuss}
                  style={{ borderRadius: '10px' }}
                >
                  <div style={{
                    padding: '12px 16px',
                    background: t.surface,
                    borderRadius: '10px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '14px'
                  }}>
                    {/* Icon + area, grouped on the left */}
                    <div style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '10px',
                      flexShrink: 0,
                      minWidth: '120px'
                    }}>
                      <div style={{
                        width: '28px', height: '28px', borderRadius: '7px',
                        background: t.surfaceMuted,
                        display: 'flex', alignItems: 'center', justifyContent: 'center'
                      }}>
                        <entry.icon size={13} color={t.textSecondary} strokeWidth={1.75} />
                      </div>
                      <span style={{ fontSize: '12px', color: t.textSecondary, fontWeight: 500 }}>
                        {entry.area}
                      </span>
                    </div>
                    
                    {/* Activity description in the middle */}
                    <div style={{ flex: 1, fontSize: '13px', color: t.textPrimary, lineHeight: 1.5, minWidth: 0 }}>
                      {entry.action}
                    </div>
                    
                    {/* Type · Time, right aligned, plain text */}
                    <div style={{ fontSize: '12px', color: t.textTertiary, flexShrink: 0, fontWeight: 500 }}>
                      {ts.label} · {entry.time}
                    </div>
                  </div>
                </Discussable>
              );
            })}
          </div>
        </div>
      ))}

      {filtered.length === 0 && (
        <div style={{ padding: '40px', background: t.surface, borderRadius: '12px', textAlign: 'center', color: t.textTertiary, fontSize: '14px' }}>
          No activity matches these filters.
        </div>
      )}

      {!showOlder && (
        <button
          onClick={() => setShowOlder(true)}
          style={{
            marginTop: '8px',
            padding: '10px 14px',
            background: 'transparent',
            color: t.accent,
            border: 'none',
            borderRadius: '8px',
            fontSize: '13px',
            fontWeight: 600,
            cursor: 'pointer',
            fontFamily: fontStack,
            display: 'flex',
            alignItems: 'center',
            gap: '6px'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.accentSoft}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          Show earlier activity <ChevronDown size={14} />
        </button>
      )}
    </div>
  );
}



// ============= STRATEGY VIEW =============
function StrategyView({ cohort, isTablet, isSmall, onDiscuss, activeSheet, setActiveSheet, panelOpen, askMessages, askInput, setAskInput, handlePanelSend, handlePanelClose, discussContext, navOrigin, restoreNavOrigin }) {
  const sourcesSheetOpen = activeSheet === 'sources';
  
  const objectivesOpen = activeSheet === 'objectives';
  const budgetOpen = activeSheet === 'budget';
  
  // Sheet close handler that respects cross-page nav origin. When the user
  // landed on Plan-with-sheet via an approval card from Home (or elsewhere),
  // closing the sheet returns them to that origin instead of leaving them
  // stranded on Plan, which they never asked for.
  const closeSheet = () => {
    setActiveSheet(null);
    if (panelOpen) handlePanelClose();
    // If we have an origin captured, restore it. The sheet close becomes a
    // single back step that unwinds both the sheet AND the implicit nav to
    // Plan that came with it.
    if (restoreNavOrigin) restoreNavOrigin();
  };

  // Pacing summary (would come from real data in production)
  const pacing = {
    period: 'April',
    spent: 342000,
    budget: 360000,
    status: 'on track' // or 'ahead', 'behind'
  };
  const pacingPct = Math.round((pacing.spent / pacing.budget) * 100);
  const pacingColor = pacing.status === 'on track' ? t.textSecondary :
                      pacing.status === 'ahead' ? t.warning : t.danger;

  return (
    <div>
      {/* Header */}
      <div style={{ marginBottom: '24px', display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '24px', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: '12px', color: t.textTertiary, marginBottom: '8px', fontWeight: 500 }}>
            Plan
          </div>
          <h1 style={{
            fontSize: isSmall ? '28px' : isTablet ? '32px' : '36px',
            fontWeight: 400, letterSpacing: '-0.02em', margin: 0,
            color: t.textPrimary, lineHeight: 1.15
          }}>
            What I am working on, and what is coming up.
          </h1>
          <p style={{ fontSize: '15px', color: t.textSecondary, marginTop: '12px', maxWidth: '720px', lineHeight: 1.55 }}>
            The temporal layout of your marketing across the next 10 weeks. I keep this in line with your objectives and budget. Edit either if the direction needs to shift.
          </p>
        </div>
      </div>

      {/* CTA strip: pacing summary + objectives / budget / sources */}
      <div style={{
        marginBottom: '20px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '16px',
        flexWrap: 'wrap'
      }}>
        {/* Pacing summary */}
        <div style={{
          fontSize: '13px',
          color: t.textSecondary,
          lineHeight: 1.5
        }}>
          <span style={{ color: t.textTertiary, fontWeight: 600, marginRight: '6px' }}>{pacing.period}:</span>
          <span style={{ color: t.textPrimary, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
            {formatMoneyShort(pacing.spent)}
          </span>
          <span style={{ color: t.textTertiary }}> of </span>
          <span style={{ color: t.textPrimary, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
            {formatMoneyShort(pacing.budget)}
          </span>
          <span style={{ color: t.textTertiary }}> spent ({pacingPct}%), </span>
          <span style={{ color: pacingColor, fontWeight: 600 }}>{pacing.status}</span>
        </div>
        
        {/* Action CTAs - icon + label, no "Edit" word */}
        <div style={{ display: 'flex', gap: '4px', flexShrink: 0 }}>
          <button
            onClick={() => setActiveSheet('objectives')}
            style={{
              display: 'flex', alignItems: 'center', gap: '6px',
              padding: '7px 12px',
              background: 'transparent', color: t.textSecondary,
              border: 'none', borderRadius: '8px',
              fontSize: '12px', fontWeight: 500, cursor: 'pointer',
              fontFamily: fontStack
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <Edit2 size={12} strokeWidth={2} />
            Objectives
          </button>
          <button
            onClick={() => setActiveSheet('budget')}
            style={{
              display: 'flex', alignItems: 'center', gap: '6px',
              padding: '7px 12px',
              background: 'transparent', color: t.textSecondary,
              border: 'none', borderRadius: '8px',
              fontSize: '12px', fontWeight: 500, cursor: 'pointer',
              fontFamily: fontStack
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <Edit2 size={12} strokeWidth={2} />
            Budget
          </button>
          <button
            onClick={() => setActiveSheet('sources')}
            style={{
              display: 'flex', alignItems: 'center', gap: '6px',
              padding: '7px 12px',
              background: 'transparent', color: t.textSecondary,
              border: 'none', borderRadius: '8px',
              fontSize: '12px', fontWeight: 500, cursor: 'pointer',
              fontFamily: fontStack
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <BookOpen size={12} strokeWidth={2} />
            Sources
          </button>
        </div>
      </div>

      <StrategyPlan isTablet={isTablet} isSmall={isSmall} onDiscuss={onDiscuss} />
      
      {sourcesSheetOpen && (
        <SourcesSheet onClose={() => setActiveSheet(null)} />
      )}
      
      {objectivesOpen && (
        <ObjectivesSheet
          onClose={closeSheet}
          onDiscuss={onDiscuss}
          panelOpen={panelOpen}
          askMessages={askMessages}
          askInput={askInput}
          setAskInput={setAskInput}
          handlePanelSend={handlePanelSend}
          handlePanelClose={handlePanelClose}
          discussContext={discussContext}
        />
      )}
      
      {budgetOpen && (
        <BudgetSheet
          onClose={closeSheet}
          onDiscuss={onDiscuss}
          panelOpen={panelOpen}
          askMessages={askMessages}
          askInput={askInput}
          setAskInput={setAskInput}
          handlePanelSend={handlePanelSend}
          handlePanelClose={handlePanelClose}
          discussContext={discussContext}
        />
      )}
    </div>
  );
}

// ============= OBJECTIVES SHEET =============
// Sheet shows objectives content with view + edit. Panel teleports inline
// when invoked - sheet expands to contain it. Footer has Save/Cancel.
function ObjectivesSheet({ onClose, onDiscuss, panelOpen, askMessages, askInput, setAskInput, handlePanelSend, handlePanelClose, discussContext }) {
  // Panel rendering inside sheet - expand sheet width when panel is open
  const SHEET_W_BASE = 720;
  const PANEL_W = 380;
  const totalWidth = panelOpen ? SHEET_W_BASE + PANEL_W : SHEET_W_BASE;
  
  return (
    <>
      <div
        onClick={onClose}
        style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(22,22,22,0.32)', backdropFilter: 'blur(4px)',
          zIndex: 200
        }}
      />
      <div style={{
        position: 'fixed', top: 0, right: 0, bottom: 0,
        width: totalWidth + 'px', maxWidth: '100vw',
        background: t.bgPrimary, zIndex: 201,
        boxShadow: '-8px 0 32px rgba(22,22,22,0.12)',
        display: 'flex', flexDirection: 'row',
        transition: 'width 0.2s ease-out'
      }}>
        {/* Sheet content column */}
        <div style={{
          width: SHEET_W_BASE + 'px',
          maxWidth: '100%',
          flexShrink: 0,
          display: 'flex',
          flexDirection: 'column',
          borderRight: panelOpen ? '1px solid ' + t.surfaceMuted : 'none'
        }}>
          {/* Header */}
          <div style={{
            padding: '24px 32px 16px',
            display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between',
            borderBottom: '1px solid ' + t.surfaceMuted
          }}>
            <div>
              <h2 style={{ fontSize: '20px', fontWeight: 600, margin: 0, color: t.textPrimary, letterSpacing: '-0.01em' }}>
                Objectives
              </h2>
              <div style={{ fontSize: '13px', color: t.textTertiary, marginTop: '4px', lineHeight: 1.5 }}>
                The direction I am working toward. Edit anything; I will adjust the plan.
              </div>
            </div>
            <button
              onClick={onClose}
              style={{
                background: 'transparent', border: 'none', color: t.textTertiary,
                cursor: 'pointer', padding: '6px', borderRadius: '8px', display: 'flex'
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              <X size={20} />
            </button>
          </div>

          {/* Content */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '24px 32px 32px' }}>
            <StrategyObjectives onDiscuss={onDiscuss} isTablet={true} isSmall={false} />
          </div>
          
          {/* Footer */}
          <div style={{
            padding: '16px 32px',
            borderTop: '1px solid ' + t.surfaceMuted,
            display: 'flex',
            justifyContent: 'flex-end',
            gap: '8px',
            background: t.bgPrimary
          }}>
            <button
              onClick={onClose}
              style={{
                padding: '9px 18px',
                background: 'transparent',
                color: t.textSecondary,
                border: 'none',
                borderRadius: '8px',
                fontSize: '13px',
                fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
            >
              Cancel
            </button>
            <button
              onClick={onClose}
              style={{
                padding: '9px 18px',
                background: t.accent,
                color: t.textOnColor,
                border: 'none',
                borderRadius: '8px',
                fontSize: '13px',
                fontWeight: 600,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = t.accentHover}
              onMouseLeave={(e) => e.currentTarget.style.background = t.accent}
            >
              Save changes
            </button>
          </div>
        </div>
        
        {/* Inline conversation panel when active */}
        {panelOpen && (
          <div style={{
            width: PANEL_W + 'px',
            flexShrink: 0,
            display: 'flex',
            flexDirection: 'column'
          }}>
            <DiscussPanelInline
              messages={askMessages}
              context={discussContext}
              input={askInput}
              setInput={setAskInput}
              onSend={() => { if (askInput.trim()) handlePanelSend(askInput); }}
              onClose={handlePanelClose}
            />
          </div>
        )}
      </div>
    </>
  );
}

// ============= BUDGET SHEET CONTENT =============
// View+edit on same surface. No nested sheets.
//
// Sections:
//   1. Annual envelope - read-only summary "$4.2M for the year ±8% flex"
//      Edit pencil opens an inline editor showing both the annual amount and
//      the flex slider. Both commit together.
//   2. Annual pacing strip - single horizontal bar "year-to-date spent vs annual"
//   3. Quarterly distribution + pacing - 4 cards, each with allocation, share,
//      and a thin pacing bar inside the card. Edit button puts
//      ALL quarter cards into edit mode at once with a running balance badge.
//   4. Monthly distribution + pacing - within active quarter. Edit-all pattern.
//   5. Channel allocation + pacing - same edit-all pattern.
// All three distribution sections support % | $ toggle.

const QUARTER_DEFINITIONS = {
  Q1: { months: ['Jan', 'Feb', 'Mar'], label: 'Q1 2026' },
  Q2: { months: ['Apr', 'May', 'Jun'], label: 'Q2 2026' },
  Q3: { months: ['Jul', 'Aug', 'Sep'], label: 'Q3 2026' },
  Q4: { months: ['Oct', 'Nov', 'Dec'], label: 'Q4 2026' }
};

// Per-month spent figures (for pacing). Q1 done, Q2 in progress, Q3+ haven't started.
const MONTHLY_SPENT = {
  Jan: 358000, Feb: 348000, Mar: 374000,
  Apr: 342000, May: 70000, Jun: 0,
  Jul: 0, Aug: 0, Sep: 0,
  Oct: 0, Nov: 0, Dec: 0
};

function BudgetSheetContent({ onDiscuss }) {
  // Annual + flex
  const [annualTotal, setAnnualTotal] = useState(BUDGET_SEED.totalAnnual);
  const [flexPct, setFlexPct] = useState(8);
  const [editingAnnual, setEditingAnnual] = useState(false);
  const [annualDraft, setAnnualDraft] = useState(annualTotal);
  const [flexDraft, setFlexDraft] = useState(flexPct);
  
  // Active quarter for monthly section
  const [activeQuarter, setActiveQuarter] = useState('Q2');
  const [showFullYear, setShowFullYear] = useState(false);
  
  // Quarterly distribution (% of annual)
  const initialQuarterlyPct = (() => {
    const total = Object.values(BUDGET_SEED.quarterlyDistribution).reduce((a, b) => a + b, 0);
    const out = {};
    Object.entries(BUDGET_SEED.quarterlyDistribution).forEach(([q, v]) => {
      out[q] = Math.round((v / total) * 1000) / 10;
    });
    return out;
  })();
  const [quarterlyPct, setQuarterlyPct] = useState(initialQuarterlyPct);
  const [quarterlyMode, setQuarterlyMode] = useState('flat');
  const [editingQuarterly, setEditingQuarterly] = useState(false);
  const [quarterlyDraft, setQuarterlyDraft] = useState(initialQuarterlyPct);
  
  // Monthly distribution (% within each quarter)
  const initialMonthlyPct = {
    Q1: { Jan: 30, Feb: 33, Mar: 37 },
    Q2: { Apr: 33, May: 33, Jun: 34 },
    Q3: { Jul: 32, Aug: 33, Sep: 35 },
    Q4: { Oct: 28, Nov: 32, Dec: 40 }
  };
  const [monthlyPct, setMonthlyPct] = useState(initialMonthlyPct);
  const [monthlyMode, setMonthlyMode] = useState('flat');
  const [editingMonthly, setEditingMonthly] = useState(false);
  const [monthlyDraft, setMonthlyDraft] = useState(initialMonthlyPct);
  
  // Channel allocation
  const totalBudgeted = CHANNELS_SEED.reduce((sum, ch) => sum + ch.budgeted, 0);
  const initialChannels = CHANNELS_SEED.map(ch => ({
    id: ch.id,
    name: ch.name,
    spent: ch.spent,
    pct: Math.round((ch.budgeted / totalBudgeted) * 1000) / 10
  }));
  const [channels, setChannels] = useState(initialChannels);
  const [channelsMode, setChannelsMode] = useState('flat');
  const [editingChannels, setEditingChannels] = useState(false);
  const [channelsDraft, setChannelsDraft] = useState(initialChannels);
  
  // Derived values
  const flexAmount = Math.round((annualTotal * flexPct) / 100);
  const flexLow = annualTotal - flexAmount;
  const flexHigh = annualTotal + flexAmount;
  
  const quarterlyDollars = (q, useDraft = false) => {
    const src = useDraft ? quarterlyDraft : quarterlyPct;
    return Math.round((src[q] / 100) * annualTotal);
  };
  
  const monthlyDollars = (q, m, useDraft = false) => {
    const src = useDraft ? monthlyDraft : monthlyPct;
    return Math.round((src[q][m] / 100) * quarterlyDollars(q));
  };
  
  const channelDollars = (pct) => Math.round((pct / 100) * annualTotal);
  
  // Annual+flex edit
  const handleAnnualEdit = () => {
    setAnnualDraft(annualTotal);
    setFlexDraft(flexPct);
    setEditingAnnual(true);
  };
  const handleAnnualSave = () => {
    setAnnualTotal(annualDraft);
    setFlexPct(flexDraft);
    setEditingAnnual(false);
  };
  const handleAnnualCancel = () => {
    setEditingAnnual(false);
  };
  
  // Quarterly bulk edit
  const handleQuarterlyEdit = () => {
    setQuarterlyDraft({ ...quarterlyPct });
    setEditingQuarterly(true);
  };
  const handleQuarterlySave = () => {
    setQuarterlyPct({ ...quarterlyDraft });
    setEditingQuarterly(false);
  };
  const handleQuarterlyCancel = () => {
    setEditingQuarterly(false);
  };
  
  const quarterlySum = Object.values(quarterlyDraft).reduce((a, b) => a + b, 0);
  const quarterlyImbalance = quarterlySum - 100;
  
  // Monthly bulk edit
  const handleMonthlyEdit = () => {
    setMonthlyDraft(JSON.parse(JSON.stringify(monthlyPct)));
    setEditingMonthly(true);
  };
  const handleMonthlySave = () => {
    setMonthlyPct(JSON.parse(JSON.stringify(monthlyDraft)));
    setEditingMonthly(false);
  };
  const handleMonthlyCancel = () => {
    setEditingMonthly(false);
  };
  
  const monthlySumForActive = Object.values(monthlyDraft[activeQuarter] || {}).reduce((a, b) => a + b, 0);
  const monthlyImbalance = monthlySumForActive - 100;
  
  // Channels bulk edit
  const handleChannelsEdit = () => {
    setChannelsDraft(channels.map(c => ({ ...c })));
    setEditingChannels(true);
  };
  const handleChannelsSave = () => {
    setChannels(channelsDraft.map(c => ({ ...c })));
    setEditingChannels(false);
  };
  const handleChannelsCancel = () => {
    setEditingChannels(false);
  };
  
  const channelsSum = channelsDraft.reduce((a, c) => a + c.pct, 0);
  const channelsImbalance = channelsSum - 100;
  
  // Annual pacing - sum spent across all months
  const totalSpent = Object.values(MONTHLY_SPENT).reduce((a, b) => a + b, 0);
  const annualPacePct = annualTotal > 0 ? (totalSpent / annualTotal) * 100 : 0;
  
  return (
    <div>
      {/* ============================================================ */}
      {/* SECTION 1: ANNUAL ENVELOPE                                    */}
      {/* ============================================================ */}
      <div style={{ marginBottom: '32px' }}>
        <div style={{ fontSize: '11px', fontWeight: 600, color: t.textTertiary, marginBottom: '8px', letterSpacing: '0.02em' }}>
          2026 annual budget
        </div>
        
        {!editingAnnual ? (
          <>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', flexWrap: 'wrap' }}>
              <div style={{
                fontSize: '36px', fontWeight: 600, color: t.textPrimary,
                fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.02em', lineHeight: 1
              }}>
                {formatMoneyShort(annualTotal)}
              </div>
              <div style={{ fontSize: '13px', color: t.textTertiary }}>
                ±{flexPct}% flex
              </div>
              <button
                onClick={handleAnnualEdit}
                style={{
                  background: 'transparent', border: 'none',
                  cursor: 'pointer', padding: '4px 6px', borderRadius: '6px',
                  display: 'flex', alignItems: 'center',
                  color: t.textTertiary
                }}
                onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textSecondary; }}
                onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textTertiary; }}
              >
                <Edit2 size={14} strokeWidth={2} />
              </button>
            </div>
            
            {/* Annual pacing strip */}
            <div style={{ marginTop: '16px' }}>
              <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: '6px' }}>
                <div style={{
                  fontSize: '11px', color: t.textTertiary, fontWeight: 500
                }}>
                  Year-to-date
                </div>
                <div style={{
                  fontSize: '11px', color: t.textTertiary,
                  fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
                }}>
                  <span style={{ color: t.textPrimary, fontWeight: 600 }}>{formatMoneyShort(totalSpent)}</span>
                  <span> of {formatMoneyShort(annualTotal)} ({Math.round(annualPacePct)}%)</span>
                </div>
              </div>
              <div style={{
                height: '4px',
                background: t.surfaceMuted,
                borderRadius: '2px',
                overflow: 'hidden'
              }}>
                <div style={{
                  width: Math.min(100, annualPacePct) + '%',
                  height: '100%',
                  background: t.accent
                }} />
              </div>
            </div>
          </>
        ) : (
          <AnnualEditor
            annualDraft={annualDraft}
            setAnnualDraft={setAnnualDraft}
            flexDraft={flexDraft}
            setFlexDraft={setFlexDraft}
            onSave={handleAnnualSave}
            onCancel={handleAnnualCancel}
          />
        )}
      </div>
      

      {/* ============================================================ */}
      {/* SECTION 2: CHANNEL ALLOCATION                                */}
      {/* ============================================================ */}
      <div style={{ marginBottom: '32px', paddingTop: '20px', borderTop: '1px solid ' + t.surfaceMuted }}>
        <SectionHeader
          title="Channel allocation"
          subtitle="How the annual budget splits across channels"
          mode={channelsMode}
          setMode={setChannelsMode}
          isEditing={editingChannels}
          onEdit={handleChannelsEdit}
          onSave={handleChannelsSave}
          onCancel={handleChannelsCancel}
          imbalance={channelsImbalance}
          imbalanceUnit="%"
        />
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          {(editingChannels ? channelsDraft : channels).map((ch, i) => {
            const chDollars = Math.round((ch.pct / 100) * annualTotal);
            const cell = (
              <ChannelRowV2
                key={ch.id}
                channel={ch}
                isEditing={editingChannels}
                mode={channelsMode}
                onPctChange={(newPct) => {
                  setChannelsDraft(prev => prev.map((c, idx) => idx === i ? { ...c, pct: newPct } : c));
                }}
                annualTotal={annualTotal}
              />
            );
            if (editingChannels) return <div key={ch.id}>{cell}</div>;
            return (
              <Discussable
                key={ch.id}
                label={ch.name}
                prefilledQuestion={'Why does ' + ch.name + ' get ' + ch.pct.toFixed(1) + '% (' + formatMoneyShort(chDollars) + ')? Is this the right allocation?'}
                onDiscuss={onDiscuss}
              >
                {cell}
              </Discussable>
            );
          })}
        </div>
      </div>
      
      {/* ============================================================ */}
      {/* SECTION 3: QUARTERLY DISTRIBUTION + PACING                    */}
      {/* ============================================================ */}
      <div style={{ marginBottom: '32px', paddingTop: '20px', borderTop: '1px solid ' + t.surfaceMuted }}>
        <SectionHeader
          title="Quarterly distribution"
          subtitle="How the annual budget flows across the four quarters"
          mode={quarterlyMode}
          setMode={setQuarterlyMode}
          isEditing={editingQuarterly}
          onEdit={handleQuarterlyEdit}
          onSave={handleQuarterlySave}
          onCancel={handleQuarterlyCancel}
          imbalance={quarterlyImbalance}
          imbalanceUnit="%"
        />
        
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '10px' }}>
          {['Q1', 'Q2', 'Q3', 'Q4'].map(q => {
            const qDollars = Math.round(((editingQuarterly ? quarterlyDraft[q] : quarterlyPct[q]) / 100) * annualTotal);
            const qPct = editingQuarterly ? quarterlyDraft[q] : quarterlyPct[q];
            const cell = (
              <QuarterCell
                key={q}
                quarterId={q}
                isCurrent={q === 'Q2'}
                isActive={activeQuarter === q}
                onClick={() => !editingQuarterly && setActiveQuarter(q)}
                pct={qPct}
                dollars={qDollars}
                spent={BUDGET_SEED.spentQuarterly[q]}
                mode={quarterlyMode}
                isEditing={editingQuarterly}
                onPctChange={(newPct) => setQuarterlyDraft(prev => ({ ...prev, [q]: newPct }))}
                annualTotal={annualTotal}
              />
            );
            if (editingQuarterly) return <div key={q}>{cell}</div>;
            return (
              <Discussable
                key={q}
                label={q + ' allocation'}
                prefilledQuestion={'Why does ' + q + ' have ' + qPct.toFixed(1) + '% (' + formatMoneyShort(qDollars) + ') of the annual budget?'}
                onDiscuss={onDiscuss}
              >
                {cell}
              </Discussable>
            );
          })}
        </div>
      </div>
      
      {/* ============================================================ */}
      {/* SECTION 4: MONTHLY DISTRIBUTION + PACING                      */}
      {/* ============================================================ */}
      <div style={{ marginBottom: '32px', paddingTop: '20px', borderTop: '1px solid ' + t.surfaceMuted }}>
        <SectionHeader
          title={'Monthly distribution within ' + QUARTER_DEFINITIONS[activeQuarter].label}
          subtitle={'How ' + QUARTER_DEFINITIONS[activeQuarter].label + ' breaks down across months. Click another quarter above to switch.'}
          mode={monthlyMode}
          setMode={setMonthlyMode}
          isEditing={editingMonthly}
          onEdit={handleMonthlyEdit}
          onSave={handleMonthlySave}
          onCancel={handleMonthlyCancel}
          imbalance={monthlyImbalance}
          imbalanceUnit="%"
        />
        
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px' }}>
          {QUARTER_DEFINITIONS[activeQuarter].months.map(m => {
            const pct = editingMonthly ? monthlyDraft[activeQuarter][m] : monthlyPct[activeQuarter][m];
            const qDollars = quarterlyDollars(activeQuarter);
            const dollars = Math.round((pct / 100) * qDollars);
            const cell = (
              <MonthCellV2
                key={m}
                monthName={m}
                pct={pct}
                dollars={dollars}
                spent={MONTHLY_SPENT[m] || 0}
                mode={monthlyMode}
                isEditing={editingMonthly}
                onPctChange={(newPct) => setMonthlyDraft(prev => ({
                  ...prev,
                  [activeQuarter]: { ...prev[activeQuarter], [m]: newPct }
                }))}
                quarterDollars={qDollars}
              />
            );
            if (editingMonthly) return <div key={m}>{cell}</div>;
            return (
              <Discussable
                key={m}
                label={m + ' allocation'}
                prefilledQuestion={'Why does ' + m + ' have ' + pct.toFixed(1) + '% (' + formatMoneyShort(dollars) + ') of ' + activeQuarter + '?'}
                onDiscuss={onDiscuss}
              >
                {cell}
              </Discussable>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ----- Annual editor (annual amount + flex slider in one edit context) -----
function AnnualEditor({ annualDraft, setAnnualDraft, flexDraft, setFlexDraft, onSave, onCancel }) {
  const flexAmount = Math.round((annualDraft * flexDraft) / 100);
  const flexLow = annualDraft - flexAmount;
  const flexHigh = annualDraft + flexAmount;
  
  return (
    <div style={{
      padding: '20px',
      background: t.surface,
      borderRadius: '12px'
    }}>
      {/* Two inputs side by side */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: '1fr 140px',
        gap: '14px',
        marginBottom: '16px'
      }}>
        {/* Annual amount */}
        <div>
          <div style={{ fontSize: '11px', fontWeight: 600, color: t.textTertiary, marginBottom: '6px', letterSpacing: '0.02em' }}>
            Annual budget
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
            <span style={{ fontSize: '16px', fontWeight: 600, color: t.textTertiary }}>$</span>
            <input
              type="number"
              value={annualDraft}
              onChange={(e) => setAnnualDraft(Number(e.target.value))}
              autoFocus
              style={{
                fontSize: '20px', fontWeight: 600, color: t.textPrimary,
                fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.01em',
                border: '1px solid ' + t.surfaceMuted,
                background: t.bgPrimary,
                padding: '8px 12px',
                borderRadius: '8px',
                width: '100%',
                outline: 'none',
                boxSizing: 'border-box'
              }}
              onKeyDown={(e) => { if (e.key === 'Enter') onSave(); if (e.key === 'Escape') onCancel(); }}
            />
          </div>
        </div>
        
        {/* Flex */}
        <div>
          <div style={{ fontSize: '11px', fontWeight: 600, color: t.textTertiary, marginBottom: '6px', letterSpacing: '0.02em' }}>
            Flex
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
            <span style={{ fontSize: '16px', fontWeight: 600, color: t.textTertiary }}>±</span>
            <input
              type="number"
              value={flexDraft}
              min="0" max="25"
              onChange={(e) => setFlexDraft(Math.max(0, Math.min(25, Number(e.target.value))))}
              style={{
                fontSize: '20px', fontWeight: 600, color: t.textPrimary,
                fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.01em',
                border: '1px solid ' + t.surfaceMuted,
                background: t.bgPrimary,
                padding: '8px 8px',
                borderRadius: '8px',
                width: '100%',
                outline: 'none',
                boxSizing: 'border-box'
              }}
              onKeyDown={(e) => { if (e.key === 'Enter') onSave(); if (e.key === 'Escape') onCancel(); }}
            />
            <span style={{ fontSize: '14px', fontWeight: 600, color: t.textTertiary, marginLeft: '2px' }}>%</span>
          </div>
        </div>
      </div>
      
      {/* Small visual cue: low / center / high band */}
      <div style={{ marginBottom: '20px' }}>
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginBottom: '6px',
          fontSize: '11px',
          color: t.textTertiary,
          fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
        }}>
          <span>{formatMoneyShort(flexLow)}</span>
          <span style={{ color: t.textPrimary, fontWeight: 600 }}>{formatMoneyShort(annualDraft)}</span>
          <span>{formatMoneyShort(flexHigh)}</span>
        </div>
        <div style={{
          position: 'relative',
          height: '6px',
          background: t.surfaceMuted,
          borderRadius: '3px',
          overflow: 'visible'
        }}>
          {/* Filled flex band: gradient is darkest at center (cap) and fades to nothing at flex bounds */}
          <div style={{
            position: 'absolute',
            left: '0', top: '0', bottom: '0',
            width: '100%',
            background: 'linear-gradient(to right, ' + t.accent + '00 0%, ' + t.accent + ' 50%, ' + t.accent + '00 100%)',
            borderRadius: '3px'
          }} />
        </div>
        <div style={{ fontSize: '11px', color: t.textTertiary, marginTop: '10px', lineHeight: 1.5 }}>
          I can shift up to <strong style={{ color: t.textPrimary, fontWeight: 600 }}>{formatMoneyShort(flexAmount)}</strong> above or below the cap on my own. Beyond this, I will pause and ask.
        </div>
      </div>
      
      {/* Actions */}
      <div style={{ display: 'flex', gap: '6px', justifyContent: 'flex-end' }}>
        <button
          onClick={onCancel}
          style={{
            padding: '7px 14px', background: 'transparent', color: t.textSecondary,
            border: 'none', borderRadius: '6px', fontSize: '12px', fontWeight: 500,
            cursor: 'pointer', fontFamily: fontStack
          }}
        >
          Cancel
        </button>
        <button
          onClick={onSave}
          style={{
            padding: '7px 14px', background: t.accent, color: t.textOnColor,
            border: 'none', borderRadius: '6px', fontSize: '12px', fontWeight: 600,
            cursor: 'pointer', fontFamily: fontStack
          }}
        >
          Save
        </button>
      </div>
    </div>
  );
}

// ----- Section header with mode toggle and edit/save/cancel + balance badge -----
function SectionHeader({ title, subtitle, mode, setMode, isEditing, onEdit, onSave, onCancel, imbalance, imbalanceUnit }) {
  // imbalance: number; +X means over, -X means under, 0 is balanced
  const imbalanceAbs = Math.abs(imbalance);
  const isBalanced = imbalanceAbs < 0.05; // tolerance for rounding
  const imbalanceSign = imbalance > 0 ? '+' : '';
  const imbalanceColor = isBalanced ? t.success : (imbalance > 0 ? t.warning : t.danger);
  const imbalanceBg = isBalanced ? t.successSoft : (imbalance > 0 ? t.warningSoft : t.dangerSoft);
  const imbalanceLabel = isBalanced ? 'Balanced' : (imbalanceSign + (imbalanceUnit === '%' ? imbalanceAbs.toFixed(1) + '%' : imbalanceAbs.toString())) + (imbalance > 0 ? ' over' : ' under');
  
  return (
    <div style={{
      display: 'flex',
      alignItems: 'flex-start',
      justifyContent: 'space-between',
      marginBottom: '14px',
      gap: '12px',
      flexWrap: 'wrap'
    }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap', marginBottom: '2px' }}>
          <div style={{ fontSize: '13px', fontWeight: 600, color: t.textPrimary }}>
            {title}
          </div>
          {isEditing && (
            <span style={{
              fontSize: '12px',
              fontWeight: 600,
              color: imbalanceColor,
              fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
            }}>
              {imbalanceLabel}
            </span>
          )}
        </div>
        <div style={{ fontSize: '11px', color: t.textTertiary, lineHeight: 1.5 }}>
          {subtitle}
        </div>
      </div>
      
      <div style={{ display: 'flex', gap: '8px', flexShrink: 0, alignItems: 'center' }}>
        {/* Mode toggle - only when editing */}
        {isEditing && (
          <div style={{
            display: 'inline-flex',
            background: t.surface,
            borderRadius: '8px',
            padding: '2px',
            gap: '2px'
          }}>
            {[{ id: 'percentage', label: '%' }, { id: 'flat', label: '$' }].map(m => (
              <button
                key={m.id}
                onClick={() => setMode(m.id)}
                style={{
                  padding: '5px 14px',
                  background: mode === m.id ? t.bgPrimary : 'transparent',
                  color: mode === m.id ? t.textPrimary : t.textTertiary,
                  border: 'none', borderRadius: '6px',
                  fontSize: '12px', fontWeight: 600,
                  cursor: 'pointer', fontFamily: fontStack,
                  boxShadow: mode === m.id ? '0 1px 2px rgba(22,22,22,0.06)' : 'none'
                }}
              >
                {m.label}
              </button>
            ))}
          </div>
        )}
        
        {/* Edit / Save / Cancel */}
        {!isEditing ? (
          <button
            onClick={onEdit}
            style={{
              display: 'flex', alignItems: 'center', gap: '6px',
              padding: '6px 12px',
              background: 'transparent', color: t.textSecondary,
              border: 'none', borderRadius: '7px',
              fontSize: '12px', fontWeight: 500,
              cursor: 'pointer', fontFamily: fontStack
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <Edit2 size={12} strokeWidth={2} />
            Edit
          </button>
        ) : (
          <div style={{ display: 'flex', gap: '4px' }}>
            <button
              onClick={onCancel}
              style={{
                padding: '6px 12px', background: 'transparent', color: t.textSecondary,
                border: 'none', borderRadius: '7px',
                fontSize: '12px', fontWeight: 500,
                cursor: 'pointer', fontFamily: fontStack
              }}
            >
              Cancel
            </button>
            <button
              onClick={onSave}
              style={{
                padding: '6px 14px', background: t.accent, color: t.textOnColor,
                border: 'none', borderRadius: '7px',
                fontSize: '12px', fontWeight: 600,
                cursor: 'pointer', fontFamily: fontStack
              }}
            >
              Save
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

