function QuarterEditField({ pct, mode, annualTotal, onPctChange }) {
  const [draftStr, setDraftStr] = useState(
    mode === 'percentage' ? String(pct) : String(Math.round((pct / 100) * annualTotal))
  );
  
  // Resync draftStr if mode changes externally
  useEffect(() => {
    setDraftStr(mode === 'percentage' ? String(pct) : String(Math.round((pct / 100) * annualTotal)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode]);
  
  const commit = (val) => {
    const num = Number(val);
    if (isNaN(num)) return;
    if (mode === 'percentage') {
      onPctChange(Math.max(0, Math.min(100, Math.round(num * 10) / 10)));
    } else {
      const newPct = annualTotal > 0 ? (num / annualTotal) * 100 : 0;
      onPctChange(Math.max(0, Math.min(100, Math.round(newPct * 10) / 10)));
    }
  };
  
  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '4px', marginBottom: '6px' }}>
        {mode === 'flat' && <span style={{ fontSize: '14px', color: t.textTertiary }}>$</span>}
        <input
          type="number"
          value={draftStr}
          step={mode === 'percentage' ? '0.5' : '1000'}
          onChange={(e) => {
            setDraftStr(e.target.value);
            commit(e.target.value);
          }}
          style={{
            fontSize: '15px', fontWeight: 600, color: t.textPrimary,
            fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
            border: '1px solid ' + t.accent,
            background: t.bgPrimary,
            padding: '4px 8px',
            borderRadius: '6px',
            width: '100%',
            outline: 'none',
            boxSizing: 'border-box'
          }}
        />
        {mode === 'percentage' && <span style={{ fontSize: '12px', color: t.textTertiary, marginLeft: '4px' }}>%</span>}
      </div>
      <div style={{
        fontSize: '10px', color: t.textTertiary,
        fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
      }}>
        {mode === 'percentage'
          ? formatMoneyShort(Math.round((pct / 100) * annualTotal))
          : pct.toFixed(1) + '%'
        }
      </div>
    </div>
  );
}

