// ============= STRATEGY / OBJECTIVES =============
const UNIVERSAL_OBJECTIVES = [
  { id: 'sales_volume', name: 'Sales volume', desc: 'Move more units' },
  { id: 'sales_gross', name: 'Sales gross profit', desc: 'Margin per unit' },
  { id: 'service_retention', name: 'Service retention', desc: 'Keep customers in our service bay' },
  { id: 'service_revenue', name: 'Service revenue (CP)', desc: 'Customer-pay service work' },
  { id: 'inventory_velocity', name: 'Inventory velocity', desc: 'Turn aged inventory faster' },
  { id: 'conquest', name: 'Conquest growth', desc: 'Steal share from competitors' },
  { id: 'retention', name: 'Customer retention', desc: 'Keep customers through trade cycle' },
  { id: 'brand', name: 'Brand and reputation', desc: 'Awareness, NPS, reviews' },
  { id: 'fi', name: 'F&I performance', desc: 'PVR, product penetration' },
  { id: 'coop', name: 'Co-op capture', desc: 'Maximize OEM funds' }
];

// AI-proposed initial bucket assignment
const AI_PROPOSED_BUCKETS = {
  service_retention: 'lean_in',
  service_revenue: 'lean_in',
  conquest: 'lean_in',
  sales_volume: 'sustain',
  sales_gross: 'sustain',
  inventory_velocity: 'sustain',
  retention: 'background',
  coop: 'background',
  fi: 'background',
  brand: 'pause'
};

const BUCKETS = [
  { id: 'lean_in', label: 'Lean in', desc: 'Most of my energy', cap: 3, color: 'accentDeep' },
  { id: 'sustain', label: 'Sustain', desc: 'Keep the engine on', cap: 3, color: 'accent' },
  { id: 'background', label: 'Background', desc: 'Light touch only', cap: null, color: 'textSecondary' },
  { id: 'pause', label: 'Pause', desc: 'Skip this quarter', cap: null, color: 'textTertiary' }
];

function StrategyObjectives({ onDiscuss, isTablet, isSmall }) {
  const [stance, setStance] = useState(
    'Tachyon Motors is a Toyota store in Austin, TX, focused on service-led growth and conquest in the southwest suburbs. We over-index on used trucks and value retaining service customers over chasing new ones. Our biggest competitive opening is the share weakness at Riverside Ford in 78745-78749.'
  );
  const [editingStance, setEditingStance] = useState(false);
  const [stanceDraft, setStanceDraft] = useState(stance);
  
  // AI-detected principles: substrings of the stance text that AI has identified as guiding signals.
  // In the real product these would be regenerated whenever the stance is saved.
  const principles = [
    'service-led growth and conquest',
    'used trucks',
    'retaining service customers over chasing new ones',
    'share weakness at Riverside Ford'
  ];
  
  // Quarter selection: dynamic list with current marker
  const CURRENT_QUARTER = 'Q2 2026'; // matches the prototype's "today" of May 5, 2026
  const QUARTERS = ['Q1 2026', 'Q2 2026', 'Q3 2026', 'Q4 2026'];
  const [quarter, setQuarter] = useState(CURRENT_QUARTER);
  const isPastQuarter = (q) => {
    const order = QUARTERS.indexOf(q);
    const currentOrder = QUARTERS.indexOf(CURRENT_QUARTER);
    return order < currentOrder;
  };
  const isReadOnly = isPastQuarter(quarter);
  
  // Draft vs saved buckets, user can edit freely until they Save
  const [savedBuckets, setSavedBuckets] = useState(AI_PROPOSED_BUCKETS);
  const [buckets, setBuckets] = useState(AI_PROPOSED_BUCKETS);
  
  // Detect if there are unsaved changes
  const hasUnsavedChanges = Object.keys(buckets).some(k => buckets[k] !== savedBuckets[k]);
  
  // Save modal
  const [saveModalOpen, setSaveModalOpen] = useState(false);

  // Counts per bucket
  const bucketCounts = BUCKETS.reduce((acc, b) => {
    acc[b.id] = Object.values(buckets).filter(v => v === b.id).length;
    return acc;
  }, {});

  // Move objective to a bucket
  const moveToBucket = (objId, targetBucket) => {
    if (isReadOnly) return;
    const cap = BUCKETS.find(b => b.id === targetBucket).cap;
    if (cap !== null && bucketCounts[targetBucket] >= cap && buckets[objId] !== targetBucket) {
      return;
    }
    setBuckets({ ...buckets, [objId]: targetBucket });
  };

  const resetToAIProposed = () => setBuckets(AI_PROPOSED_BUCKETS);
  const discardChanges = () => setBuckets(savedBuckets);
  const confirmSave = () => {
    setSavedBuckets(buckets);
    setSaveModalOpen(false);
  };

  return (
    <div>
      {/* VISION AND VALUES - stance with AI-highlighted principles */}
      <section style={{ marginBottom: '40px' }}>
        <div style={{ marginBottom: '12px' }}>
          <h2 style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, margin: 0, letterSpacing: '-0.005em', marginBottom: '6px' }}>
            Vision and values
          </h2>
          <p style={{ fontSize: '12px', color: t.textTertiary, margin: 0, lineHeight: 1.5 }}>
            Tell me who you are. I will draw out the guiding principles I should apply everywhere. Click any underlined phrase to discuss it.
          </p>
        </div>

        {!editingStance ? (
          <div style={{
            position: 'relative',
            background: t.surface,
            borderRadius: '12px',
            padding: '24px 28px'
          }}>
            <button
              onClick={() => { setStanceDraft(stance); setEditingStance(true); }}
              aria-label="Edit"
              style={{
                position: 'absolute',
                top: '14px', right: '14px',
                background: 'transparent', border: 'none',
                color: t.textTertiary, cursor: 'pointer',
                padding: '6px', borderRadius: '6px',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                transition: 'background 0.12s'
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textSecondary; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textTertiary; }}
            >
              <Edit2 size={14} strokeWidth={1.75} />
            </button>
            <div style={{
              fontSize: '15px', color: t.textPrimary, lineHeight: 1.7, fontWeight: 400,
              paddingRight: '36px'
            }}>
              {renderStanceWithPrinciples(stance, principles, onDiscuss)}
            </div>
          </div>
        ) : (
          <div style={{ background: t.surface, borderRadius: '12px', padding: '4px' }}>
            <textarea
              value={stanceDraft}
              onChange={(e) => setStanceDraft(e.target.value)}
              autoFocus
              rows={5}
              style={{
                width: '100%', background: 'transparent', border: 'none',
                padding: '20px 24px', fontSize: '15px', color: t.textPrimary,
                lineHeight: 1.7, fontFamily: fontStack, outline: 'none', resize: 'vertical',
                boxSizing: 'border-box'
              }}
            />
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '6px', padding: '0 16px 14px' }}>
              <button
                onClick={() => setEditingStance(false)}
                style={{
                  padding: '7px 14px', background: 'transparent', color: t.textSecondary,
                  border: 'none', borderRadius: '7px', fontSize: '12px', fontWeight: 500,
                  cursor: 'pointer', fontFamily: fontStack
                }}
              >
                Cancel
              </button>
              <button
                onClick={() => { setStance(stanceDraft); setEditingStance(false); }}
                style={{
                  padding: '7px 14px', background: t.accent, color: t.textOnColor,
                  border: 'none', borderRadius: '7px', fontSize: '12px', fontWeight: 600,
                  cursor: 'pointer', fontFamily: fontStack
                }}
              >
                Save
              </button>
            </div>
          </div>
        )}
      </section>

      {/* QUARTERLY EMPHASIS - BUCKET ASSIGNMENT */}
      <section style={{ marginBottom: '24px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: '6px', flexWrap: 'wrap', gap: '12px' }}>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', flexWrap: 'wrap' }}>
            <h2 style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, margin: 0, letterSpacing: '-0.005em' }}>
              Where I should focus this quarter
            </h2>
            <div style={{ position: 'relative' }}>
              <select
                value={quarter}
                onChange={(e) => {
                  if (hasUnsavedChanges) {
                    if (!window.confirm('You have unsaved changes. Switch quarter and discard them?')) return;
                    setBuckets(savedBuckets);
                  }
                  setQuarter(e.target.value);
                }}
                style={{
                  background: t.surface, border: 'none', color: t.textPrimary,
                  padding: '6px 32px 6px 12px',
                  borderRadius: '7px', fontSize: '12px',
                  fontWeight: 600, cursor: 'pointer', fontFamily: fontStack, outline: 'none',
                  appearance: 'none', WebkitAppearance: 'none',
                  backgroundImage: 'url("data:image/svg+xml;utf8,<svg xmlns=' + String.fromCharCode(39) + 'http://www.w3.org/2000/svg' + String.fromCharCode(39) + ' width=' + String.fromCharCode(39) + '12' + String.fromCharCode(39) + ' height=' + String.fromCharCode(39) + '12' + String.fromCharCode(39) + ' viewBox=' + String.fromCharCode(39) + '0 0 24 24' + String.fromCharCode(39) + ' fill=' + String.fromCharCode(39) + 'none' + String.fromCharCode(39) + ' stroke=' + String.fromCharCode(39) + '%23969AA3' + String.fromCharCode(39) + ' stroke-width=' + String.fromCharCode(39) + '2' + String.fromCharCode(39) + ' stroke-linecap=' + String.fromCharCode(39) + 'round' + String.fromCharCode(39) + ' stroke-linejoin=' + String.fromCharCode(39) + 'round' + String.fromCharCode(39) + '><polyline points=' + String.fromCharCode(39) + '6 9 12 15 18 9' + String.fromCharCode(39) + '/></svg>")',
                  backgroundRepeat: 'no-repeat',
                  backgroundPosition: 'right 10px center'
                }}
              >
                {QUARTERS.map(q => (
                  <option key={q} value={q}>
                    {q}{q === CURRENT_QUARTER ? ' (current)' : ''}
                  </option>
                ))}
              </select>
            </div>
            {isReadOnly && (
              <span style={{
                fontSize: '11px', color: t.textTertiary, fontWeight: 500,
                padding: '3px 8px', background: t.surfaceMuted, borderRadius: '5px'
              }}>
                Snapshot, read-only
              </span>
            )}
          </div>
          
          {/* Save / Discard / Reset actions */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            {!hasUnsavedChanges && !isReadOnly && (
              <button
                onClick={resetToAIProposed}
                style={{
                  padding: '6px 12px', background: 'transparent', color: t.accent,
                  border: 'none', borderRadius: '7px', fontSize: '12px', fontWeight: 600,
                  cursor: 'pointer', fontFamily: fontStack,
                  display: 'flex', alignItems: 'center', gap: '5px'
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = t.accentSoft}
                onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
              >
                <RefreshCw size={11} /> Reset to AI proposal
              </button>
            )}
            {hasUnsavedChanges && (
              <>
                <span style={{ fontSize: '11px', color: t.warning, fontWeight: 600 }}>
                  Unsaved changes
                </span>
                <button
                  onClick={discardChanges}
                  style={{
                    padding: '7px 14px', background: 'transparent', color: t.textSecondary,
                    border: 'none', borderRadius: '7px', fontSize: '12px', fontWeight: 500,
                    cursor: 'pointer', fontFamily: fontStack
                  }}
                >
                  Discard
                </button>
                <button
                  onClick={() => setSaveModalOpen(true)}
                  style={{
                    padding: '7px 14px', background: t.accent, color: t.textOnColor,
                    border: 'none', borderRadius: '7px', fontSize: '12px', fontWeight: 600,
                    cursor: 'pointer', fontFamily: fontStack
                  }}
                >
                  Save changes
                </button>
              </>
            )}
          </div>
        </div>
        <p style={{ fontSize: '12px', color: t.textTertiary, margin: 0, marginBottom: '24px', lineHeight: 1.5 }}>
          Pick where each goal goes. Lean in is where I put most of my energy. Pause means skip it for now.
        </p>

        {/* COLUMN-HEADER LEGEND: bucket descriptions sit above the segmented control column */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: isSmall ? '1fr' : '240px 1fr',
          gap: '16px',
          marginBottom: '8px',
          alignItems: 'flex-end'
        }}>
          <div /> {/* spacer for the name column */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(4, 1fr)',
            gap: '2px',
            padding: '0 3px'
          }}>
            {BUCKETS.map(b => {
              const count = bucketCounts[b.id];
              const overCap = b.cap !== null && count > b.cap;
              const atCap = b.cap !== null && count === b.cap;
              return (
                <div key={b.id} style={{
                  padding: '6px 10px',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '2px'
                }}>
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: '6px' }}>
                    <span style={{ fontSize: '12px', fontWeight: 600, color: t.textPrimary }}>
                      {b.label}
                    </span>
                    <span style={{
                      fontSize: '11px',
                      color: overCap ? t.warning : atCap ? t.success : t.textTertiary,
                      fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
                      fontWeight: 500
                    }}>
                      {count}{b.cap !== null ? '/' + b.cap : ''}
                    </span>
                  </div>
                  <div style={{ fontSize: '10px', color: t.textTertiary, lineHeight: 1.4 }}>
                    {b.desc}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Objective rows with segmented controls aligned to the columns above */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          {UNIVERSAL_OBJECTIVES.map(obj => {
            const currentBucket = buckets[obj.id];
            return (
              <Discussable
                key={obj.id}
                label={obj.name}
                prefilledQuestion={`Why is ${obj.name} where it is, and what would change if I moved it?`}
                onDiscuss={onDiscuss}
                style={{ borderRadius: '10px' }}
              >
                <div style={{
                  padding: '14px 18px', background: t.surface, borderRadius: '10px',
                  display: 'grid',
                  gridTemplateColumns: isSmall ? '1fr' : '240px 1fr',
                  gap: '16px', alignItems: 'center'
                }}>
                  <div>
                    <div style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary }}>
                      {obj.name}
                    </div>
                    <div style={{ fontSize: '12px', color: t.textTertiary, marginTop: '2px' }}>
                      {obj.desc}
                    </div>
                  </div>
                  
                  {/* Uniform segmented control - one button per bucket column */}
                  <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(4, 1fr)',
                    background: t.surfaceMuted,
                    borderRadius: '8px',
                    padding: '3px',
                    gap: '2px'
                  }}>
                    {BUCKETS.map(b => {
                      const isCurrent = currentBucket === b.id;
                      const atCap = b.cap !== null && bucketCounts[b.id] >= b.cap && !isCurrent;
                      const disabled = atCap || isReadOnly;
                      
                      return (
                        <button
                          key={b.id}
                          onClick={() => moveToBucket(obj.id, b.id)}
                          disabled={disabled}
                          style={{
                            padding: '6px 8px',
                            background: isCurrent ? t.bgPrimary : 'transparent',
                            color: isCurrent ? t.textPrimary : disabled ? t.textDisabled : t.textSecondary,
                            border: 'none',
                            borderRadius: '6px',
                            fontSize: '11px',
                            fontWeight: isCurrent ? 600 : 500,
                            cursor: disabled ? 'not-allowed' : 'pointer',
                            fontFamily: fontStack,
                            transition: 'all 0.12s',
                            boxShadow: isCurrent ? '0 1px 2px rgba(22,22,22,0.06)' : 'none',
                            whiteSpace: 'nowrap'
                          }}
                          onMouseEnter={(e) => { if (!isCurrent && !disabled) e.currentTarget.style.background = 'rgba(22,22,22,0.03)'; }}
                          onMouseLeave={(e) => { if (!isCurrent) e.currentTarget.style.background = 'transparent'; }}
                        >
                          {b.label}
                        </button>
                      );
                    })}
                  </div>
                </div>
              </Discussable>
            );
          })}
        </div>
      </section>

      {/* SAVE CONFIRMATION MODAL */}
      {saveModalOpen && (
        <SaveEmphasisModal
          quarter={quarter}
          buckets={buckets}
          savedBuckets={savedBuckets}
          onConfirm={confirmSave}
          onCancel={() => setSaveModalOpen(false)}
        />
      )}    </div>
  );
}

// ============= SAVE EMPHASIS MODAL =============
function SaveEmphasisModal({ quarter, buckets, savedBuckets, onConfirm, onCancel }) {
  // Compute the diffs to show what changed
  const changes = Object.keys(buckets)
    .filter(k => buckets[k] !== savedBuckets[k])
    .map(k => {
      const obj = UNIVERSAL_OBJECTIVES.find(o => o.id === k);
      const fromBucket = BUCKETS.find(b => b.id === savedBuckets[k]);
      const toBucket = BUCKETS.find(b => b.id === buckets[k]);
      return { name: obj.name, from: fromBucket.label, to: toBucket.label };
    });

  return (
    <>
      <div
        onClick={onCancel}
        style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(22,22,22,0.4)', backdropFilter: 'blur(4px)',
          zIndex: 300,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          padding: '24px'
        }}
      >
        <div
          onClick={(e) => e.stopPropagation()}
          style={{
            background: t.bgPrimary,
            borderRadius: '16px',
            padding: '28px 32px',
            maxWidth: '520px',
            width: '100%',
            boxShadow: '0 20px 60px rgba(22,22,22,0.2)'
          }}
        >
          <h2 style={{
            fontSize: '20px', fontWeight: 600, margin: 0, marginBottom: '8px',
            color: t.textPrimary, letterSpacing: '-0.015em'
          }}>
            Save {quarter} focus?
          </h2>
          <p style={{
            fontSize: '14px', color: t.textSecondary, lineHeight: 1.6,
            margin: 0, marginBottom: '20px'
          }}>
            With this change, I will reprioritize <strong style={{ color: t.textPrimary }}>7 scheduled campaigns</strong> and update the {quarter} <strong style={{ color: t.textPrimary }}>Plan</strong> to match this new emphasis. Active campaigns will continue, but pacing and budget allocation will shift accordingly.
          </p>

          {/* Diff preview */}
          {changes.length > 0 && (
            <div style={{
              background: t.surface, borderRadius: '10px',
              padding: '12px 16px', marginBottom: '20px'
            }}>
              <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 600, marginBottom: '8px' }}>
                {changes.length} change{changes.length === 1 ? '' : 's'}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                {changes.map((c, i) => (
                  <div key={i} style={{
                    display: 'flex', alignItems: 'center', gap: '10px',
                    fontSize: '13px'
                  }}>
                    <span style={{ color: t.textPrimary, fontWeight: 500, flex: 1 }}>{c.name}</span>
                    <span style={{ color: t.textTertiary }}>{c.from}</span>
                    <ArrowRight size={12} color={t.textTertiary} />
                    <span style={{ color: t.textPrimary, fontWeight: 600 }}>{c.to}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px' }}>
            <button
              onClick={onCancel}
              style={{
                padding: '10px 18px', background: 'transparent', color: t.textSecondary,
                border: 'none', borderRadius: '8px', fontSize: '13px', fontWeight: 500,
                cursor: 'pointer', fontFamily: fontStack
              }}
            >
              Keep editing
            </button>
            <button
              onClick={onConfirm}
              style={{
                padding: '10px 18px', background: t.accent, color: t.textOnColor,
                border: 'none', borderRadius: '8px', fontSize: '13px', fontWeight: 600,
                cursor: 'pointer', fontFamily: fontStack
              }}
            >
              Save and update Plan
            </button>
          </div>
        </div>
      </div>
    </>
  );
}

// ============= STRATEGY / PLAN =============
function StrategyPlan({ isTablet, isSmall, onDiscuss }) {
  const [view, setView] = useState('schedule'); // schedule | month | quarter
  const [layers, setLayers] = useState({
    campaigns: true,
    oem: true,
    coop: true,
    seasonal: true
  });
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [popupAnchor, setPopupAnchor] = useState(null); // {x, y}
  
  // Month view navigation
  const [monthCursor, setMonthCursor] = useState('2026-05'); // current month being viewed
  const [quarterCursor, setQuarterCursor] = useState('Q2'); // Q1 / Q2 / Q3 / Q4

  const toggleLayer = (key) => setLayers({ ...layers, [key]: !layers[key] });

  const layerDefs = [
    { key: 'campaigns', label: 'Campaigns', color: '#4285F4' },
    { key: 'oem', label: 'OEM events', color: '#01BFA5' },
    { key: 'coop', label: 'Co-op Fund', color: '#7B61FF' },
    { key: 'seasonal', label: 'Seasonal markers', color: '#B8721B' }
  ];

  const handleEventClick = (event, e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setPopupAnchor({ 
      x: rect.right + 12, 
      y: rect.top,
      cardWidth: rect.width
    });
    setSelectedEvent(event);
  };

  const closePopup = () => {
    setSelectedEvent(null);
    setPopupAnchor(null);
  };

  // Range label per view
  let rangeLabel = '';
  if (view === 'schedule') rangeLabel = '2026';
  else if (view === 'month') {
    const monthNames = { '2026-01': 'January', '2026-02': 'February', '2026-03': 'March', '2026-04': 'April', '2026-05': 'May', '2026-06': 'June', '2026-07': 'July', '2026-08': 'August', '2026-09': 'September', '2026-10': 'October', '2026-11': 'November', '2026-12': 'December' };
    rangeLabel = monthNames[monthCursor] + ' 2026';
  } else if (view === 'quarter') {
    rangeLabel = quarterCursor + ' 2026';
  }

  const goToToday = () => {
    if (view === 'month') setMonthCursor('2026-05');
    else if (view === 'quarter') setQuarterCursor('Q2');
    else if (view === 'schedule') {
      // scroll to today line
      setTimeout(() => {
        const el = document.getElementById('schedule-today-anchor');
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 50);
    }
  };

  const navPrev = () => {
    if (view === 'month') {
      const months = ['2026-01', '2026-02', '2026-03', '2026-04', '2026-05', '2026-06', '2026-07', '2026-08', '2026-09', '2026-10', '2026-11', '2026-12'];
      const idx = months.indexOf(monthCursor);
      if (idx > 0) setMonthCursor(months[idx - 1]);
    } else if (view === 'quarter') {
      const qs = ['Q1', 'Q2', 'Q3', 'Q4'];
      const idx = qs.indexOf(quarterCursor);
      if (idx > 0) setQuarterCursor(qs[idx - 1]);
    }
  };

  const navNext = () => {
    if (view === 'month') {
      const months = ['2026-01', '2026-02', '2026-03', '2026-04', '2026-05', '2026-06', '2026-07', '2026-08', '2026-09', '2026-10', '2026-11', '2026-12'];
      const idx = months.indexOf(monthCursor);
      if (idx < months.length - 1) setMonthCursor(months[idx + 1]);
    } else if (view === 'quarter') {
      const qs = ['Q1', 'Q2', 'Q3', 'Q4'];
      const idx = qs.indexOf(quarterCursor);
      if (idx < qs.length - 1) setQuarterCursor(qs[idx + 1]);
    }
  };

  return (
    <div style={{ position: 'relative' }}>
      {/* Plan header: Today + nav + range label, view toggle on right */}
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        marginBottom: '20px', flexWrap: 'wrap', gap: '12px'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <button
            onClick={goToToday}
            style={{
              padding: '7px 14px', background: t.surface, color: t.textPrimary,
              border: 'none', borderRadius: '8px', fontSize: '12px', fontWeight: 600,
              cursor: 'pointer', fontFamily: fontStack
            }}
          >
            Today
          </button>
          {view !== 'schedule' && (
            <>
              <button
                onClick={navPrev}
                style={{
                  width: '32px', height: '32px',
                  background: 'transparent', color: t.textSecondary,
                  border: 'none', borderRadius: '7px', cursor: 'pointer',
                  display: 'flex', alignItems: 'center', justifyContent: 'center'
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = t.surface}
                onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
              >
                <ChevronLeft size={16} />
              </button>
              <button
                onClick={navNext}
                style={{
                  width: '32px', height: '32px',
                  background: 'transparent', color: t.textSecondary,
                  border: 'none', borderRadius: '7px', cursor: 'pointer',
                  display: 'flex', alignItems: 'center', justifyContent: 'center'
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = t.surface}
                onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
              >
                <ChevronRight size={16} />
              </button>
            </>
          )}
          <span style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, marginLeft: '4px', letterSpacing: '-0.005em' }}>
            {rangeLabel}
          </span>
        </div>

        <div style={{
          display: 'flex',
          background: t.surface,
          borderRadius: '8px',
          padding: '3px',
          gap: '2px'
        }}>
          {[
            { id: 'schedule', label: 'Schedule' },
            { id: 'month', label: 'Month' },
            { id: 'quarter', label: 'Quarter' }
          ].map(v => {
            const isActive = view === v.id;
            return (
              <button
                key={v.id}
                onClick={() => setView(v.id)}
                style={{
                  padding: '6px 14px',
                  background: isActive ? t.bgPrimary : 'transparent',
                  color: isActive ? t.textPrimary : t.textSecondary,
                  border: 'none',
                  borderRadius: '6px',
                  fontSize: '12px',
                  fontWeight: isActive ? 600 : 500,
                  cursor: 'pointer',
                  fontFamily: fontStack,
                  boxShadow: isActive ? '0 1px 2px rgba(22,22,22,0.06)' : 'none'
                }}
              >
                {v.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Body: content + floating layers panel on right */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: isTablet ? '1fr' : '1fr 168px',
        gap: '24px',
        alignItems: 'flex-start'
      }}>
        {/* Plan content */}
        <div style={{ minWidth: 0 }}>
          {view === 'schedule' && <PlanScheduleView layers={layers} onDiscuss={onDiscuss} onEventClick={handleEventClick} isSmall={isSmall} />}
          {view === 'month' && <PlanMonthView layers={layers} onDiscuss={onDiscuss} onEventClick={handleEventClick} monthCursor={monthCursor} />}
          {view === 'quarter' && <PlanQuarterView layers={layers} onDiscuss={onDiscuss} onEventClick={handleEventClick} quarterCursor={quarterCursor} />}
        </div>

        {/* Floating layer toggles, right side, no card chrome */}
        {!isTablet && (
          <div style={{
            position: 'sticky',
            top: '24px',
            display: 'flex',
            flexDirection: 'column',
            gap: '2px',
            padding: '4px'
          }}>
            {layerDefs.map(l => (
              <LayerToggle
                key={l.key}
                label={l.label}
                color={l.color}
                checked={layers[l.key]}
                onChange={() => toggleLayer(l.key)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Event popup */}
      {selectedEvent && popupAnchor && (
        <EventPopup
          event={selectedEvent}
          anchor={popupAnchor}
          onClose={closePopup}
          onDiscuss={onDiscuss}
        />
      )}
    </div>
  );
}

// ============= LAYER TOGGLE =============
function LayerToggle({ label, color, checked, onChange }) {
  return (
    <label style={{
      display: 'flex', alignItems: 'center', gap: '10px',
      padding: '8px 10px',
      borderRadius: '7px',
      cursor: 'pointer',
      transition: 'background 0.12s'
    }}
    onMouseEnter={(e) => e.currentTarget.style.background = t.surface}
    onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
    >
      <div
        onClick={(e) => { e.preventDefault(); onChange(); }}
        style={{
          width: '16px', height: '16px',
          borderRadius: '4px',
          border: checked ? 'none' : '1.5px solid ' + t.textTertiary,
          background: checked ? color : 'transparent',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          flexShrink: 0,
          transition: 'all 0.12s'
        }}
      >
        {checked && (
          <svg width="11" height="11" viewBox="0 0 12 12" fill="none">
            <path d="M2.5 6.2 L4.8 8.5 L9.5 3.8" stroke="#FFFFFF" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        )}
      </div>
      <span style={{
        fontSize: '12px',
        color: checked ? t.textPrimary : t.textTertiary,
        fontWeight: 500
      }}>
        {label}
      </span>
    </label>
  );
}

