const LAYER_COLORS = {
  campaigns: '#4285F4',
  oem: '#01BFA5',
  coop: '#7B61FF',
  seasonal: '#B8721B'
};

const LAYER_LABELS = {
  campaigns: 'Campaign',
  oem: 'OEM event',
  coop: 'Co-op',
  seasonal: 'Seasonal'
};

const TODAY_ISO = '2026-05-05';

// Expand multi-day events into per-day instances for schedule view
function expandPlanItems(items) {
  const expanded = [];
  items.forEach(item => {
    if (!item.endDate) {
      expanded.push({ ...item, isMultiDay: false });
      return;
    }
    // Generate one entry per day in the range
    const start = new Date(item.date);
    const end = new Date(item.endDate);
    const dayMs = 24 * 60 * 60 * 1000;
    const totalDays = Math.round((end - start) / dayMs) + 1;
    for (let i = 0; i < totalDays; i++) {
      const d = new Date(start.getTime() + i * dayMs);
      const iso = d.toISOString().slice(0, 10);
      const monthName = d.toLocaleString('en-US', { month: 'short' });
      const dayLabel = monthName + ' ' + d.getDate();
      expanded.push({
        ...item,
        date: iso,
        day: dayLabel,
        isMultiDay: true,
        dayIndex: i + 1,
        totalDays: totalDays
      });
    }
  });
  return expanded;
}

// ============= SCHEDULE VIEW =============
function PlanScheduleView({ layers, onDiscuss, onEventClick, isSmall }) {
  const todayAnchorRef = useRef(null);
  const [showScrollToTop, setShowScrollToTop] = useState(false);
  
  // Watch the today anchor's position. Show the floating "back to today" button
  // when the today row scrolls above the visible viewport.
  // We attach scroll listeners on both window and any scrollable ancestors, since
  // the actual scrolling element varies depending on layout.
  useEffect(() => {
    const el = todayAnchorRef.current;
    if (!el) return;
    
    // Find any scrollable ancestors so we can listen to them
    const scrollableAncestors = [];
    let parent = el.parentElement;
    while (parent && parent !== document.body) {
      const style = window.getComputedStyle(parent);
      const overflowY = style.overflowY;
      if (overflowY === 'auto' || overflowY === 'scroll') {
        scrollableAncestors.push(parent);
      }
      parent = parent.parentElement;
    }
    
    const checkPosition = () => {
      if (!todayAnchorRef.current) return;
      const rect = todayAnchorRef.current.getBoundingClientRect();
      // Show the button when today is above the visible viewport.
      // Using -8 as threshold to give a tiny buffer before the button appears.
      setShowScrollToTop(rect.top < -8);
    };
    
    // Run an initial check (in case the user is already scrolled past today on mount)
    checkPosition();
    
    // Listen to window scroll (primary case)
    window.addEventListener('scroll', checkPosition, { passive: true });
    
    // Also listen to any scrollable ancestor (for inner-scroll layouts)
    scrollableAncestors.forEach(node => {
      node.addEventListener('scroll', checkPosition, { passive: true });
    });
    
    // Re-check on window resize too
    window.addEventListener('resize', checkPosition, { passive: true });
    
    return () => {
      window.removeEventListener('scroll', checkPosition);
      window.removeEventListener('resize', checkPosition);
      scrollableAncestors.forEach(node => {
        node.removeEventListener('scroll', checkPosition);
      });
    };
  }, []);
  
  const scrollToToday = () => {
    if (todayAnchorRef.current) {
      todayAnchorRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };
  
  const visible = expandPlanItems(PLAN_ITEMS).filter(item => layers[item.layer]);
  
  // Group by date
  const byDate = {};
  visible.forEach(item => {
    if (!byDate[item.date]) byDate[item.date] = [];
    byDate[item.date].push(item);
  });
  
  // Always include today even if empty
  if (!byDate[TODAY_ISO]) byDate[TODAY_ISO] = [];
  
  // Filter to: 3 most recent past days with events + today + all future days
  const allSorted = Object.keys(byDate).sort();
  const todayIdx = allSorted.indexOf(TODAY_ISO);
  const pastWithEvents = allSorted
    .slice(0, todayIdx)
    .filter(d => byDate[d].length > 0);
  const recentPast = pastWithEvents.slice(-3); // last 3 past days with events
  const futureAndToday = allSorted.slice(todayIdx);
  const sortedDates = [...recentPast, ...futureAndToday];
  
  // Format date for row label
  const formatDateRow = (iso) => {
    const d = new Date(iso + 'T00:00:00');
    const day = d.getDate();
    const dow = d.toLocaleString('en-US', { weekday: 'short' }).toUpperCase();
    const mo = d.toLocaleString('en-US', { month: 'short' }).toUpperCase();
    return { day, dow, mo };
  };

  return (
    <div style={{ position: 'relative' }}>
      {sortedDates.map((iso, idx) => {
        const items = byDate[iso];
        const { day, dow, mo } = formatDateRow(iso);
        const isToday = iso === TODAY_ISO;
        const isPast = iso < TODAY_ISO;
        
        return (
          <React.Fragment key={iso}>
            {isToday && <TodayLine />}
            <div
              ref={isToday ? todayAnchorRef : null}
              id={isToday ? 'schedule-today-anchor' : undefined}
              style={{
                display: 'grid',
                gridTemplateColumns: '88px 1fr',
                gap: '20px',
                padding: '14px 0',
                borderBottom: '1px solid ' + t.surfaceMuted,
                opacity: isPast ? 0.55 : 1,
                transition: 'opacity 0.15s'
              }}
            >
              {/* Date column */}
              <div style={{ display: 'flex', alignItems: 'flex-start', gap: '10px' }}>
                <div style={{
                  width: '32px', height: '32px',
                  borderRadius: '50%',
                  background: isToday ? t.accent : 'transparent',
                  color: isToday ? '#fff' : t.textPrimary,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '15px', fontWeight: isToday ? 600 : 500,
                  flexShrink: 0
                }}>
                  {day}
                </div>
                <div style={{ paddingTop: '4px' }}>
                  <div style={{
                    fontSize: '10px',
                    fontWeight: 600,
                    color: isToday ? t.accent : t.textTertiary,
                    letterSpacing: '0.04em'
                  }}>
                    {mo} {dow}
                  </div>
                </div>
              </div>
              
              {/* Events column */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', minWidth: 0 }}>
                {items.length === 0 ? (
                  <div style={{ fontSize: '13px', color: t.textTertiary, fontStyle: 'italic', paddingTop: '6px' }}>
                    Nothing planned
                  </div>
                ) : (
                  items.map((item, i) => {
                    const color = LAYER_COLORS[item.layer];
                    return (
                      <div
                        key={i}
                        onClick={(e) => onEventClick(item, e)}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '10px',
                          padding: '6px 10px',
                          margin: '-6px -10px',
                          borderRadius: '7px',
                          cursor: 'pointer',
                          transition: 'background 0.12s'
                        }}
                        onMouseEnter={(e) => e.currentTarget.style.background = t.surface}
                        onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
                      >
                        <div style={{
                          width: '8px', height: '8px',
                          borderRadius: '50%',
                          background: color,
                          flexShrink: 0
                        }} />
                        <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, minWidth: '52px' }}>
                          All day
                        </div>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <span style={{ fontSize: '14px', color: t.textPrimary, fontWeight: 500 }}>
                            {item.name}
                          </span>
                          {item.isMultiDay && (
                            <span style={{ fontSize: '12px', color: t.textTertiary, marginLeft: '6px', fontWeight: 500 }}>
                              (Day {item.dayIndex}/{item.totalDays})
                            </span>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          </React.Fragment>
        );
      })}
      
      {/* Floating "back to today" button. Appears when the today row scrolls
          out of view above. Same x-axis as the Ask bar on wider screens;
          stacked above the Ask bar on small viewports. Styled to match the
          Ask bar (height, radius, shadow, icon size) so they read as a pair. */}
      {showScrollToTop && (
        <button
          onClick={scrollToToday}
          aria-label="Back to today"
          style={{
            position: 'fixed',
            bottom: isSmall ? '76px' : '24px',
            right: isSmall ? '16px' : '32px',
            width: '42px',
            height: '42px',
            borderRadius: '14px',
            background: t.bgPrimary,
            border: 'none',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: t.textPrimary,
            boxShadow: '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)',
            zIndex: 65,
            transition: 'transform 0.15s, box-shadow 0.15s',
            animation: 'fadeIn 0.18s ease'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = 'translateY(-2px)';
            e.currentTarget.style.boxShadow = '0 6px 20px rgba(22,22,22,0.08), 0 1px 3px rgba(22,22,22,0.04)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'translateY(0)';
            e.currentTarget.style.boxShadow = '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)';
          }}
        >
          <ChevronUp size={16} strokeWidth={2} />
        </button>
      )}
    </div>
  );
}

// Today line component, drawn between past and present
function TodayLine() {
  return (
    <div style={{
      position: 'relative',
      height: '2px',
      background: t.danger,
      margin: '0 -8px',
      borderRadius: '2px'
    }}>
      <div style={{
        position: 'absolute',
        left: '-4px',
        top: '-4px',
        width: '10px', height: '10px',
        borderRadius: '50%',
        background: t.danger
      }} />
    </div>
  );
}

// ============= MONTH VIEW =============
function PlanMonthView({ layers, onDiscuss, onEventClick, monthCursor }) {
  // Parse the month cursor (e.g. '2026-05')
  const [year, monthStr] = monthCursor.split('-');
  const month = parseInt(monthStr); // 1-12
  
  // Build the grid: always 6 rows of 7 days
  // Find first day of month and its day-of-week
  const firstDay = new Date(parseInt(year), month - 1, 1);
  const firstDow = firstDay.getDay(); // 0 = Sun
  const lastDay = new Date(parseInt(year), month, 0);
  const daysInMonth = lastDay.getDate();
  
  // Days in previous month for leading cells
  const prevMonthLast = new Date(parseInt(year), month - 1, 0).getDate();
  
  // Build 42-cell grid (6 rows × 7 cols)
  const cells = [];
  // Leading days from previous month
  for (let i = firstDow - 1; i >= 0; i--) {
    cells.push({ day: prevMonthLast - i, inMonth: false });
  }
  // Current month days
  for (let d = 1; d <= daysInMonth; d++) {
    cells.push({ day: d, inMonth: true });
  }
  // Trailing days from next month to fill 42
  let trailing = 1;
  while (cells.length < 42) {
    cells.push({ day: trailing++, inMonth: false });
  }
  
  // Items keyed by ISO date for the visible month
  const visible = PLAN_ITEMS.filter(item => layers[item.layer]);
  const itemsByDate = {};
  visible.forEach(item => {
    // For multi-day items, add to each day in range
    if (item.endDate) {
      const start = new Date(item.date);
      const end = new Date(item.endDate);
      const dayMs = 24 * 60 * 60 * 1000;
      for (let d = new Date(start); d <= end; d = new Date(d.getTime() + dayMs)) {
        const iso = d.toISOString().slice(0, 10);
        if (!itemsByDate[iso]) itemsByDate[iso] = [];
        itemsByDate[iso].push(item);
      }
    } else {
      if (!itemsByDate[item.date]) itemsByDate[item.date] = [];
      itemsByDate[item.date].push(item);
    }
  });
  
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  
  // Today
  const TODAY_DAY = 5;
  const TODAY_MONTH = 5;
  const isCurrentMonth = month === TODAY_MONTH;

  return (
    <div style={{
      border: '1px solid ' + t.surfaceMuted,
      borderRadius: '12px',
      overflow: 'hidden'
    }}>
      {/* Day headers */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(7, 1fr)',
        background: t.bgPrimary,
        borderBottom: '1px solid ' + t.surfaceMuted
      }}>
        {days.map(d => (
          <div key={d} style={{
            padding: '10px 12px',
            fontSize: '10px', fontWeight: 600, color: t.textTertiary,
            letterSpacing: '0.04em',
            textAlign: 'left'
          }}>
            {d.toUpperCase()}
          </div>
        ))}
      </div>

      {/* 6 fixed rows of 7 cells, each cell fixed-height */}
      <div style={{ background: t.bgPrimary }}>
        {[0, 1, 2, 3, 4, 5].map(rowIdx => (
          <div key={rowIdx} style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            borderTop: rowIdx > 0 ? '1px solid ' + t.surfaceMuted : 'none',
            height: '116px'
          }}>
            {cells.slice(rowIdx * 7, (rowIdx + 1) * 7).map((cell, di) => {
              const isToday = cell.inMonth && cell.day === TODAY_DAY && isCurrentMonth;
              const cellDateIso = cell.inMonth 
                ? year + '-' + String(month).padStart(2, '0') + '-' + String(cell.day).padStart(2, '0')
                : null;
              const dayItems = cell.inMonth && cellDateIso ? (itemsByDate[cellDateIso] || []) : [];
              
              return (
                <div key={di} style={{
                  padding: '6px 7px',
                  borderRight: di < 6 ? '1px solid ' + t.surfaceMuted : 'none',
                  background: isToday ? t.accentSoft : 'transparent',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '3px',
                  opacity: cell.inMonth ? 1 : 0.4,
                  minHeight: 0,
                  overflow: 'hidden'
                }}>
                  {/* Day number, with circular accent if today */}
                  <div style={{ display: 'flex', justifyContent: 'flex-start', marginBottom: '2px' }}>
                    {isToday ? (
                      <div style={{
                        width: '22px', height: '22px',
                        borderRadius: '50%',
                        background: t.accent,
                        color: '#fff',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: '11px', fontWeight: 600
                      }}>
                        {cell.day}
                      </div>
                    ) : (
                      <div style={{
                        width: '22px', height: '22px',
                        display: 'flex', alignItems: 'center', justifyContent: 'flex-start',
                        fontSize: '11px',
                        fontWeight: 500,
                        color: cell.inMonth ? t.textSecondary : t.textTertiary,
                        paddingLeft: '2px'
                      }}>
                        {cell.day}
                      </div>
                    )}
                  </div>
                  
                  {/* Events: max 3, +N more if overflow */}
                  {dayItems.slice(0, 3).map((item, idx) => {
                    const color = LAYER_COLORS[item.layer];
                    return (
                      <div
                        key={idx}
                        onClick={(e) => { e.stopPropagation(); onEventClick(item, e); }}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '5px',
                          padding: '2px 4px',
                          borderRadius: '4px',
                          cursor: 'pointer',
                          transition: 'background 0.12s',
                          minWidth: 0
                        }}
                        onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
                        onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
                        title={item.name}
                      >
                        <div style={{
                          width: '6px', height: '6px',
                          borderRadius: '50%',
                          background: color,
                          flexShrink: 0
                        }} />
                        <span style={{
                          fontSize: '10px',
                          color: t.textPrimary,
                          fontWeight: 500,
                          whiteSpace: 'nowrap',
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          minWidth: 0,
                          flex: 1
                        }}>
                          {item.name}
                        </span>
                      </div>
                    );
                  })}
                  {dayItems.length > 3 && (
                    <div style={{
                      fontSize: '10px', color: t.textTertiary, fontWeight: 500,
                      padding: '0 4px'
                    }}>
                      +{dayItems.length - 3} more
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

// ============= QUARTER VIEW =============
function PlanQuarterView({ layers, onDiscuss, onEventClick, quarterCursor }) {
  // Build months for the quarter
  const QUARTER_MONTHS = {
    Q1: [{ key: '2026-01', name: 'January' }, { key: '2026-02', name: 'February' }, { key: '2026-03', name: 'March' }],
    Q2: [{ key: '2026-04', name: 'April' }, { key: '2026-05', name: 'May' }, { key: '2026-06', name: 'June' }],
    Q3: [{ key: '2026-07', name: 'July' }, { key: '2026-08', name: 'August' }, { key: '2026-09', name: 'September' }],
    Q4: [{ key: '2026-10', name: 'October' }, { key: '2026-11', name: 'November' }, { key: '2026-12', name: 'December' }]
  };
  const months = QUARTER_MONTHS[quarterCursor];
  
  const visible = PLAN_ITEMS.filter(item => layers[item.layer]);
  const grouped = {};
  months.forEach(m => { grouped[m.key] = []; });
  visible.forEach(item => {
    const m = item.date.slice(0, 7);
    if (grouped[m]) grouped[m].push(item);
  });
  
  const TODAY_MONTH = '2026-05';

  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: '1fr 1fr 1fr',
      gap: '8px'
    }}>
      {months.map(m => {
        const items = grouped[m.key];
        const isCurrentMonth = m.key === TODAY_MONTH;
        return (
          <div key={m.key} style={{
            background: t.surface,
            borderRadius: '12px',
            padding: '14px',
            minHeight: '420px'
          }}>
            <div style={{
              display: 'flex', alignItems: 'baseline', justifyContent: 'space-between',
              marginBottom: '12px',
              paddingBottom: '8px',
              borderBottom: isCurrentMonth ? '1px solid ' + t.accent : '1px solid transparent'
            }}>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
                <span style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, letterSpacing: '-0.01em' }}>
                  {m.name}
                </span>
              </div>
              <span style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500 }}>
                {items.length}
              </span>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {items.map((item, i) => {
                const color = LAYER_COLORS[item.layer];
                return (
                  <div
                    key={i}
                    onClick={(e) => onEventClick(item, e)}
                    style={{
                      padding: '8px 10px',
                      background: t.bgPrimary,
                      borderRadius: '7px',
                      cursor: 'pointer',
                      transition: 'background 0.12s'
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
                    onMouseLeave={(e) => e.currentTarget.style.background = t.bgPrimary}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
                      <div style={{
                        width: '6px', height: '6px', borderRadius: '50%',
                        background: color, flexShrink: 0
                      }} />
                      <span style={{ fontSize: '10px', fontWeight: 600, color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
                        {item.day}
                      </span>
                    </div>
                    <div style={{ fontSize: '12px', fontWeight: 600, color: t.textPrimary, lineHeight: 1.35 }}>
                      {item.name}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ============= EVENT POPUP =============
function EventPopup({ event, anchor, onClose, onDiscuss }) {
  const popupRef = useRef(null);
  
  // Click outside to close
  useEffect(() => {
    const onDocClick = (e) => {
      if (popupRef.current && !popupRef.current.contains(e.target)) {
        onClose();
      }
    };
    setTimeout(() => document.addEventListener('mousedown', onDocClick), 0);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [onClose]);

  const color = LAYER_COLORS[event.layer];
  const layerLabel = LAYER_LABELS[event.layer];
  
  // Format date display
  const formatFullDate = (iso) => {
    const d = new Date(iso + 'T00:00:00');
    return d.toLocaleString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
  };
  
  let dateText = formatFullDate(event.date);
  if (event.endDate) {
    const endD = new Date(event.endDate + 'T00:00:00');
    const endText = endD.toLocaleString('en-US', { month: 'long', day: 'numeric' });
    dateText = formatFullDate(event.date) + ', All day';
    var rangeText = formatFullDate(event.date).replace(/^[A-Za-z]+, /, '') + ' to ' + endText;
  }
  
  // Source metadata
  let sourceLabel = '';
  let sourceIcon = null;
  if (event.source === 'ai') {
    sourceLabel = 'AI-scheduled · last updated 2 days ago';
    sourceIcon = <img src={TEKION_AI_LOGO} alt="" style={{ width: '14px', height: '14px' }} />;
  } else if (event.source === 'oem') {
    sourceLabel = 'From Toyota OEM · synced May 1';
    sourceIcon = <Building2 size={13} color={t.textSecondary} strokeWidth={1.75} />;
  } else if (event.source === 'system') {
    sourceLabel = 'Standard calendar marker';
    sourceIcon = <Calendar size={13} color={t.textSecondary} strokeWidth={1.75} />;
  } else {
    sourceLabel = 'Scheduled by you';
    sourceIcon = <Edit2 size={13} color={t.textSecondary} strokeWidth={1.75} />;
  }
  
  // Position the popup, ensuring it stays in viewport
  const POPUP_WIDTH = 360;
  const POPUP_HEIGHT_EST = 280;
  let left = anchor.x;
  let top = anchor.y;
  
  if (typeof window !== 'undefined') {
    if (left + POPUP_WIDTH > window.innerWidth - 16) {
      left = window.innerWidth - POPUP_WIDTH - 16;
    }
    if (top + POPUP_HEIGHT_EST > window.innerHeight - 16) {
      top = window.innerHeight - POPUP_HEIGHT_EST - 16;
    }
    if (top < 16) top = 16;
    if (left < 16) left = 16;
  }

  return (
    <div
      ref={popupRef}
      style={{
        position: 'fixed',
        left: left + 'px',
        top: top + 'px',
        width: POPUP_WIDTH + 'px',
        background: t.bgPrimary,
        borderRadius: '14px',
        boxShadow: '0 4px 16px rgba(22,22,22,0.08), 0 16px 48px rgba(22,22,22,0.12)',
        zIndex: 250,
        overflow: 'hidden'
      }}
    >
      {/* Top action bar */}
      <div style={{
        display: 'flex', justifyContent: 'flex-end', gap: '4px',
        padding: '10px 12px 0'
      }}>
        <button
          aria-label="Edit"
          style={{
            width: '28px', height: '28px',
            background: 'transparent', border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: t.textSecondary, borderRadius: '6px',
            transition: 'background 0.12s'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <Edit2 size={14} strokeWidth={1.75} />
        </button>
        <button
          onClick={() => {
            onDiscuss({
              label: event.name,
              prefilledQuestion: 'Tell me about ' + event.name + '. Why is it scheduled here, what is the projected impact, and should we move it?'
            });
            onClose();
          }}
          aria-label="Discuss"
          style={{
            width: '28px', height: '28px',
            background: 'transparent', border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: t.textSecondary, borderRadius: '6px',
            transition: 'background 0.12s'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <MessageSquare size={14} strokeWidth={1.75} />
        </button>
        <button
          aria-label="More"
          style={{
            width: '28px', height: '28px',
            background: 'transparent', border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: t.textSecondary, borderRadius: '6px',
            transition: 'background 0.12s'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <MoreHorizontal size={14} strokeWidth={1.75} />
        </button>
        <button
          onClick={onClose}
          aria-label="Close"
          style={{
            width: '28px', height: '28px',
            background: 'transparent', border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: t.textSecondary, borderRadius: '6px',
            transition: 'background 0.12s'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <X size={15} strokeWidth={1.75} />
        </button>
      </div>

      {/* Title and date */}
      <div style={{ padding: '4px 22px 18px' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: '10px', marginBottom: '8px' }}>
          <div style={{
            width: '14px', height: '14px',
            borderRadius: '4px',
            background: color,
            flexShrink: 0,
            marginTop: '5px'
          }} />
          <h2 style={{
            fontSize: '20px', fontWeight: 600, margin: 0,
            color: t.textPrimary, letterSpacing: '-0.015em', lineHeight: 1.3
          }}>
            {event.name}
          </h2>
        </div>
        <div style={{ fontSize: '13px', color: t.textSecondary, paddingLeft: '24px', lineHeight: 1.5 }}>
          {event.endDate ? (
            <>
              {formatFullDate(event.date)}
              <br />
              <span style={{ color: t.textTertiary }}>through {formatFullDate(event.endDate)}</span>
            </>
          ) : (
            formatFullDate(event.date) + ' · All day'
          )}
        </div>
      </div>

      {/* Description */}
      {event.detail && (
        <div style={{
          padding: '12px 22px',
          borderTop: '1px solid ' + t.surfaceMuted,
          fontSize: '13px',
          color: t.textPrimary,
          lineHeight: 1.6
        }}>
          {event.detail}
        </div>
      )}

      {/* Layer pill */}
      <div style={{
        padding: '12px 22px',
        borderTop: '1px solid ' + t.surfaceMuted,
        display: 'flex',
        alignItems: 'center',
        gap: '10px'
      }}>
        <div style={{
          width: '10px', height: '10px',
          borderRadius: '50%',
          background: color,
          flexShrink: 0
        }} />
        <span style={{ fontSize: '12px', color: t.textSecondary, fontWeight: 500 }}>
          {layerLabel}
        </span>
      </div>

      {/* Source */}
      <div style={{
        padding: '12px 22px 18px',
        borderTop: '1px solid ' + t.surfaceMuted,
        display: 'flex',
        alignItems: 'center',
        gap: '10px'
      }}>
        {sourceIcon}
        <span style={{ fontSize: '12px', color: t.textSecondary, fontWeight: 500 }}>
          {sourceLabel}
        </span>
      </div>
    </div>
  );
}

// ============= STRATEGY / BUDGET =============
//
// Architecture:
//   - Read view: budget displayed as static information. Edit affordance is an icon
//     next to the total that opens the BudgetPlaygroundSheet.
//   - Playground sheet: ~720px right-side overlay. Hierarchical accordion for FY total,
//     quarterly distribution, channel allocation, within-channel breakdowns.
//     Running balances at every level. Save only enabled when all levels balance.
//   - AI suggestions: same grey surface, no nested colored panels. Approve commits
//     immediately with an Undo toast. No draft state on the read view.
//   - Pacing pulse: plain prose with clickable bold spans (parseClickableProse pattern
//     from Home overview), opens the discuss panel.

