// Curated AIWidget content for approval items. Maps an approval's id to
// the description AI streams in when the user clicks Discuss on that card,
// plus the three suggested prompts. Realistic, item-specific copy for the
// three test scenarios (a_acq, a_serv, a_ret); other items fall through to
// the widget's generic fallback.
//
// displayLabel is the short noun used in the popover header ("Discuss
// campaign" not "Discuss Approve a new push to move 32 aging Camry XLE
// units"). Each entity type maps to its own short label.
function getApprovalDiscussContent(item) {
  if (!item) return {};
  if (item.id === 'a_acq') {
    return {
      displayLabel: 'campaign',
      description: '32 Camry XLE units have crossed 60 days on lot, with carrying cost climbing $2,400 a week. I pulled 848 reachable Camry intenders from your CRM, modeled the trim ladder against your gross targets, and proposed a $30K push that should clear 18 to 22 units before the curve gets worse. The plan leans Meta and Google because your last three Camry pushes attributed best there.',
      suggestedChips: [
        'Why these 32 units and not more',
        'Walk me through the budget',
        'What happens if I do nothing'
      ]
    };
  }
  if (item.id === 'a_serv') {
    return {
      displayLabel: 'campaign',
      description: '1,840 service customers are due for A/C inspection in the next 60 days, and your service desk runs a $79 inspection every May with strong attach. I built the plan around that offer with email and SMS leading, since your service customers respond 3x better than acquisition leads on those channels. After 76 suppressions for active service appointments, 1,764 are reachable. Budget is $8K, projected at roughly 240 inspections.',
      suggestedChips: [
        'Why $8K and not more',
        'Show me the email and SMS split',
        'What about the 76 we suppressed'
      ]
    };
  }
  if (item.id === 'a_ret') {
    return {
      displayLabel: 'campaign',
      description: '183 in-market shoppers haven\'t been contacted in 14 or more days. Historical conversion drops about 30 percent each week past last contact, so this is a closing window. The creatives are drafted: a 3-touch sequence leading with a $1,000 trade-in bonus, paced over 5 days, with the BDC handoff cued for anyone who clicks. Projected 4 to 6 sales at $4,200 budget.',
      suggestedChips: [
        'Why a trade-in bonus and not financing',
        'Walk me through the 3-touch sequence',
        'What gross do you expect per sale'
      ]
    };
  }
  // Other approval types: short displayLabel based on type, no curated body
  const typeLabels = {
    'campaign-new': 'campaign',
    'campaign-edit': 'campaign',
    'campaign-creative': 'campaign',
    'campaign-insight': 'campaign',
    'journey-new': 'journey',
    'journey-health': 'journey',
    'journey-paused': 'journey',
    'plan-revise': 'plan',
    'budget-revise': 'budget',
    'objectives-revise': 'objectives',
    'components-revise': 'components',
    'reputation': 'review',
    'compliance': 'compliance check',
    'oem-coop': 'OEM co-op claim'
  };
  return { displayLabel: typeLabels[item.type] || null };
}

