const STATUS_CONFIG = {
  awaiting_approval: { label: 'Awaiting approval', color: t.warning, bg: t.warningSoft },
  queued: { label: 'Queued', color: t.textSecondary, bg: t.surfaceMuted },
  active: { label: 'Active', color: t.success, bg: t.successSoft },
  paused: { label: 'Paused', color: t.textTertiary, bg: t.surfaceMuted },
  ended: { label: 'Ended', color: t.textTertiary, bg: t.surfaceMuted }
};

// ============= FILTER PILL =============
// Dropdown-style filter for the campaign filter strip. Click to open.
function FilterPill({ label, value, options, onChange }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  
  useEffect(() => {
    const onDocClick = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    if (open) document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [open]);
  
  const currentLabel = options.find(o => o.value === value)?.label || 'All';
  const isActive = value !== 'all';
  
  return (
    <div ref={ref} style={{ position: 'relative' }}>
      <button
        onClick={() => setOpen(!open)}
        style={{
          padding: '7px 10px 7px 12px',
          background: isActive ? t.accentSoft : t.surface,
          color: isActive ? t.accent : t.textSecondary,
          border: 'none',
          borderRadius: '8px',
          fontSize: '12px', fontWeight: 500,
          cursor: 'pointer',
          fontFamily: fontStack,
          display: 'flex', alignItems: 'center', gap: '5px',
          whiteSpace: 'nowrap'
        }}
        onMouseEnter={(e) => { if (!isActive) e.currentTarget.style.background = t.surfaceMuted; }}
        onMouseLeave={(e) => { if (!isActive) e.currentTarget.style.background = t.surface; }}
      >
        <span style={{ color: isActive ? t.accent : t.textTertiary, fontWeight: 600 }}>
          {label}{isActive ? ': ' : ''}
        </span>
        {isActive && <span>{currentLabel}</span>}
        <ChevronDown size={11} strokeWidth={2} style={{ marginTop: '1px' }} />
      </button>
      {open && (
        <div style={{
          position: 'absolute',
          top: 'calc(100% + 4px)',
          left: 0,
          minWidth: '180px',
          background: t.bgPrimary,
          borderRadius: '10px',
          boxShadow: '0 8px 24px rgba(22,22,22,0.12), 0 2px 6px rgba(22,22,22,0.06)',
          padding: '6px',
          zIndex: 50
        }}>
          {options.map(opt => (
            <button
              key={opt.value}
              onClick={() => { onChange(opt.value); setOpen(false); }}
              style={{
                width: '100%',
                padding: '8px 12px',
                background: opt.value === value ? t.accentSoft : 'transparent',
                color: opt.value === value ? t.accent : t.textPrimary,
                border: 'none',
                borderRadius: '6px',
                fontSize: '12px',
                fontWeight: opt.value === value ? 600 : 500,
                cursor: 'pointer',
                fontFamily: fontStack,
                textAlign: 'left',
                display: 'flex', alignItems: 'center', justifyContent: 'space-between'
              }}
              onMouseEnter={(e) => { if (opt.value !== value) e.currentTarget.style.background = t.surface; }}
              onMouseLeave={(e) => { if (opt.value !== value) e.currentTarget.style.background = 'transparent'; }}
            >
              <span>{opt.label}</span>
              {opt.value === value && <Check size={12} strokeWidth={2.5} />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function CampaignsWorkspace({ isTablet, isSmall, onDiscuss, onSelectCampaign }) {
  const [campaignsTab, setCampaignsTab] = useState('ongoing');
  
  // Filter state - Department + Funding only (Status is replaced by tab)
  // These filters apply ONLY to the tab content below, not to Needs your approval.
  const [filterDept, setFilterDept] = useState('all');
  const [filterFund, setFilterFund] = useState('all');
  
  // Needs your approval - pulls from unfiltered pool, status='awaiting_approval' OR awaitingDirection=true
  // (campaigns AI is asking the user to make a call on, regardless of run state).
  // Cap at 3 to keep this zone focused on the active test scenarios; other
  // awaiting_approval campaigns in seed are intentionally hidden for now.
  const needsApproval = CAMPAIGNS_SEED.filter(c =>
    c.status === 'awaiting_approval' || c.awaitingDirection === true
  );
  
  // Tab content - apply Department + Funding filters here
  const filteredForTabs = CAMPAIGNS_SEED.filter(c => {
    if (filterDept !== 'all' && c.department !== filterDept) return false;
    if (filterFund !== 'all' && c.funding !== filterFund) return false;
    return true;
  });
  
  // Bucket the filtered pool by status. Exclude items already shown in Needs your approval
  // so users don't see the same campaign in two places.
  const ongoing = filteredForTabs.filter(c =>
    (c.status === 'active' || c.status === 'paused')
    && c.awaitingDirection !== true
  );
  const upcoming = filteredForTabs.filter(c => c.status === 'queued');
  const ended = filteredForTabs.filter(c => c.status === 'ended');
  
  // Sort comparators. needsApproval sorts by explicit priority (lower number
  // first) so the test-scenario campaigns float to the top of the Campaigns
  // workspace just as they do on Home and Inbox. Items without a priority
  // fall back to attention-need.
  const sortByPriority = (a, b) => {
    const ap = a.priority ?? Infinity;
    const bp = b.priority ?? Infinity;
    if (ap !== bp) return ap - bp;
    if (a.needsAttention !== b.needsAttention) return a.needsAttention ? -1 : 1;
    return 0;
  };
  const sortByAttention = (a, b) => {
    if (a.needsAttention !== b.needsAttention) return a.needsAttention ? -1 : 1;
    return 0;
  };
  needsApproval.sort(sortByPriority);
  // For the current test push, only the top 3 (the three test scenarios:
  // c_acq, c_serv, c_ret with priorities 1/2/3) should appear in the
  // Campaigns tab's needs-approval zone. Other awaiting_approval campaigns
  // remain in seed for use elsewhere; this is a presentation cap only.
  const visibleNeedsApproval = needsApproval.slice(0, 3);
  ongoing.sort(sortByAttention);
  upcoming.sort(sortByAttention);
  
  const anyFilterActive = filterDept !== 'all' || filterFund !== 'all';
  
  // Performance tab summary - simple aggregates from ended campaigns
  const endedTotalGross = ended.reduce((s, c) => s + (c.actual?.gross || c.projected?.gross || 0), 0);
  const endedAvgRoas = ended.length > 0
    ? ended.reduce((s, c) => s + (c.actual?.roas || 0), 0) / ended.length
    : 0;
  
  // What goes in active tab?
  const tabItems = campaignsTab === 'ongoing' ? ongoing
    : campaignsTab === 'upcoming' ? upcoming
    : ended;
  
  return (
    <div>
      {/* Needs your approval - top section, NOT affected by Department/Funding filters.
          Capped to the top 3 by the visibleNeedsApproval slice. */}
      {visibleNeedsApproval.length > 0 && (
        <CampaignSection
          title="Needs your approval"
          count={visibleNeedsApproval.length}
          items={visibleNeedsApproval}
          onSelectCampaign={onSelectCampaign}
          onDiscuss={onDiscuss}
          isSmall={isSmall}
          forceRich
        />
      )}
      
      {/* Tab strip - sticky to top of scroll area so the page anchors during tab switches */}
      <div style={{
        position: 'sticky',
        top: 0,
        zIndex: 5,
        background: t.bgPrimary,
        display: 'flex',
        gap: '4px',
        borderBottom: '1px solid ' + t.surfaceMuted,
        marginBottom: '20px',
        paddingTop: '4px'
      }}>
        {[
          { id: 'ongoing', label: 'Ongoing', count: ongoing.length },
          { id: 'upcoming', label: 'Upcoming', count: upcoming.length },
          { id: 'performance', label: 'Performance', count: ended.length }
        ].map(tabDef => (
          <button
            key={tabDef.id}
            onClick={() => setCampaignsTab(tabDef.id)}
            style={{
              padding: '10px 14px',
              background: 'transparent',
              color: campaignsTab === tabDef.id ? t.textPrimary : t.textSecondary,
              border: 'none',
              borderBottom: '2px solid ' + (campaignsTab === tabDef.id ? t.accent : 'transparent'),
              borderRadius: 0,
              fontSize: '13px',
              fontWeight: campaignsTab === tabDef.id ? 600 : 500,
              cursor: 'pointer',
              fontFamily: fontStack,
              marginBottom: '-1px',
              display: 'flex', alignItems: 'center', gap: '6px'
            }}
          >
            {tabDef.label}
            {tabDef.count > 0 && (
              <span style={{
                fontSize: '11px',
                fontWeight: 500,
                color: t.textTertiary,
                fontFamily: fontStack,
                fontVariantNumeric: 'tabular-nums'
              }}>
                {tabDef.count}
              </span>
            )}
          </button>
        ))}
      </div>
      
      {/* Filters inside tab area - Department + Funding apply to tab content only */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '12px',
        marginBottom: '20px',
        flexWrap: 'wrap'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
          <FilterPill
            label="Department"
            value={filterDept}
            options={[
              { value: 'all', label: 'All' },
              { value: 'sales', label: 'Sales' },
              { value: 'service', label: 'Service' },
              { value: 'parts', label: 'Parts' }
            ]}
            onChange={setFilterDept}
          />
          <FilterPill
            label="Funding"
            value={filterFund}
            options={[
              { value: 'all', label: 'All' },
              { value: 'self', label: 'Self-funded' },
              { value: 'oem', label: 'OEM co-op' },
              { value: 'mixed', label: 'Mixed' }
            ]}
            onChange={setFilterFund}
          />
          {anyFilterActive && (
            <button
              onClick={() => { setFilterDept('all'); setFilterFund('all'); }}
              style={{
                padding: '7px 10px',
                background: 'transparent',
                color: t.textTertiary,
                border: 'none',
                fontSize: '11px', fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => e.currentTarget.style.color = t.textPrimary}
              onMouseLeave={(e) => e.currentTarget.style.color = t.textTertiary}
            >
              Clear filters
            </button>
          )}
        </div>
        
        <button
          onClick={() => alert('Manual campaign creation - coming next round')}
          style={{
            padding: '7px 12px',
            background: 'transparent',
            color: t.textSecondary,
            border: 'none',
            borderRadius: '8px',
            fontSize: '12px', fontWeight: 500,
            cursor: 'pointer',
            fontFamily: fontStack,
            display: 'flex', alignItems: 'center', gap: '5px'
          }}
          onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
          onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
        >
          <Plus size={12} strokeWidth={2} />
          Create campaign
        </button>
      </div>
      
      {/* Performance tab summary */}
      {campaignsTab === 'performance' && ended.length > 0 && (
        <div style={{
          padding: '14px 16px',
          background: t.surface,
          borderRadius: '10px',
          marginBottom: '16px',
          display: 'flex', alignItems: 'center', gap: '24px', flexWrap: 'wrap'
        }}>
          <div>
            <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, marginBottom: '2px' }}>
              Ended
            </div>
            <div style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
              {ended.length} campaigns
            </div>
          </div>
          <div>
            <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, marginBottom: '2px' }}>
              Total attributed gross
            </div>
            <div style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
              ${(endedTotalGross / 1000000).toFixed(2)}M
            </div>
          </div>
          <div>
            <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, marginBottom: '2px' }}>
              Average ROAS
            </div>
            <div style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
              {endedAvgRoas.toFixed(1)}x
            </div>
          </div>
        </div>
      )}
      
      {/* Tab content */}
      {tabItems.length === 0 ? (
        <div style={{
          padding: '48px 32px',
          textAlign: 'center',
          background: t.surface,
          borderRadius: '12px',
          color: t.textSecondary
        }}>
          <div style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary, marginBottom: '6px' }}>
            {anyFilterActive ? 'No campaigns match these filters' : 'Nothing here yet'}
          </div>
          <div style={{ fontSize: '13px', color: t.textTertiary }}>
            {anyFilterActive ? 'Adjust your filters to see more.'
              : campaignsTab === 'ongoing' ? 'No campaigns are running right now.'
              : campaignsTab === 'upcoming' ? 'No campaigns are queued to launch.'
              : 'No completed campaigns yet.'}
          </div>
        </div>
      ) : (
        <CampaignSection
          title=""
          count={tabItems.length}
          items={tabItems}
          onSelectCampaign={onSelectCampaign}
          onDiscuss={onDiscuss}
          isSmall={isSmall}
          dimmed={campaignsTab === 'performance'}
        />
      )}
    </div>
  );
}

// ============= CAMPAIGN SECTION =============
function CampaignSection({ title, subtitle, count, items, onSelectCampaign, onDiscuss, isSmall, forceRich, dimmed, collapsible, onCollapse }) {
  const showHeader = title && title.length > 0;
  return (
    <div style={{ marginBottom: '32px' }}>
      {showHeader && (
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: '12px', gap: '12px', flexWrap: 'wrap' }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
              <h2 style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, margin: 0, letterSpacing: '-0.005em' }}>
                {title}
              </h2>
              <span style={{ fontSize: '12px', color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', fontWeight: 500 }}>
                {count}
              </span>
            </div>
            {subtitle && (
              <p style={{ fontSize: '12px', color: t.textTertiary, margin: '4px 0 0', lineHeight: 1.5 }}>
                {subtitle}
              </p>
            )}
          </div>
          {collapsible && (
            <button
              onClick={onCollapse}
              style={{
                padding: '6px 12px', background: 'transparent',
                color: t.textSecondary,
                border: 'none', borderRadius: '8px',
                fontSize: '12px', fontWeight: 600,
                cursor: 'pointer', fontFamily: fontStack,
                display: 'flex', alignItems: 'center', gap: '5px'
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = t.surface}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              <ChevronUp size={12} /> Hide
            </button>
          )}
        </div>
      )}
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        {items.map(item => (
          <CampaignRow
            key={item.id}
            item={item}
            onClick={() => onSelectCampaign(item)}
            onDiscuss={onDiscuss}
            isSmall={isSmall}
            forceRich={forceRich}
            dimmed={dimmed}
          />
        ))}
      </div>
    </div>
  );
}

// ============= CAMPAIGN ROW =============
function CampaignRow({ item, onClick, onDiscuss, isSmall, forceRich, dimmed }) {
  // forceRich is set on the "Needs your approval" section -> ApprovalCard pattern.
  // Everything else (Ongoing, Upcoming, Performance) uses the overview card pattern.
  if (forceRich) {
    return <CampaignRichCard item={item} onClick={onClick} onDiscuss={onDiscuss} isSmall={isSmall} />;
  }
  return <CampaignOverviewCard item={item} onClick={onClick} isSmall={isSmall} dimmed={dimmed} />;
}

// ============= CAMPAIGN RICH CARD =============
// Used in 'Needs your approval' zone of CampaignsWorkspace. Maps a campaign
// item into ApprovalCard's simplified shape.
function CampaignRichCard({ item, onClick, onDiscuss, isSmall }) {
  // Unified read path: prefer the campaign's approval block (the new spec)
  // so this card looks identical to the Home and Inbox version of the same
  // campaign. Fall back to the legacy synthesis for campaigns that haven't
  // been migrated to the new shape yet.
  const approval = item.approval;
  
  // Curated AI content for the three test scenarios (a_acq / a_serv / a_ret)
  // is keyed off the approval id. Map the campaign id to the approval id
  // so the Campaigns tab card opens the same realistic popover content
  // that Home does for the same campaign.
  const campaignToApprovalId = { c_acq: 'a_acq', c_serv: 'a_serv', c_ret: 'a_ret' };
  const aiContent = getApprovalDiscussContent({
    id: campaignToApprovalId[item.id] || item.id,
    type: approval ? approval.type : 'campaign-new'
  });
  
  if (approval) {
    return (
      <Discussable
        label={approval.heading}
        displayLabel={aiContent.displayLabel}
        description={aiContent.description}
        suggestedChips={aiContent.suggestedChips}
        prefilledQuestion={'Tell me about ' + item.name + '. Why are you proposing it?'}
        onDiscuss={onDiscuss}
        style={{ borderRadius: '10px' }}
      >
        <ApprovalCard
          type={approval.type}
          heading={approval.heading}
          description={approval.description}
          meta={approval.meta}
          ctaLabel={approval.ctaLabel || 'Review'}
          onView={onClick}
          onDismiss={() => onDiscuss({
            label: item.name,
            displayLabel: aiContent.displayLabel,
            description: aiContent.description,
            suggestedChips: aiContent.suggestedChips,
            prefilledQuestion: 'Tell me about ' + item.name + '. Why are you proposing it?'
          })}
        />
      </Discussable>
    );
  }
  
  // Legacy path - synthesize headline/meta from raw campaign fields. Used
  // only for campaigns that don't yet have a structured approval block.
  let kind = 'campaign-plan';
  if (item.objective && item.objective.toLowerCase().includes('compliance')) kind = 'compliance';
  
  const meta = [];
  if (item.startDate && item.endDate) {
    meta.push(formatRangeShort(item.startDate, item.endDate));
  }
  if (item.audience?.size) {
    meta.push(item.audience.size.toLocaleString() + ' customers');
  }
  if (item.budget) {
    meta.push('$' + (item.budget / 1000).toFixed(0) + 'K budget');
  }
  if (item.actual?.pace !== undefined && item.actual.pace !== 0) {
    meta.push((item.actual.pace > 0 ? '+' : '') + item.actual.pace + '% pacing');
  }
  
  return (
    <Discussable
      label={item.actionPrompt || item.name}
      displayLabel="campaign"
      prefilledQuestion={'Tell me about ' + item.name + '. Why are you proposing it?'}
      onDiscuss={onDiscuss}
      style={{ borderRadius: '10px' }}
    >
      <ApprovalCard
        type={kind}
        heading={item.actionPrompt || item.name}
        description={item.aiCommentary || item.description}
        meta={meta}
        ctaLabel="Review"
        onView={onClick}
        onDismiss={() => onDiscuss({
          label: item.name,
          displayLabel: 'campaign',
          prefilledQuestion: 'Tell me about ' + item.name + '. Why are you proposing it?'
        })}
      />
    </Discussable>
  );
}

// ============= CAMPAIGN OVERVIEW CARD =============
// Used in Ongoing, Upcoming, and Performance tabs. Shows a 3-second-readable
// summary: name, classification, audience, budget, time strip with progress bar,
// primary metric appropriate to the campaign's lifecycle stage.
function CampaignOverviewCard({ item, onClick, isSmall, dimmed }) {
  // Funding label
  const fundingLabel = item.funding === 'self' ? 'Self-funded'
    : item.funding === 'oem' ? 'OEM co-op'
    : item.funding === 'mixed' ? 'Mixed funding'
    : null;
  
  // Date computations - "today" matches the prototype's TODAY_ISO
  const today = new Date('2026-05-08T00:00:00');
  const start = item.startDate ? new Date(item.startDate + 'T00:00:00') : null;
  const end = item.endDate ? new Date(item.endDate + 'T00:00:00') : null;
  const dayMs = 24 * 60 * 60 * 1000;
  
  let progressPct = 0;
  let timeLabel = '';
  let progressColor = t.textSecondary;
  
  if (item.status === 'active' || item.status === 'paused') {
    if (start && end) {
      const totalMs = end - start;
      const elapsedMs = today - start;
      progressPct = Math.max(0, Math.min(100, (elapsedMs / totalMs) * 100));
      const daysLeft = Math.ceil((end - today) / dayMs);
      timeLabel = formatRangeShort(item.startDate, item.endDate) + ' \u00b7 ' +
        (daysLeft > 0 ? daysLeft + ' day' + (daysLeft === 1 ? '' : 's') + ' left' : 'Ending today');
    }
  } else if (item.status === 'queued') {
    progressPct = 0;
    if (start) {
      const daysUntil = Math.ceil((start - today) / dayMs);
      timeLabel = 'Launches ' + start.toLocaleString('en-US', { month: 'short', day: 'numeric' }) +
        ' \u00b7 ' + (daysUntil > 0 ? daysUntil + ' day' + (daysUntil === 1 ? '' : 's') + ' from now' : 'Starts today');
    }
  } else if (item.status === 'ended') {
    progressPct = 100;
    if (start && end) {
      const totalDays = Math.round((end - start) / dayMs);
      timeLabel = formatRangeShort(item.startDate, item.endDate) + ' \u00b7 ' + totalDays + ' day' + (totalDays === 1 ? '' : 's');
    }
  }
  
  // Primary metric (right-side anchor on time strip row)
  let metricLabel = '';
  let metricValue = '';
  if (item.status === 'active' || item.status === 'paused') {
    if (item.actual?.pace !== undefined) {
      const sign = item.actual.pace > 0 ? '+' : '';
      metricValue = sign + item.actual.pace + '%';
      metricLabel = 'Pacing';
    } else if (item.actual?.roas) {
      metricValue = item.actual.roas.toFixed(1) + 'x';
      metricLabel = 'ROAS';
    }
  } else if (item.status === 'queued') {
    if (item.projected?.roas) {
      metricValue = item.projected.roas.toFixed(1) + 'x';
      metricLabel = 'Projected ROAS';
    }
  } else if (item.status === 'ended') {
    if (item.actual?.roas) {
      metricValue = item.actual.roas.toFixed(1) + 'x';
      metricLabel = 'Final ROAS';
    } else if (item.projected?.roas) {
      metricValue = item.projected.roas.toFixed(1) + 'x';
      metricLabel = 'Projected ROAS';
    }
  }
  
  // Money facts line - varies by lifecycle stage
  const moneyFacts = [];
  if (item.audience?.size) {
    moneyFacts.push(item.audience.size.toLocaleString() + ' customers');
  }
  if (item.budget) {
    moneyFacts.push('$' + Math.round(item.budget / 1000) + 'K budget');
  }
  if (item.status === 'active' || item.status === 'paused') {
    if (item.spent !== undefined) {
      const pct = Math.round((item.spent / item.budget) * 100);
      moneyFacts.push('$' + Math.round(item.spent / 1000) + 'K spent (' + pct + '%)');
    }
  } else if (item.status === 'queued') {
    if (item.projected?.gross) {
      moneyFacts.push('$' + Math.round(item.projected.gross / 1000) + 'K projected gross');
    }
  } else if (item.status === 'ended') {
    if (item.actual?.gross) {
      moneyFacts.push('$' + Math.round(item.actual.gross / 1000) + 'K attributed gross');
    } else if (item.projected?.gross) {
      moneyFacts.push('$' + Math.round(item.projected.gross / 1000) + 'K projected gross');
    }
  }
  
  return (
    <div
      onClick={onClick}
      style={{
        padding: '16px 18px',
        background: t.surface,
        borderRadius: '10px',
        cursor: 'pointer',
        transition: 'background 0.12s',
        opacity: dimmed ? 0.75 : 1
      }}
      onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; }}
      onMouseLeave={(e) => { e.currentTarget.style.background = t.surface; }}
    >
      {/* Row 1: Name + objective/funding */}
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: '12px', marginBottom: '4px', flexWrap: 'wrap' }}>
        <h3 style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary, margin: 0, lineHeight: 1.35, letterSpacing: '-0.005em' }}>
          {item.name}
        </h3>
      </div>
      <div style={{ fontSize: '12px', color: t.textTertiary, fontWeight: 500 }}>
        {item.objective}{fundingLabel ? ' \u00b7 ' + fundingLabel : ''}
      </div>
      
      {/* Row 2: Money facts strip */}
      {moneyFacts.length > 0 && (
        <div style={{
          marginTop: '10px',
          display: 'flex', alignItems: 'center', gap: '8px',
          flexWrap: 'wrap',
          fontSize: '12px', color: t.textSecondary,
          fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
        }}>
          {moneyFacts.map((f, i) => (
            <React.Fragment key={i}>
              {i > 0 && <span style={{ color: t.textTertiary }}>·</span>}
              <span>{f}</span>
            </React.Fragment>
          ))}
        </div>
      )}
      
      {/* Row 3: Progress bar */}
      <div style={{ marginTop: '12px' }}>
        <div style={{
          height: '4px',
          background: t.surfaceMuted,
          borderRadius: '2px',
          overflow: 'hidden'
        }}>
          <div style={{
            height: '100%',
            width: progressPct + '%',
            background: item.status === 'ended' ? t.textTertiary : t.accent,
            borderRadius: '2px',
            transition: 'width 0.3s'
          }} />
        </div>
        
        {/* Row 4: Time label + primary metric */}
        <div style={{
          marginTop: '8px',
          display: 'flex',
          alignItems: 'baseline',
          justifyContent: 'space-between',
          gap: '12px',
          flexWrap: 'wrap'
        }}>
          <span style={{ fontSize: '12px', color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
            {timeLabel}
          </span>
          {metricValue && (
            <span style={{ display: 'flex', alignItems: 'baseline', gap: '6px' }}>
              <span style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500 }}>
                {metricLabel}
              </span>
              <span style={{ fontSize: '13px', fontWeight: 600, color: t.textPrimary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
                {metricValue}
              </span>
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

function formatRangeShort(start, end) {
  const s = new Date(start + 'T00:00:00');
  const e = new Date(end + 'T00:00:00');
  const sM = s.toLocaleString('en-US', { month: 'short' });
  const eM = e.toLocaleString('en-US', { month: 'short' });
  if (sM === eM) {
    return sM + ' ' + s.getDate() + '-' + e.getDate();
  }
  return sM + ' ' + s.getDate() + ' - ' + eM + ' ' + e.getDate();
}

// ============= CAMPAIGN DETAIL PAGE =============
// Full-page campaign view with two modes:
//   - Build mode (status: awaiting_approval): stage-gated approval (plan/creative/publish)
//   - Monitor mode (active/paused/queued/ended): single-column live state
// Status block (header) combines KPIs + pacing bar in one unit.
// Compliance is the last ingredient section, always visible.
// Phases (multi-phase only) is an ingredient row with click-to-expand cards.

const ICON_MAP = {
  Car, Users, Tag, DollarSign, Calendar, Target, Layers,
  Workflow, ArrowRight, ArrowUpRight, Truck, Clock, ImageIcon, BarChart3, Mail,
  MessageCircle, MessageSquare, Send, ShieldCheck, Shield, Compass, CheckCircle2,
  AlertCircle, GitBranch, Share2, Smartphone, Sparkles,
  TrendingDown, Edit2
};
function resolveIcon(name) { return ICON_MAP[name] || Target; }

// Scroll helpers.
// In this app the scroll container could be either <main> (declared as overflow:auto)
// or the document/window. Which one actually scrolls depends on whether the ancestor
// chain provides bounded height. To be robust we set scroll on both; the non-scrolling
// one's set is a harmless no-op. For reads we take whichever is non-zero (only the
// actual scroll container will have a non-zero scrollTop).
function getScrollTop() {
  const main = document.querySelector('main');
  const doc = document.scrollingElement || document.documentElement;
  const mainTop = main ? main.scrollTop : 0;
  const docTop = doc ? doc.scrollTop : (window.scrollY || 0);
  return Math.max(mainTop, docTop);
}
function setScrollTop(value) {
  const main = document.querySelector('main');
  const doc = document.scrollingElement || document.documentElement;
  if (main) main.scrollTop = value;
  if (doc) doc.scrollTop = value;
}
function adjustScrollBy(delta) {
  const main = document.querySelector('main');
  const doc = document.scrollingElement || document.documentElement;
  // Only the actually-scrolling container has non-zero scrollTop, so only it
  // can be adjusted meaningfully. Setting on the other is a no-op but harmless.
  if (main && main.scrollTop > 0) main.scrollTop += delta;
  else if (doc && doc.scrollTop > 0) doc.scrollTop += delta;
  else if (main) main.scrollTop += delta;
  else if (doc) doc.scrollTop += delta;
  else window.scrollBy(0, delta);
}

function CampaignDetailPage({ campaign: initialCampaign, onBack, backLabel, onDiscuss, isSmall }) {
  const [stage, setStage] = useState(initialCampaign.approvalStage || 'approved');
  const [pulsedTarget, setPulsedTarget] = useState(null);
  // aiWorking lives in app-level context so the CompactAskBar (mounted in App)
  // can react to it. Local consumers of the build body still see it via props.
  const { aiWorking, setAiWorking, setDoneFlash } = useContext(AiWorkingContext);
  const ingredientRefs = useRef({});
  const previousStageRef = useRef(stage);
  
  // Edit canvas state. canvasOpen holds the row config we are editing (or null).
  // refineSignal is a counter incremented each time a canvas saves; rows watch
  // their matching canvasSavedTarget to trigger their refining animation.
  // We use a counter (not a boolean) so the same row can be edited twice in a row
  // and still re-trigger the animation.
  const [canvasOpen, setCanvasOpen] = useState(null);
  const [canvasSavedTarget, setCanvasSavedTarget] = useState({ rowId: null, signal: 0 });
  
  const openCanvas = (config) => {
    setCanvasOpen(config);
  };
  const closeCanvas = () => {
    setCanvasOpen(null);
  };
  const saveCanvas = () => {
    if (canvasOpen) {
      const rowId = canvasOpen.rowId;
      setCanvasSavedTarget(prev => ({ rowId, signal: prev.signal + 1 }));
    }
    setCanvasOpen(null);
  };
  
  // Floating "back to top" button state.
  // Appears when the top "Back to campaigns" link scrolls out of view (so the
  // user has lost their easy way to leave the campaign). Click scrolls the page
  // to the very top so the original link is visible again.
  const backNavRef = useRef(null);
  const [showScrollToTop, setShowScrollToTop] = useState(false);
  
  // Watch the CampaignBackNav element. When its bottom edge scrolls above the
  // viewport top, we show the floating button. We attach scroll listeners on
  // both window AND any scrollable ancestors (could be <main> or document
  // depending on layout).
  useEffect(() => {
    const el = backNavRef.current;
    if (!el) return;
    
    const scrollableAncestors = [];
    let parent = el.parentElement;
    while (parent && parent !== document.body) {
      const style = window.getComputedStyle(parent);
      const overflowY = style.overflowY;
      if (overflowY === 'auto' || overflowY === 'scroll') {
        scrollableAncestors.push(parent);
      }
      parent = parent.parentElement;
    }
    
    const checkPosition = () => {
      if (!backNavRef.current) return;
      const rect = backNavRef.current.getBoundingClientRect();
      // Show the button when the back nav is above the visible viewport.
      // -8 gives a tiny buffer before the button appears.
      setShowScrollToTop(rect.bottom < -8);
    };
    
    checkPosition();
    window.addEventListener('scroll', checkPosition, { passive: true });
    scrollableAncestors.forEach(node => {
      node.addEventListener('scroll', checkPosition, { passive: true });
    });
    window.addEventListener('resize', checkPosition, { passive: true });
    
    return () => {
      window.removeEventListener('scroll', checkPosition);
      window.removeEventListener('resize', checkPosition);
      scrollableAncestors.forEach(node => {
        node.removeEventListener('scroll', checkPosition);
      });
    };
  }, [initialCampaign.id]);
  
  // Scroll handler for the floating button. Smooth-scroll to the very top so
  // the back nav comes into view.
  const scrollToTop = () => {
    setScrollTop(0);
    // setScrollTop is instant; for a smoother feel, animate it
    const main = document.querySelector('main');
    if (main && main.scrollTo) main.scrollTo({ top: 0, behavior: 'smooth' });
    const doc = document.scrollingElement || document.documentElement;
    if (doc && doc.scrollTo) doc.scrollTo({ top: 0, behavior: 'smooth' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  
  // Anchor to top on mount and whenever a new campaign loads. For build-mode
  // campaigns (awaiting_approval), trigger the cold-start animation so users
  // can demo the build experience by re-clicking the tile from Home, Campaigns,
  // or Inbox.
  useLayoutEffect(() => {
    setScrollTop(0);
    const initialStage = initialCampaign.approvalStage || 'approved';
    setStage(initialStage);
    previousStageRef.current = initialStage;
    // Cold-start animation fires only for campaigns explicitly marked as
    // "build from scratch" - meaning AI proposes the opportunity but hasn't
    // drafted the plan yet. For Stage 2 (plan ready, creatives pending) and
    // Stage 3 (everything drafted) campaigns, the user lands on the rendered
    // campaign directly.
    if (initialCampaign.presentationMode === 'build_from_scratch') {
      setAiWorking('coldStart');
    } else {
      setAiWorking(null);
    }
  }, [initialCampaign.id]);
  
  // When stage advances forward, smooth-scroll to the newly revealed content.
  // Stage transitions are handled visually by AI animation completion.
  // Scroll anchoring happens in advanceStage when AI starts, not after the
  // animation completes, so users see the generation in progress.
  useEffect(() => {
    previousStageRef.current = stage;
  }, [stage]);
  
  const campaign = initialCampaign;
  const isBuildMode = campaign.status === 'awaiting_approval';
  
  // Approval flow gates through AI animations. Click Approve plan -> AI generates
  // creatives (animation) -> stage advances to creative. Click Approve campaign ->
  // AI finalizes for launch (animation) -> stage advances to approved.
  //
  // Scroll anchors to the section as soon as AI starts working on it, so the
  // user sees the generation in progress rather than jumping in once content
  // is fully rendered.
  const advanceStage = () => {
    if (stage === 'plan') {
      setAiWorking('creative');
      // Scroll to the creative row immediately so the in-progress animation
      // is visible from the start.
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          const creativeRow = ingredientRefs.current['creative'];
          if (creativeRow) {
            creativeRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
          }
        });
      });
    } else if (stage === 'creative') {
      setAiWorking('launch');
      // Scroll to the bottom where the launch animation will render
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          const scrollEl = document.scrollingElement || document.documentElement;
          const target = (scrollEl ? scrollEl.scrollHeight : document.body.scrollHeight);
          const main = document.querySelector('main');
          if (main) main.scrollTo({ top: main.scrollHeight, behavior: 'smooth' });
          if (scrollEl && 'scrollTo' in scrollEl) scrollEl.scrollTo({ top: target, behavior: 'smooth' });
          else window.scrollTo({ top: target, behavior: 'smooth' });
        });
      });
    }
  };
  
  // Called from AiAtWork's onComplete callback. Commits the stage advance
  // and clears the working state so the new content can render normally.
  const handleAiComplete = () => {
    if (aiWorking === 'coldStart') {
      setAiWorking(null);
      setDoneFlash({ kind: 'coldStart' });
    } else if (aiWorking === 'creative') {
      setAiWorking(null);
      setDoneFlash({ kind: 'creative' });
      setStage('creative');
    } else if (aiWorking === 'launch') {
      setAiWorking(null);
      setDoneFlash({ kind: 'launch' });
      setStage('approved');
    }
  };
  
  // Triggered by the "Rebuild from scratch" button in the header.
  // Resets stage to plan and runs the cold-start animation, then re-reveals
  // the ingredient list with the seed data (effectively a demo re-run).
  const triggerColdStart = () => {
    setStage('plan');
    setAiWorking('coldStart');
    requestAnimationFrame(() => setScrollTop(0));
  };
  
  const revertStage = (target) => setStage(target);
  
  const registerRef = (id, el) => {
    if (el) ingredientRefs.current[id] = el;
  };
  
  const scrollToTarget = (id) => {
    if (!id) return;
    const el = ingredientRefs.current[id];
    if (!el) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    setPulsedTarget(id);
    setTimeout(() => setPulsedTarget(curr => curr === id ? null : curr), 1400);
  };
  
  return (
    <div>
      {/* Pulse animation keyframes */}
      <style>{`
        @keyframes campaignPulse {
          0% { background-color: transparent; }
          25% { background-color: ${t.accentSoft}; }
          75% { background-color: ${t.accentSoft}; }
          100% { background-color: transparent; }
        }
        @keyframes aiStepIn {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes aiProgress {
          from { width: 0%; }
          to { width: 100%; }
        }
        @keyframes aiOrbit {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        @keyframes iconShimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes aiCommentaryIn {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes popoverIn {
          from { opacity: 0; transform: translateY(-4px) scale(0.98); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes refineGlow {
          0% { background-color: transparent; }
          30% { background-color: ${t.accentSoft}; }
          70% { background-color: ${t.accentSoft}; }
          100% { background-color: transparent; }
        }
        @keyframes canvasFadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes canvasSlideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes sheetSlideIn {
          from { transform: translateX(100%); }
          to { transform: translateX(0); }
        }
      `}</style>
      
      <CampaignBackNav onBack={onBack} navRef={backNavRef} label={backLabel} />
      <CampaignHeader campaign={campaign} isSmall={isSmall} isBuildMode={isBuildMode} onRebuild={triggerColdStart} aiWorking={aiWorking} />
      
      {isBuildMode
        ? <CampaignBuildBody campaign={campaign} stage={stage} advanceStage={advanceStage} revertStage={revertStage} onDiscuss={onDiscuss} onEdit={openCanvas} canvasSavedTarget={canvasSavedTarget} registerRef={registerRef} pulsedTarget={pulsedTarget} aiWorking={aiWorking} onAiComplete={handleAiComplete} />
        : <CampaignMonitorBody campaign={campaign} onDiscuss={onDiscuss} onEdit={openCanvas} canvasSavedTarget={canvasSavedTarget} registerRef={registerRef} pulsedTarget={pulsedTarget} />
      }
      
      {/* Floating "scroll to top" button. Appears when the user has scrolled
          past the top "Back to campaigns" link. Same x-axis as the Ask bar on
          wider screens; stacked above the Ask bar on small viewports.
          Visual styling (height, radius, shadow, icon size) matches the Ask
          bar so they read as a pair. */}
      {showScrollToTop && (
        <button
          onClick={scrollToTop}
          aria-label="Scroll to top"
          style={{
            position: 'fixed',
            bottom: isSmall ? '76px' : '24px',
            right: isSmall ? '16px' : '32px',
            width: '42px',
            height: '42px',
            borderRadius: '14px',
            background: t.bgPrimary,
            border: 'none',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: t.textPrimary,
            boxShadow: '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)',
            zIndex: 65,
            transition: 'transform 0.15s, box-shadow 0.15s',
            animation: 'fadeIn 0.18s ease'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = 'translateY(-2px)';
            e.currentTarget.style.boxShadow = '0 6px 20px rgba(22,22,22,0.08), 0 1px 3px rgba(22,22,22,0.04)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'translateY(0)';
            e.currentTarget.style.boxShadow = '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)';
          }}
        >
          <ChevronUp size={16} strokeWidth={2} />
        </button>
      )}
      
      {/* Edit canvas overlay (covers viewport when a section's Edit is clicked). */}
      {canvasOpen && (
        <CanvasOverlay
          rowId={canvasOpen.rowId}
          rowLabel={canvasOpen.rowLabel}
          iconName={canvasOpen.iconName}
          subId={canvasOpen.subId}
          campaign={campaign}
          onSave={saveCanvas}
          onCancel={closeCanvas}
        />
      )}
    </div>
  );
}

// ----- Back nav -----
function CampaignBackNav({ onBack, navRef, label }) {
  return (
    <div ref={navRef} style={{ marginBottom: '20px' }}>
      <button
        onClick={onBack}
        style={{
          display: 'flex', alignItems: 'center', gap: '6px',
          padding: '8px 12px 8px 8px',
          background: 'transparent', color: t.textSecondary,
          border: 'none', borderRadius: '8px',
          fontSize: '13px', fontWeight: 500,
          cursor: 'pointer', fontFamily: fontStack,
          marginLeft: '-8px'
        }}
        onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
        onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
      >
        <ChevronLeft size={16} strokeWidth={1.75} />
        {label || 'Back to campaigns'}
      </button>
    </div>
  );
}

// ----- Header: title + classification + summary + status block -----
// Order is intentional: orient (title) -> understand (summary) -> measure (status).
// Resolves a campaign's raw status into a header-chip config. Four states the
// user actually sees on the campaign detail page:
//   Pending Review (orange) - awaiting any approval gate
//   Scheduled (grey)        - approved and queued, hasn't started yet
//   Live (green)            - currently running
//   Paused (grey)           - active but paused by user or system
//   Completed (grey)        - finished, no more activity
// We render this chip in the header so the user knows the campaign's state
// at a glance, the moment they land on the detail page.
function resolveCampaignStatusChip(campaign) {
  const status = campaign && campaign.status;
  if (status === 'awaiting_approval') {
    return { label: 'Pending review', bg: t.warningSoft, color: t.warning, dot: '#B8721B' };
  }
  if (status === 'queued') {
    return { label: 'Scheduled', bg: t.surfaceMuted, color: t.textSecondary, dot: t.textTertiary };
  }
  if (status === 'active' || status === 'live') {
    return { label: 'Live', bg: t.successSoft, color: t.success, dot: t.success };
  }
  if (status === 'paused') {
    return { label: 'Paused', bg: t.surfaceMuted, color: t.textSecondary, dot: t.textTertiary };
  }
  if (status === 'ended' || status === 'completed') {
    return { label: 'Completed', bg: t.surfaceMuted, color: t.textSecondary, dot: t.textTertiary };
  }
  return null;
}

// Compact pill rendered in the CampaignHeader title row. Status-specific colors
// matching resolveCampaignStatusChip. Includes a small leading dot so the
// pill reads quickly even at peripheral glance.
function CampaignStatusChip({ campaign }) {
  const config = resolveCampaignStatusChip(campaign);
  if (!config) return null;
  return (
    <div style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: '6px',
      padding: '4px 10px 4px 8px',
      borderRadius: '999px',
      background: config.bg,
      color: config.color,
      fontSize: '12px',
      fontWeight: 500,
      lineHeight: 1.2,
      fontFamily: fontStack,
      whiteSpace: 'nowrap'
    }}>
      <span style={{
        width: '6px',
        height: '6px',
        borderRadius: '50%',
        background: config.dot,
        flexShrink: 0
      }} />
      {config.label}
    </div>
  );
}

function CampaignHeader({ campaign, isSmall, isBuildMode, onRebuild, aiWorking }) {
  const fundingLabel = campaign.funding === 'self' ? 'Self-funded'
    : campaign.funding === 'oem' ? 'OEM co-op'
    : campaign.funding === 'mixed' ? 'Mixed funding'
    : null;
  const lifecycleLabel = campaign.lifecycle
    ? campaign.lifecycle.charAt(0).toUpperCase() + campaign.lifecycle.slice(1)
    : null;
  
  return (
    <div style={{ marginBottom: '28px' }}>
      {/* Title row */}
      <div style={{
        display: 'flex',
        alignItems: 'flex-start',
        justifyContent: 'space-between',
        gap: '24px',
        flexWrap: 'wrap',
        marginBottom: '20px'
      }}>
        <div style={{ flex: 1, minWidth: '240px' }}>
          {/* Title + status chip on the same line. Chip sits at h1 baseline
              so it reads as part of the title, not floating chrome. */}
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            flexWrap: 'wrap'
          }}>
            <h1 style={{
              fontSize: isSmall ? '20px' : '24px', fontWeight: 600, margin: 0,
              color: t.textPrimary, letterSpacing: '-0.015em', lineHeight: 1.2
            }}>
              {campaign.name}
            </h1>
            <CampaignStatusChip campaign={campaign} />
          </div>
          <div style={{ fontSize: '13px', color: t.textSecondary, marginTop: '6px', lineHeight: 1.5 }}>
            {campaign.objective}
            {fundingLabel ? ' \u00b7 ' + fundingLabel : ''}
            {lifecycleLabel ? ' \u00b7 ' + lifecycleLabel : ''}
            {campaign.type === 'multi_phase' ? ' \u00b7 Multi-phase' : ''}
          </div>
        </div>
        
        {/* Right cluster: overflow menu */}
        <div style={{ display: 'flex', gap: '6px', alignItems: 'center', flexShrink: 0 }}>
          <button style={{
            padding: '7px 8px', background: 'transparent', color: t.textSecondary,
            border: 'none', borderRadius: '8px', cursor: 'pointer',
            display: 'flex', alignItems: 'center'
          }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <MoreHorizontal size={16} strokeWidth={1.75} />
          </button>
        </div>
      </div>
      
      {/* Status block: hidden during cold-start since the animation renders its own. */}
      {aiWorking !== 'coldStart' && <CampaignStatusBlock campaign={campaign} />}
    </div>
  );
}

// Consolidated status block - metrics on top, pacing bar below, single visual group
function CampaignStatusBlock({ campaign }) {
  const metrics = computeHeaderMetrics(campaign);
  
  const today = new Date('2026-05-08T00:00:00');
  const start = campaign.startDate ? new Date(campaign.startDate + 'T00:00:00') : null;
  const end = campaign.endDate ? new Date(campaign.endDate + 'T00:00:00') : null;
  let progressPct = 0;
  let timeLabel = '';
  if (campaign.status === 'active' || campaign.status === 'paused') {
    if (start && end) {
      progressPct = Math.max(0, Math.min(100, ((today - start) / (end - start)) * 100));
      timeLabel = formatRangeLong(campaign.startDate, campaign.endDate);
    }
  } else if (campaign.status === 'queued' && start) {
    timeLabel = 'Launches ' + start.toLocaleString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  } else if (campaign.status === 'ended' && start && end) {
    progressPct = 100;
    timeLabel = formatRangeLong(campaign.startDate, campaign.endDate);
  } else if (start && end) {
    timeLabel = formatRangeLong(campaign.startDate, campaign.endDate);
  }
  
  if (metrics.length === 0 && !timeLabel) return null;
  
  return (
    <div style={{
      padding: '16px 20px',
      background: t.surface,
      borderRadius: '12px'
    }}>
      {/* Metric strip */}
      {metrics.length > 0 && (
        <div style={{
          display: 'flex',
          gap: '28px',
          flexWrap: 'wrap',
          marginBottom: timeLabel ? '16px' : 0
        }}>
          {metrics.map((m, i) => (
            <div key={i}>
              <div style={{
                fontSize: '16px', fontWeight: 600, color: t.textPrimary,
                fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.005em', lineHeight: 1.2
              }}>
                {m.value}
              </div>
              <div style={{ fontSize: '11px', color: t.textTertiary, marginTop: '2px', fontWeight: 500 }}>
                {m.label}
              </div>
            </div>
          ))}
        </div>
      )}
      
      {/* Pacing bar */}
      {timeLabel && (
        <div>
          <div style={{
            height: '3px', background: t.surfaceMuted, borderRadius: '2px',
            overflow: 'hidden', marginBottom: '8px'
          }}>
            <div style={{
              height: '100%', width: progressPct + '%',
              background: campaign.status === 'ended' ? t.textTertiary : t.accent,
              borderRadius: '2px'
            }} />
          </div>
          <div style={{ fontSize: '12px', color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
            {timeLabel}
          </div>
        </div>
      )}
    </div>
  );
}

// Compute the right metrics for the campaign's current state
// Building (awaiting_approval): Goal + Projected gross + Projected ROAS
// Queued: Goal + Projected gross + Until launch
// Active/paused: Spent + Attributed + ROAS + Pacing (PLUS Deals, % to goal, etc as performance)
// Ended: Final gross + Final ROAS + Deals + % to goal
function computeHeaderMetrics(campaign) {
  const metrics = [];
  const today = new Date('2026-05-08T00:00:00');
  const dayMs = 24 * 60 * 60 * 1000;
  
  if (campaign.status === 'awaiting_approval') {
    if (campaign.goal?.target !== undefined) {
      const unit = goalUnitLabel(campaign.goal.kpi);
      metrics.push({ value: campaign.goal.target + ' ' + unit, label: 'Goal' });
    }
    if (campaign.projected?.gross) {
      metrics.push({ value: '$' + Math.round(campaign.projected.gross / 1000) + 'K', label: 'Projected gross' });
    }
    if (campaign.projected?.roas) {
      metrics.push({ value: campaign.projected.roas.toFixed(1) + 'x', label: 'Projected ROAS' });
    }
  } else if (campaign.status === 'queued') {
    if (campaign.goal?.target !== undefined) {
      const unit = goalUnitLabel(campaign.goal.kpi);
      metrics.push({ value: campaign.goal.target + ' ' + unit, label: 'Goal' });
    }
    if (campaign.projected?.gross) {
      metrics.push({ value: '$' + Math.round(campaign.projected.gross / 1000) + 'K', label: 'Projected gross' });
    }
    if (campaign.startDate) {
      const start = new Date(campaign.startDate + 'T00:00:00');
      const daysUntil = Math.ceil((start - today) / dayMs);
      metrics.push({ value: daysUntil > 0 ? daysUntil + ' days' : 'Today', label: 'Until launch' });
    }
  } else if (campaign.status === 'active' || campaign.status === 'paused') {
    // Full performance picture in the header now
    if (campaign.actual?.gross) {
      metrics.push({ value: '$' + Math.round(campaign.actual.gross / 1000) + 'K', label: 'Attributed gross' });
    }
    if (campaign.attribution?.dealsAttributed > 0) {
      metrics.push({ value: campaign.attribution.dealsAttributed.toLocaleString(), label: 'Deals' });
    }
    if (campaign.actual?.roas) {
      metrics.push({ value: campaign.actual.roas.toFixed(1) + 'x', label: 'ROAS' });
    }
    if (campaign.actual?.pace !== undefined) {
      const sign = campaign.actual.pace > 0 ? '+' : '';
      metrics.push({ value: sign + campaign.actual.pace + '%', label: 'Pacing' });
    }
    if (campaign.goal?.target && campaign.goal?.current !== undefined) {
      const pct = Math.round((campaign.goal.current / campaign.goal.target) * 100);
      metrics.push({ value: pct + '%', label: 'To goal' });
    }
  } else if (campaign.status === 'ended') {
    if (campaign.actual?.gross) {
      metrics.push({ value: '$' + Math.round(campaign.actual.gross / 1000) + 'K', label: 'Final gross' });
    }
    if (campaign.attribution?.dealsAttributed > 0) {
      metrics.push({ value: campaign.attribution.dealsAttributed.toLocaleString(), label: 'Deals' });
    }
    if (campaign.actual?.roas) {
      metrics.push({ value: campaign.actual.roas.toFixed(1) + 'x', label: 'Final ROAS' });
    }
    if (campaign.goal?.target && campaign.goal?.current !== undefined) {
      const pct = Math.round((campaign.goal.current / campaign.goal.target) * 100);
      metrics.push({ value: pct + '%', label: 'To goal' });
    }
  }
  return metrics;
}

function goalUnitLabel(kpi) {
  const k = (kpi || '').toLowerCase();
  if (k.includes('lead')) return 'leads';
  if (k.includes('unit')) return 'units';
  if (k.includes('reactivated')) return 'leads';
  return 'units';
}

// ============= BUILD MODE =============

function CampaignBuildBody({ campaign, stage, advanceStage, revertStage, onDiscuss, onEdit, canvasSavedTarget, registerRef, pulsedTarget, aiWorking, onAiComplete }) {
  // The campaign builds incrementally through stages, but the visible structure
  // is just an ingredient list that grows. Plan stage shows plan ingredients.
  // Creative stage adds a Creative ingredient row (containing the artifacts).
  // After approving creative, the campaign goes straight to approved (queued for
  // launch).
  //
  // AI animations occupy three slots:
  //   - coldStart: replaces the entire ingredient list (page renders empty
  //     content area with just the animation visible)
  //   - creative: appears below the ingredient list, where the Creative row
  //     will land once stage advances
  //   - launch: appears below the ingredient list (with Creative row visible),
  //     where the PublishedConfirmation will land
  //
  // While any animation runs, the ApprovalCTA is hidden so the user can't
  // double-click and confuse the state.
  const isAnimating = aiWorking !== null;
  // During the creative animation, we want the Creative row to appear in the
  // ingredient list (with its skeleton/animation tiles inside), not above or below it.
  // So we render the list with stage='creative' even though the official stage
  // is still 'plan', and pass creativeAnimating so the Creative row uses the
  // animation component instead of the final artifacts.
  const listStage = aiWorking === 'creative' ? 'creative' : stage;
  
  return (
    <div>
      {/* Cold start replaces the ingredient list entirely with a skeleton-style
          assembly animation. */}
      {aiWorking === 'coldStart' ? (
        <ColdStartAnimation campaign={campaign} onComplete={onAiComplete} />
      ) : (
        <IngredientList
          campaign={campaign}
          onDiscuss={onDiscuss}
          onEdit={onEdit}
          canvasSavedTarget={canvasSavedTarget}
          registerRef={registerRef}
          pulsedTarget={pulsedTarget}
          stage={listStage}
          creativeAnimating={aiWorking === 'creative'}
          onCreativeAnimComplete={onAiComplete}
        />
      )}
      
      {/* Launch animation lands where the confirmation will appear */}
      {aiWorking === 'launch' && (
        <LaunchAnimation campaign={campaign} onComplete={onAiComplete} />
      )}
      
      {/* Confirmation - only when fully approved and not animating */}
      {stage === 'approved' && !isAnimating && <PublishedConfirmation campaign={campaign} />}
      
      {/* Approval CTA - hidden during animations and when fully approved */}
      {stage !== 'approved' && !isAnimating && (
        <ApprovalCTA
          stage={stage}
          onApprove={advanceStage}
          onDiscuss={() => onDiscuss({
            label: campaign.name,
            prefilledQuestion: stage === 'plan' ? 'I have some thoughts on the plan.'
              : 'I have some thoughts on the creatives.'
          })}
          campaign={campaign}
        />
      )}
    </div>
  );
}

// ----- Prose summary with inline icons -----
// Iconed segments with a `target` field are clickable and scroll the corresponding
// ingredient row into view (with a brief pulse highlight to draw the eye).
function CampaignSummaryProse({ campaign, scrollToTarget }) {
  const structured = campaign.summaryStructured;
  
  if (!structured || !Array.isArray(structured)) {
    return campaign.summary ? (
      <p style={{
        fontSize: '16px', color: t.textPrimary, lineHeight: 1.7,
        margin: '0 0 24px', fontWeight: 400, maxWidth: '780px'
      }}>
        {campaign.summary}
      </p>
    ) : null;
  }
  
  return (
    <p style={{
      fontSize: '16px', lineHeight: 1.75,
      margin: '0 0 24px', maxWidth: '780px'
    }}>
      {structured.map((seg, i) => {
        if (seg.icon) {
          const Icon = resolveIcon(seg.icon);
          const isClickable = !!seg.target && !!scrollToTarget;
          
          return (
            <ProseIconSegment
              key={i}
              Icon={Icon}
              text={seg.text}
              target={seg.target}
              isClickable={isClickable}
              onClick={() => scrollToTarget && scrollToTarget(seg.target)}
            />
          );
        }
        return (
          <span key={i} style={{ color: t.textSecondary }}>
            {seg.text}
          </span>
        );
      })}
    </p>
  );
}

// One iconed segment in the prose. Renders as a non-wrapping inline unit so the icon
// and text stay glued. Clickable when target exists; subtle hover affordance.
function ProseIconSegment({ Icon, text, isClickable, onClick }) {
  const [hover, setHover] = useState(false);
  
  return (
    <span
      onClick={isClickable ? onClick : undefined}
      onMouseEnter={() => isClickable && setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        display: 'inline',
        whiteSpace: 'nowrap',
        cursor: isClickable ? 'pointer' : 'default'
      }}
    >
      <span style={{
        display: 'inline-flex', alignItems: 'center',
        verticalAlign: '-3px', marginRight: '5px',
        color: t.textPrimary
      }}>
        <Icon size={15} strokeWidth={2} />
      </span>
      <span style={{
        fontWeight: 600,
        color: t.textPrimary,
        borderBottom: hover ? '1px solid ' + t.textPrimary : '1px solid transparent',
        paddingBottom: '1px',
        transition: 'border-color 0.12s'
      }}>
        {text}
      </span>
    </span>
  );
}

// ----- Ingredient list -----
// Compliance + Funding are real ingredient rows (last in the list).
// Creative is also an ingredient row, but it only appears once AI has worked on it:
//   - Build mode: when stage has reached 'creative' (after plan approval)
//   - Monitor mode: always (campaign is past build, creatives exist)
// The stage prop is undefined in monitor mode and the caller doesn't pass it; we
// fall back to "show creative" when the campaign isn't awaiting approval.
function IngredientList({ campaign, onDiscuss, onEdit, canvasSavedTarget, registerRef, pulsedTarget, stage, creativeAnimating, onCreativeAnimComplete }) {
  const rows = [];
  
  // Decide if Creative row should appear
  const isBuildMode = campaign.status === 'awaiting_approval';
  const stageOrder = ['plan', 'creative', 'approved'];
  const showCreative = isBuildMode
    ? (stage && stageOrder.indexOf(stage) >= stageOrder.indexOf('creative'))
    : true;
  
  // Objective
  if (campaign.goal) {
    rows.push({
      icon: 'Target',
      value: campaign.goal.headline,
      label: 'Objective'
    });
  }
  
  // Audience
  // Comes before Offer in the read order: audience is "who we're trying to reach,"
  // a property of the database (Camry intenders exist independent of the campaign).
  // The offer is a marketing decision tailored to that audience: cause then effect.
  if (campaign.audience) {
    const sizeStr = campaign.audience.size?.toLocaleString();
    const suppressed = campaign.audience.suppressed > 0
      ? ' \u00b7 ' + campaign.audience.suppressed + ' suppressed'
      : '';
    rows.push({
      icon: 'Users',
      value: sizeStr + ' contacts',
      meta: campaign.audience.name + suppressed,
      label: 'Audience'
    });
  }
  
  // Offer
  if (campaign.offer) {
    rows.push({
      icon: 'Tag',
      value: campaign.offer.headline,
      meta: campaign.offer.secondary || null,
      label: 'Offer'
    });
  }
  
  // Inventory (conditional). Shown only when the campaign is actually
  // tied to specific vehicle inventory - i.e. an acquisition campaign
  // promoting on-lot units. Service campaigns sell appointment slots
  // (no vehicle inventory), and reactivation campaigns are
  // relationship-led (no specific units in play), so neither shows
  // this row. The seed sets inventory: null for those; we also guard
  // on `available` being a real number as a belt-and-suspenders check.
  if (
    campaign.inventory
    && campaign.inventory.models
    && campaign.inventory.models.length > 0
    && campaign.inventory.available != null
  ) {
    const inv = campaign.inventory;
    const metaValue = inv.available + ' in stock';
    rows.push({
      icon: 'Car',
      value: inv.models.join(', '),
      meta: metaValue,
      label: 'Inventory'
    });
  }
  
  // Schedule
  if (campaign.startDate && campaign.endDate) {
    rows.push({
      icon: 'Calendar',
      value: formatRangeLong(campaign.startDate, campaign.endDate),
      label: 'Schedule'
    });
  }
  
  // Budget and channels - funding type folds into the value line since money
  // and the rules attached to it (self-funded vs OEM co-op) are inseparable.
  if (campaign.budget) {
    const fundingSuffix = campaign.funding === 'self' ? ' \u00b7 Self-funded'
      : campaign.funding === 'oem' ? ' \u00b7 OEM co-op'
      : campaign.funding === 'mixed' ? ' \u00b7 Mixed funding'
      : '';
    
    // Co-op claim status (when applicable) becomes the meta line.
    const coopStatus = campaign.compliance?.coopStatus;
    const meta = coopStatus
      ? coopStatus.oem + ' co-op claim, ' + (coopStatus.claimStatus || 'pending')
      : null;
    
    rows.push({
      icon: 'Layers',
      value: '$' + Math.round(campaign.budget / 1000) + 'K' + fundingSuffix,
      meta: meta,
      label: 'Budget and channels',
      expand: 'channels'
    });
  }
  
  // Workflow - approach to running the campaign. Every campaign has a workflow,
  // whether it's a single blast or a multi-phase engagement ladder.
  {
    // Derive workflow shape from existing data.
    const hasPhases = campaign.type === 'multi_phase' && campaign.phases && campaign.phases.length > 1;
    let workflowValue, workflowMeta = null;
    if (hasPhases) {
      workflowValue = campaign.phases.length + '-step engagement ladder';
      const activeIdx = campaign.phases.findIndex(p => p.status === 'active');
      const completedCount = campaign.phases.filter(p => p.status === 'completed').length;
      if (activeIdx >= 0) {
        workflowMeta = 'Currently in step ' + (activeIdx + 1) + ' of ' + campaign.phases.length;
      } else if (completedCount === campaign.phases.length) {
        workflowMeta = 'All steps complete';
      }
    } else {
      const channelCount = (campaign.channelAllocation || []).length;
      workflowValue = channelCount > 1
        ? 'Multi-channel blast across ' + channelCount + ' channels'
        : 'Single send';
    }
    rows.push({
      icon: 'GitBranch',
      value: workflowValue,
      meta: workflowMeta,
      label: 'Workflow',
      expand: 'workflow'
    });
  }
  
  // Creative - same row pattern as everything else
  if (showCreative) {
    rows.push({
      icon: 'ImageIcon',
      value: 'Social post, email, text',
      label: 'Creative',
      expand: 'creative'
    });
  }
  
  // Compliance - combined TCPA + brand rules in one row.
  // This is the only row that represents verification output rather than a
  // campaign input. Sits last because audit/governance reads after the plan.
  if (campaign.compliance) {
    const c = campaign.compliance;
    const tcpa = c.tcpa;
    const brandPassed = c.brandRulesPassed;
    const issues = c.complianceIssues || [];
    
    // Headline takes the worst state
    let value, meta;
    if (brandPassed === false) {
      value = issues.length + (issues.length === 1 ? ' brand rule item needs review' : ' brand rule items need review');
      const tcpaBit = tcpa ? tcpa.compliant?.toLocaleString() + ' with valid TCPA consent' + (tcpa.suppressed > 0 ? ' \u00b7 ' + tcpa.suppressed + ' suppressed' : '') : null;
      const brandBit = issues.length > 0 ? issues.join(' \u00b7 ') : null;
      meta = [tcpaBit, brandBit].filter(Boolean).join(' \u00b7 ');
    } else {
      value = 'All checks passed';
      const parts = [];
      if (tcpa) {
        parts.push(tcpa.compliant?.toLocaleString() + ' with valid TCPA consent' + (tcpa.suppressed > 0 ? ' \u00b7 ' + tcpa.suppressed + ' suppressed' : ''));
      }
      parts.push('Brand rules reviewed');
      meta = parts.join(' \u00b7 ');
    }
    
    rows.push({
      icon: 'ShieldCheck',
      value: value,
      meta: meta,
      label: 'Compliance',
      // Compliance is a results surface, not an editable plan ingredient.
      // The user can ask AI about it (Discuss) but there's nothing to edit
      // here directly. Hide the Edit CTA on this row.
      viewOnly: true
    });
  }
  
  return (
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      {rows.map((row, i) => (
        <IngredientRow
          key={i}
          row={row}
          campaign={campaign}
          onDiscuss={onDiscuss}
          onEdit={onEdit}
          canvasSavedTarget={canvasSavedTarget}
          registerRef={registerRef}
          pulsedTarget={pulsedTarget}
          creativeAnimating={creativeAnimating}
          onCreativeAnimComplete={onCreativeAnimComplete}
        />
      ))}
    </div>
  );
}

