    { id: 'multi-touch', name: 'Multi-touch sequence', desc: 'Touchpoint, wait, next touchpoint. No branching.', icon: 'ArrowRight' },
    { id: 'ladder', name: 'Engagement ladder', desc: 'Each step gated by engagement. Engagers continue, non-engagers exit.', icon: 'GitBranch' },
    { id: 'tree', name: 'Decision tree', desc: 'Multiple branches. Different paths for openers, clickers, callers, non-engagers.', icon: 'Workflow' }
