// Detect which template best fits the current workflow shape
function deriveActiveTemplate(nodes) {
  if (!nodes || nodes.length === 0) return null;
  
  const hasBranch = (list) => list.some(n =>
    n.type === 'branch' ||
    (n.yes && hasBranch(n.yes)) ||
    (n.no && hasBranch(n.no))
  );
  const countBranches = (list) => list.reduce((acc, n) => {
    if (n.type === 'branch') {
      return acc + 1 + countBranches(n.yes || []) + countBranches(n.no || []);
    }
    return acc;
  }, 0);
  
  const hasWait = nodes.some(n => n.type === 'wait');
  const actionCount = nodes.filter(n => n.type === 'action').length;
  const branchCount = countBranches(nodes);
  
  if (branchCount >= 2) return 'tree';
  if (branchCount === 1) return 'ladder';
  if (hasWait) return 'multi-touch';
  if (actionCount > 1) return 'multi-channel';
  return 'single';
}

