// ===== Creative image placeholder =====
// Uses gradient backgrounds to represent generated images. variant strings:
// gradient-blue, gradient-red, gradient-warm, gradient-cool, gradient-mono.
function CreativeImage({ variant, aspectRatio, rounded, fullHeight }) {
  const gradient = gradientForVariant(variant);
  return (
    <div style={{
      width: '100%',
      aspectRatio: aspectRatio === 'auto' ? undefined : aspectRatio,
      height: fullHeight ? '100%' : undefined,
      background: gradient,
      borderRadius: rounded === false ? 0 : '6px',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      position: 'relative',
      minHeight: aspectRatio === 'auto' ? '120px' : undefined
    }}>
      <Car size={42} color="rgba(255,255,255,0.55)" strokeWidth={1.25} />
    </div>
  );
}

function gradientForVariant(variant) {
  const map = {
    'gradient-blue': 'linear-gradient(135deg, #4D9CF6 0%, #1B5FBA 100%)',
    'gradient-red': 'linear-gradient(135deg, #E96A6A 0%, #B83A3A 100%)',
    'gradient-warm': 'linear-gradient(135deg, #F4B638 0%, #E96A6A 100%)',
    'gradient-cool': 'linear-gradient(135deg, #6FB4D1 0%, #5CB87B 100%)',
    'gradient-mono': 'linear-gradient(135deg, #4A5568 0%, #2D3748 100%)',
    'gradient-sunset': 'linear-gradient(135deg, #F4B638 0%, #A86DD8 100%)',
    'gradient-dawn': 'linear-gradient(135deg, #FFE5B4 0%, #FF8C69 100%)',
    'gradient-forest': 'linear-gradient(135deg, #5CB87B 0%, #2D5F3F 100%)'
  };
  return map[variant] || map['gradient-blue'];
}

// ===== RefinePopover - inline AI refinement near the clicked element =====
// Visual shell matches DiscussPopover (the row-level "Discuss and refine") so
// the two AI-refine surfaces feel like one product. Behavior differs in one
// way: this popover NEVER applies changes directly. Submission always
// produces 3 variants; the user picks one, and that selection animates onto
// the creative card.
function RefinePopover({ element, currentValue, onApply, onClose }) {
  const popoverRef = useRef(null);
  const inputRef = useRef(null);
  const [coords, setCoords] = useState(null);
  const [instruction, setInstruction] = useState('');
  // Phases: 'idle' (initial chips + input), 'thinking' (AI generating),
  //         'picking' (3 variants visible). No 'applying' - clicking a variant
  //         calls onApply synchronously and the parent handles the animation.
  const [phase, setPhase] = useState('idle');
  const [variants, setVariants] = useState(null);
  const isImage = element.elementKey === 'image';
  
  const POPOVER_WIDTH = 380;
  const POPOVER_HEIGHT_ESTIMATE = 320;
  const VIEWPORT_PAD = 16;
  
  // Position relative to the anchor rect. Same flip/clamp logic as before,
  // sized for the new wider popover.
  useLayoutEffect(() => {
    if (!element.anchorRect) return;
    const computePosition = () => {
      const rect = element.anchorRect;
      const popoverH = (popoverRef.current && popoverRef.current.offsetHeight) || POPOVER_HEIGHT_ESTIMATE;
      const vh = window.innerHeight;
      const vw = window.innerWidth;
      const spaceBelow = vh - rect.bottom - VIEWPORT_PAD;
      const spaceAbove = rect.top - VIEWPORT_PAD;
      const flipUp = spaceBelow < popoverH && spaceAbove > spaceBelow;
      let top = flipUp ? rect.top - popoverH - 8 : rect.bottom + 8;
      if (top + popoverH > vh - VIEWPORT_PAD) top = Math.max(VIEWPORT_PAD, vh - popoverH - VIEWPORT_PAD);
      if (top < VIEWPORT_PAD) top = VIEWPORT_PAD;
      // Horizontally center on the element, then clamp to viewport.
      let left = rect.left + rect.width / 2 - POPOVER_WIDTH / 2;
      if (left + POPOVER_WIDTH > vw - VIEWPORT_PAD) left = vw - POPOVER_WIDTH - VIEWPORT_PAD;
      if (left < VIEWPORT_PAD) left = VIEWPORT_PAD;
      setCoords({ top, left });
    };
    computePosition();
    window.addEventListener('resize', computePosition);
    window.addEventListener('scroll', computePosition, true);
    return () => {
      window.removeEventListener('resize', computePosition);
      window.removeEventListener('scroll', computePosition, true);
    };
  }, [element]);
  
  // Click-outside close (with a tick of delay to ignore the opening click).
  useEffect(() => {
    const onDoc = (e) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target)) onClose();
    };
    const tid = setTimeout(() => {
      document.addEventListener('mousedown', onDoc);
    }, 0);
    return () => {
      clearTimeout(tid);
      document.removeEventListener('mousedown', onDoc);
    };
  }, [onClose]);
  
  // Esc to close.
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose]);
  
  // Focus the input when idle, so users can type immediately.
  useEffect(() => {
    if (phase === 'idle' && inputRef.current) {
      const tid = setTimeout(() => inputRef.current && inputRef.current.focus(), 80);
      return () => clearTimeout(tid);
    }
  }, [phase]);
  
  // Generate 3 variants from either a free-text instruction or a quick-pick.
  // For text, we apply the instruction in three different tonal directions so
  // the variants feel distinct. For image, we generate 3 visual moods.
  const generateVariants = (instructionHint) => {
    setPhase('thinking');
    setTimeout(() => {
      if (isImage) {
        // Image variants: 3 moods. Hints from instruction nudge the palette.
        const hint = (instructionHint || '').toLowerCase();
        const allGradients = ['gradient-blue', 'gradient-warm', 'gradient-mono', 'gradient-cool', 'gradient-sunset', 'gradient-dawn', 'gradient-forest'];
        // Crude hint-aware selection so quick-pick choices feel responsive
        let picked = ['gradient-blue', 'gradient-warm', 'gradient-mono'];
        if (hint.includes('sunset') || hint.includes('warm')) picked = ['gradient-warm', 'gradient-sunset', 'gradient-dawn'];
        else if (hint.includes('mono') || hint.includes('editorial')) picked = ['gradient-mono', 'gradient-cool', 'gradient-blue'];
        else if (hint.includes('cinematic') || hint.includes('dramatic')) picked = ['gradient-blue', 'gradient-mono', 'gradient-forest'];
        else if (hint.includes('lot') || hint.includes('exterior')) picked = ['gradient-warm', 'gradient-blue', 'gradient-cool'];
        setVariants([
          { id: 'v1', image: picked[0], label: gradientLabel(picked[0]) },
          { id: 'v2', image: picked[1], label: gradientLabel(picked[1]) },
          { id: 'v3', image: picked[2], label: gradientLabel(picked[2]) }
        ]);
      } else {
        // Text variants: 3 tonal interpretations of the instruction. If no
        // instruction was given (user clicked a chip with a tonal name),
        // produce three different "voices" of the same intent.
        const hint = instructionHint || '';
        const baseText = hint ? applyInstructionToText(currentValue, hint) : currentValue;
        setVariants([
          { id: 'v1', text: rewriteText(baseText, element.elementKey, 'punchy'), label: 'Punchy' },
          { id: 'v2', text: rewriteText(baseText, element.elementKey, 'warm'), label: 'Warm' },
          { id: 'v3', text: rewriteText(baseText, element.elementKey, 'urgent'), label: 'Urgent' }
        ]);
      }
      setPhase('picking');
    }, 900);
  };
  
  // Submit handlers - free text from input + quick-pick chips both go through
  // generateVariants. No more "apply directly" path here.
  const handleSubmitInput = () => {
    const text = instruction.trim();
    if (!text || phase === 'thinking') return;
    generateVariants(text);
  };
  const handlePickClick = (pickLabel) => {
    if (phase === 'thinking') return;
    setInstruction(pickLabel);
    generateVariants(pickLabel);
  };
  const handleVariantPick = (v) => {
    if (isImage) onApply({ image: v.image });
    else onApply({ [element.elementKey]: v.text });
  };
  const handleRegenerate = () => {
    setVariants(null);
    setPhase('idle');
  };
  
  if (!coords) return null;
  
  const elementLabel = labelForElementKey(element.elementKey);
  const HeadIcon = isImage ? ImageIcon : Type;
  
  return (
    <div
      ref={popoverRef}
      onClick={(e) => e.stopPropagation()}
      style={{
        position: 'fixed',
        top: coords.top + 'px',
        left: coords.left + 'px',
        width: POPOVER_WIDTH + 'px',
        maxWidth: 'calc(100vw - ' + (VIEWPORT_PAD * 2) + 'px)',
        background: t.bgPrimary,
        border: '1px solid ' + t.surfaceMuted,
        borderRadius: '12px',
        boxShadow: '0 12px 32px rgba(22,22,22,0.10), 0 2px 6px rgba(22,22,22,0.05)',
        animation: 'popoverIn 0.2s ease-out',
        zIndex: 350,
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column'
      }}
    >
      {/* Header - mirrors DiscussPopover */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: '10px',
        padding: '12px 14px',
        borderBottom: '1px solid ' + t.surfaceMuted,
        flexShrink: 0
      }}>
        <div style={{
          width: '26px', height: '26px',
          borderRadius: '7px',
          background: t.accentSoft,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          flexShrink: 0
        }}>
          <HeadIcon size={13} color={t.accent} strokeWidth={2} />
        </div>
        <div style={{
          flex: 1, minWidth: 0,
          fontSize: '13px', fontWeight: 600,
          color: t.textPrimary,
          letterSpacing: '-0.005em'
        }}>
          Refine {elementLabel.toLowerCase()}
        </div>
        <button
          onClick={onClose}
          aria-label="Close"
          style={{
            width: '22px', height: '22px',
            background: 'transparent',
            border: 'none', borderRadius: '6px',
            cursor: 'pointer', color: t.textTertiary,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            flexShrink: 0
          }}
          onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textSecondary; }}
          onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textTertiary; }}
        >
          <X size={14} strokeWidth={2} />
        </button>
      </div>
      
      {/* Body */}
      <div style={{ padding: '14px' }}>
        {phase === 'idle' && (
          <>
            {/* Context line - what AI knows about this element */}
            <div style={{
              fontSize: '13px', color: t.textSecondary,
              lineHeight: 1.5, marginBottom: '12px'
            }}>
              {isImage
                ? 'I can generate visual variations. Describe what you want, or pick a direction.'
                : 'I\'ll generate three options for you to pick from. Describe what to change, or pick a direction.'}
            </div>
            
            {/* Quick-pick chips - context-aware suggestions */}
            <div style={{
              display: 'flex', flexWrap: 'wrap', gap: '6px',
              marginBottom: '14px'
            }}>
              {quickPicksForElement(element.elementKey).map((pick, i) => (
                <button
                  key={i}
                  onClick={() => handlePickClick(pick)}
                  style={{
                    padding: '6px 12px',
                    background: t.bgPrimary,
                    color: t.textPrimary,
                    border: '1px solid ' + t.surfaceMuted,
                    borderRadius: '999px',
                    fontSize: '12px', fontWeight: 500,
                    cursor: 'pointer',
                    fontFamily: fontStack,
                    transition: 'border-color 0.12s, background 0.12s'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = t.accentSoft;
                    e.currentTarget.style.borderColor = t.accent;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = t.bgPrimary;
                    e.currentTarget.style.borderColor = t.surfaceMuted;
                  }}
                >
                  {pick}
                </button>
              ))}
            </div>
            
            {/* Free-text input - DiscussPopover-style */}
            <div style={{
              display: 'flex', alignItems: 'center', gap: '8px',
              padding: '6px 6px 6px 12px',
              border: '1px solid ' + t.surfaceMuted,
              borderRadius: '10px',
              background: t.bgPrimary,
              transition: 'border-color 0.12s'
            }}>
              <input
                ref={inputRef}
                type="text"
                value={instruction}
                onChange={(e) => setInstruction(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleSubmitInput(); }}
                placeholder={isImage ? 'Tell me what to change' : 'Tell me what to change'}
                style={{
                  flex: 1, background: 'transparent', border: 'none',
                  color: t.textPrimary, fontSize: '13px', outline: 'none',
                  fontFamily: fontStack, minWidth: 0,
                  padding: '6px 0'
                }}
              />
              <button
                onClick={handleSubmitInput}
                disabled={!instruction.trim()}
                style={{
                  width: '28px', height: '28px',
                  background: instruction.trim() ? t.accent : t.surface,
                  color: instruction.trim() ? t.textOnColor : t.textTertiary,
                  border: 'none', borderRadius: '7px',
                  cursor: instruction.trim() ? 'pointer' : 'default',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  flexShrink: 0,
                  transition: 'background 0.12s'
                }}
              >
                <ArrowRight size={13} strokeWidth={2.25} />
              </button>
            </div>
          </>
        )}
        
        {phase === 'thinking' && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: '10px',
            padding: '8px 0',
            animation: 'aiCommentaryIn 0.25s ease-out'
          }}>
            <img src={TEKION_AI_LOGO} alt="" style={{
              width: '18px', height: '18px', flexShrink: 0,
              animation: 'aiOrbit 2.4s linear infinite'
            }} />
            <span style={{ fontSize: '13px', color: t.textPrimary, lineHeight: 1.5 }}>
              Generating three options.
            </span>
          </div>
        )}
        
        {phase === 'picking' && variants && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ fontSize: '12px', color: t.textSecondary, marginBottom: '2px' }}>
              Pick one to apply.
            </div>
            {variants.map(v => (
              <button
                key={v.id}
                onClick={() => handleVariantPick(v)}
                style={{
                  padding: '0',
                  background: t.bgPrimary,
                  border: '1px solid ' + t.surfaceMuted,
                  borderRadius: '10px',
                  cursor: 'pointer',
                  fontFamily: fontStack,
                  textAlign: 'left',
                  overflow: 'hidden',
                  transition: 'border-color 0.15s, box-shadow 0.15s'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.borderColor = t.accent;
                  e.currentTarget.style.boxShadow = '0 2px 8px rgba(66,133,244,0.12)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.borderColor = t.surfaceMuted;
                  e.currentTarget.style.boxShadow = 'none';
                }}
              >
                {isImage ? (
                  <>
                    <div style={{
                      height: '90px',
                      background: gradientForVariant(v.image),
                      display: 'flex', alignItems: 'center', justifyContent: 'center'
                    }}>
                      <Car size={28} color="rgba(255,255,255,0.55)" strokeWidth={1.25} />
                    </div>
                    <div style={{
                      padding: '8px 12px',
                      fontSize: '12px', color: t.textSecondary
                    }}>
                      {v.label}
                    </div>
                  </>
                ) : (
                  <div style={{
                    padding: '10px 12px',
                    fontSize: '13px', color: t.textPrimary,
                    lineHeight: 1.5
                  }}>
                    {v.text}
                  </div>
                )}
              </button>
            ))}
            <button
              onClick={handleRegenerate}
              style={{
                padding: '6px',
                background: 'transparent',
                color: t.textSecondary,
                border: 'none',
                cursor: 'pointer',
                fontSize: '12px', fontWeight: 500,
                fontFamily: fontStack,
                marginTop: '2px',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '4px'
              }}
              onMouseEnter={(e) => { e.currentTarget.style.color = t.textPrimary; }}
              onMouseLeave={(e) => { e.currentTarget.style.color = t.textSecondary; }}
            >
              <RefreshCw size={11} strokeWidth={2} />
              Try again
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// Pretty label for a gradient key; used by the image variant picker.
function gradientLabel(key) {
  const map = {
    'gradient-blue': 'Cinematic blue',
    'gradient-warm': 'Warm sunset',
    'gradient-mono': 'Editorial mono',
    'gradient-cool': 'Cool dawn',
    'gradient-sunset': 'Golden hour',
    'gradient-dawn': 'Soft dawn',
    'gradient-forest': 'Forest deep'
  };
  return map[key] || 'Variation';
}

function labelForElementKey(key) {
  const map = {
    subject: 'subject line',
    preheader: 'preheader',
    headline: 'headline',
    body: 'body copy',
    image: 'image',
    cta: 'CTA button',
    primaryText: 'primary text',
    linkDescription: 'link description',
    headline1: 'headlines',
    description1: 'description',
    displayUrl: 'display URL',
    subhead: 'subhead',
    script: 'call script'
  };
  return map[key] || 'element';
}

// Quick-pick chips below the refine input - context-aware shortcuts that tap
// to apply immediately without typing. Picks are intentionally short (1-2
// words) and represent the most common refinement directions per element.
function quickPicksForElement(elementKey) {
  const map = {
    image: ['Cinematic', 'Warm sunset', 'Editorial mono', 'On the lot'],
    subject: ['Shorter', 'Add urgency', 'More personal'],
    preheader: ['Shorter', 'More casual', 'Add urgency'],
    headline: ['Shorter', 'Punchier', 'Add urgency'],
    body: ['Shorter', 'More casual', 'More formal', 'Add urgency'],
    cta: ['Shorter', 'More urgent', 'More inviting'],
    primaryText: ['Shorter', 'More casual', 'Add urgency'],
    linkDescription: ['Shorter', 'More descriptive'],
    headline1: ['Shorter', 'Punchier', 'Add urgency'],
    description1: ['Shorter', 'More casual', 'Add urgency'],
    displayUrl: ['Cleaner', 'More specific'],
    subhead: ['Shorter', 'Punchier'],
    script: ['Shorter', 'More casual', 'More formal']
  };
  return map[elementKey] || ['Shorter', 'More urgent'];
}

function rewriteText(s, elementKey, tone) {
  if (!s) return s;
  if (elementKey === 'cta') {
    if (tone === 'punchy') return 'Shop now';
    if (tone === 'warm') return 'See the lineup';
    if (tone === 'urgent') return 'Get the deal today';
  }
  if (elementKey === 'subject') {
    if (tone === 'punchy') return shortenText(s);
    if (tone === 'warm') return 'A note about ' + s.replace(/^Your\s+/i, '').toLowerCase();
    if (tone === 'urgent') return s + ' (ends Monday)';
  }
  if (tone === 'punchy') return shortenText(s);
  if (tone === 'warm') return 'We thought you might like this. ' + s;
  if (tone === 'urgent') return s + ' This weekend only.';
  return s;
}

function applyInstructionToText(s, instruction) {
  const ins = instruction.toLowerCase();
  if (ins.includes('shorter') || ins.includes('punchier') || ins.includes('cleaner')) return shortenText(s);
  if (ins.includes('longer') || ins.includes('expand') || ins.includes('more descriptive') || ins.includes('more specific')) {
    return s + ' Stop by this weekend and ask for the Memorial Day desk.';
  }
  if (ins.includes('urgent') || ins.includes('urgency')) return addUrgency(s);
  if (ins.includes('casual') || ins.includes('warmer') || ins.includes('friendlier') || ins.includes('inviting') || ins.includes('personal')) {
    return 'Hey there. ' + s;
  }
  if (ins.includes('formal')) return s.replace(/\bget\b/gi, 'receive').replace(/\bnow\b/gi, 'today');
  return s;
}

// buildCreativeVariants - per-element variant generator used by the
// AIWidget edit-creative flow. Returns three concrete proposals the user
// can pick from; each carries an opaque payload describing the patch to
// apply to the active creative.
//
// For image elements: three gradient swatches, hint-tuned by the chip
// label the user picked.
// For text elements: three tonal rewrites of the current value (punchy,
// warm, urgent), with the user's instruction hint folded in first.
function buildCreativeVariants({ elementKey, currentValue, instructionHint }) {
  const hint = (instructionHint || '').toLowerCase();
  const isImage = elementKey === 'image';
  
  if (isImage) {
    // Hint-aware gradient selection so the user's chip choice nudges the
    // palette. Mirrors the old RefinePopover image branch.
    let picked = ['gradient-blue', 'gradient-warm', 'gradient-mono'];
    if (hint.includes('sunset') || hint.includes('warm')) {
      picked = ['gradient-warm', 'gradient-sunset', 'gradient-dawn'];
    } else if (hint.includes('mono') || hint.includes('editorial')) {
      picked = ['gradient-mono', 'gradient-cool', 'gradient-blue'];
    } else if (hint.includes('cinematic') || hint.includes('dramatic')) {
      picked = ['gradient-blue', 'gradient-mono', 'gradient-forest'];
    } else if (hint.includes('lot') || hint.includes('exterior')) {
      picked = ['gradient-warm', 'gradient-blue', 'gradient-cool'];
    }
    return picked.map((key, i) => ({
      label: gradientLabel(key),
      image: key,
      payload: { image: key }
    }));
  }
  
  // Text variants. Each chip is an instruction direction. We produce three
  // takes on that direction so the user has a real choice rather than
  // three rewordings of the same thing. If no instruction was given,
  // fall back to three tonal interpretations (punchy / warm / urgent).
  if (!hint) {
    const tones = [
      { tone: 'punchy', label: 'Punchy' },
      { tone: 'warm', label: 'Warm' },
      { tone: 'urgent', label: 'Urgent' }
    ];
    return tones.map(({ tone, label }) => {
      const text = rewriteText(currentValue, elementKey, tone);
      return { label, text, payload: { [elementKey]: text } };
    });
  }
  
  // Instruction-driven. Each take applies the instruction slightly
  // differently so the variants feel like three thoughtful answers, not
  // three reshufflings.
  const v1Text = applyInstructionToText(currentValue, hint);
  const v2Text = rewriteText(currentValue, elementKey, 'punchy');
  const v3Text = rewriteText(applyInstructionToText(currentValue, hint), elementKey, 'urgent');
  return [
    { label: 'As described', text: v1Text, payload: { [elementKey]: v1Text } },
    { label: 'Tighter', text: v2Text, payload: { [elementKey]: v2Text } },
    { label: 'With urgency', text: v3Text, payload: { [elementKey]: v3Text } }
  ];
}

// ===== COMPLIANCE CANVAS - read-mostly with re-run =====
function ComplianceCanvas({ campaign, instructionSignal }) {
  const tcpa = campaign.compliance?.tcpa || {};
  const passed = campaign.compliance?.brandRulesPassed !== false;
  
  return (
    <div>
      <CanvasCard title="TCPA verification" subtitle="Telephone Consumer Protection Act consent for SMS and outbound calls.">
        <div style={{ display: 'flex', gap: '24px', flexWrap: 'wrap' }}>
          <div>
            <div style={{ fontSize: '11px', color: t.textTertiary, marginBottom: '2px' }}>Compliant contacts</div>
            <div style={{ fontSize: '20px', fontWeight: 600, color: t.success, fontVariantNumeric: 'tabular-nums' }}>
              {(tcpa.compliant || 0).toLocaleString()}
            </div>
          </div>
          <div>
            <div style={{ fontSize: '11px', color: t.textTertiary, marginBottom: '2px' }}>Suppressed</div>
            <div style={{ fontSize: '20px', fontWeight: 600, color: t.textPrimary, fontVariantNumeric: 'tabular-nums' }}>
              {(tcpa.suppressed || 0).toLocaleString()}
            </div>
          </div>
        </div>
      </CanvasCard>
      
      <CanvasCard title="Brand rules" subtitle="Automated checks against your brand guidelines.">
        <div style={{
          display: 'flex', alignItems: 'center', gap: '10px',
          padding: '12px 14px',
          background: passed ? t.successSoft : t.dangerSoft,
          borderRadius: '8px'
        }}>
          {passed ? (
            <>
              <CheckCircle2 size={18} color={t.success} strokeWidth={2} />
              <span style={{ fontSize: '13px', color: t.textPrimary, fontWeight: 500 }}>
                All checks passed
              </span>
            </>
          ) : (
            <>
              <AlertCircle size={18} color={t.danger} strokeWidth={2} />
              <span style={{ fontSize: '13px', color: t.textPrimary, fontWeight: 500 }}>
                {(campaign.compliance?.complianceIssues?.length || 0)} items need review
              </span>
            </>
          )}
        </div>
        
        <button style={{
          marginTop: '12px',
          padding: '7px 12px',
          background: t.bgPrimary, color: t.textSecondary,
          border: '1px solid ' + t.surfaceMuted, borderRadius: '7px',
          fontSize: '12px', fontWeight: 500,
          cursor: 'pointer', fontFamily: fontStack,
          display: 'inline-flex', alignItems: 'center', gap: '5px'
        }}>
          <RefreshCw size={11} strokeWidth={1.75} />
          Re-run checks
        </button>
      </CanvasCard>
    </div>
  );
}

// ===== PLACEHOLDER CANVAS - for sections without a specific editor =====
function PlaceholderCanvas({ rowLabel }) {
  return (
    <CanvasCard title={'Editing ' + rowLabel.toLowerCase()} subtitle="A dedicated editor for this section is coming in the next iteration. For now, use the AI input below to describe what you'd like to change.">
      <div style={{
        padding: '40px 20px',
        textAlign: 'center',
        color: t.textTertiary,
        fontSize: '13px'
      }}>
        Type your instruction below to refine this section.
      </div>
    </CanvasCard>
  );
}

// ----- One ingredient row -----
// Hover state has two parts: the background tint is immediate so quick scan-hovers
// still get visual feedback on which row they're on. The action buttons (Discuss /
// Edit on canvas) appear with a 300ms delay so casual mouse-over-during-scan doesn't
// surface them. The intent: buttons appear only when the user actually pauses on a row.
function IngredientRow({ row, campaign, onDiscuss, onEdit, canvasSavedTarget, registerRef, pulsedTarget, creativeAnimating, onCreativeAnimComplete }) {
  const Icon = resolveIcon(row.icon);
  // discussOpen tracks whether THIS row's chip is the one that opened the
  // global AIWidget. Used to keep the FloatingActionChip forceShow'd while
  // the widget is open over this row.
  const [discussOpen, setDiscussOpen] = useState(false);
  // Refining state has three sub-phases for the post-submit experience:
  //   null            - not refining
  //   'thinking'      - brief AI thinking commentary above the row
  //   'rebuilding'    - row value is skeletonized, then fades back in
  //   'just-updated'  - brief "Updated" affordance to highlight the change
  const [refining, setRefining] = useState(null);
  // Ref on the Discuss button. AIWidget uses this to anchor itself near
  // the row chip via collision-aware placement.
  const discussBtnRef = useRef(null);
  const targetId = row.label.toLowerCase();
  const rowKey = row.id || row.label.toLowerCase();
  const isPulsing = pulsedTarget === targetId;
  
  // Trigger the refining animation. Shared by both an AIWidget action
  // dispatch and a canvas save.
  const triggerRefining = () => {
    setRefining('thinking');
    setTimeout(() => setRefining('rebuilding'), 1200);
    setTimeout(() => setRefining('just-updated'), 2800);
    setTimeout(() => setRefining(null), 6500);
  };
  
  // Open the global AIWidget for this row, action-primary, with the
  // curated description + pill suggestions from the per-row config.
  // The widget anchors to the Discuss button, calls back to triggerRefining
  // on action commit, and closes the discussOpen state when dismissed.
  const toggleDiscuss = (e) => {
    if (e) e.stopPropagation();
    if (discussOpen) {
      // Already open for this row; clicking again closes via the widget's
      // own close path. The chip just reflects state.
      return;
    }
    const config = getDiscussConfig(rowKey, campaign, row.subId);
    setDiscussOpen(true);
    // View-only rows (compliance) are discussion-primary; they can't be
    // refined, only asked about. Editable rows are action-primary because
    // the goal of clicking on a row's Discuss IS to change it.
    //
    // campaignId + variationKey let AIWidget look up authored per-pill
    // variations from CAMPAIGN_VARIATIONS for the three test campaigns.
    onDiscuss({
      label: row.label,
      iconName: row.icon,
      primaryIntent: row.viewOnly ? 'discussion' : 'action',
      description: config && config.reasoning,
      suggestedChips: config && config.pills ? config.pills.map(p => p.label || p) : undefined,
      campaignId: campaign && campaign.id,
      variationKey: rowKey,
      anchorRef: discussBtnRef,
      onActionDispatch: triggerRefining,
      onWidgetClose: () => setDiscussOpen(false)
    });
  };
  const closeDiscuss = () => setDiscussOpen(false);
  
  // Open the canvas to hands-on edit this section. Bubbles up to the page.
  const handleEditClick = () => {
    if (onEdit) onEdit({
      rowId: rowKey,
      rowLabel: row.label,
      iconName: row.icon
    });
  };
  
  // Watch the page-level "canvas just saved" signal. When the saved target's
  // rowId matches this row, run the same refining animation.
  useEffect(() => {
    if (canvasSavedTarget && canvasSavedTarget.signal > 0 && canvasSavedTarget.rowId === rowKey) {
      triggerRefining();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canvasSavedTarget && canvasSavedTarget.signal]);
  
  return (
    <FloatingActionChip
      actions={[
        // View-only rows can only be discussed (compliance is verification
        // output - there's nothing to refine, just questions to ask).
        // Editable rows show the fuller "Discuss and refine" because the
        // conversation can produce changes.
        {
          label: row.viewOnly ? 'Discuss' : 'Discuss and refine',
          icon: 'ai',
          onClick: toggleDiscuss,
          ref: discussBtnRef,
          active: discussOpen
        },
        // Edit is suppressed for view-only rows (e.g., compliance results).
        // The user can still discuss; there's just nothing to edit directly.
        ...(row.viewOnly ? [] : [{ label: 'Edit', icon: 'edit', onClick: handleEditClick }])
      ]}
      forceShow={discussOpen}
      suppress={refining === 'thinking' || refining === 'rebuilding'}
    >
      {(hover) => (
        <div
          ref={el => registerRef && registerRef(targetId, el)}
          style={{
            padding: '14px 16px',
            margin: '0 -16px',
            borderRadius: '10px',
            background: discussOpen ? t.accentSoft : (hover ? t.surface : 'transparent'),
            display: 'flex', gap: '14px', alignItems: 'flex-start',
            transition: 'background 0.18s ease',
            position: 'relative',
            animation: isPulsing ? 'campaignPulse 1.4s ease-out' : 'none'
          }}
        >
          <div style={{
            width: '36px', height: '36px',
            borderRadius: '8px',
            background: discussOpen ? t.bgPrimary : t.surface,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            flexShrink: 0,
            transition: 'background 0.18s ease'
          }}>
            <Icon size={16} color={discussOpen ? t.accent : t.textSecondary} strokeWidth={1.75} />
          </div>
          
      <div style={{ flex: 1, minWidth: 0 }}>
        {/* Refining: brief commentary above the row content */}
        {refining === 'thinking' && (
          <div style={{
            fontSize: '12px', color: t.textSecondary, lineHeight: 1.5,
            fontStyle: 'italic', marginBottom: '8px',
            display: 'flex', alignItems: 'center', gap: '6px',
            animation: 'aiCommentaryIn 0.3s ease-out'
          }}>
            <img src={TEKION_AI_LOGO} alt="" style={{ width: '14px', height: '14px', animation: 'aiOrbit 2.4s linear infinite' }} />
            Considering your input on the {row.label.toLowerCase()}.
          </div>
        )}
        {refining === 'rebuilding' && (
          <div style={{
            fontSize: '12px', color: t.textSecondary, lineHeight: 1.5,
            fontStyle: 'italic', marginBottom: '8px',
            display: 'flex', alignItems: 'center', gap: '6px',
            animation: 'aiCommentaryIn 0.3s ease-out'
          }}>
            <img src={TEKION_AI_LOGO} alt="" style={{ width: '14px', height: '14px', animation: 'aiOrbit 2.4s linear infinite' }} />
            Recalculating.
          </div>
        )}
        
        {/* Label sits at the top, paired tightly with the icon as the row's identity. */}
        <div style={{
          fontSize: '11px', color: t.textTertiary, fontWeight: 500,
          marginBottom: '3px',
          display: 'flex', alignItems: 'center', gap: '8px'
        }}>
          {row.label}
          {refining === 'just-updated' && (
            <span style={{
              fontSize: '10px', fontWeight: 500,
              color: t.success,
              background: t.successSoft,
              padding: '2px 7px',
              borderRadius: '10px',
              animation: 'aiCommentaryIn 0.4s ease-out',
              display: 'inline-flex', alignItems: 'center', gap: '4px'
            }}>
              <Check size={9} strokeWidth={2.5} />
              Just updated
            </span>
          )}
        </div>
        
        {/* Value: skeleton while rebuilding, real value otherwise */}
        {refining === 'rebuilding' ? (
          <div style={{
            height: '15px',
            width: '60%',
            background: t.surfaceMuted,
            borderRadius: '3px',
            marginTop: '4px',
            position: 'relative',
            overflow: 'hidden'
          }}>
            <div style={{
              position: 'absolute',
              top: 0, left: 0, bottom: 0,
              width: '40%',
              background: 'linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.55) 50%, transparent 100%)',
              animation: 'iconShimmer 1.4s linear infinite'
            }} />
          </div>
        ) : (
          <div style={{
            fontSize: '15px', fontWeight: 500, color: t.textPrimary,
            lineHeight: 1.45,
            animation: refining === 'just-updated' ? 'aiCommentaryIn 0.3s ease-out' : 'none'
          }}>
            {row.value}
          </div>
        )}
        
        {/* Meta is additional context. */}
        {row.meta && refining !== 'rebuilding' && (
          <div style={{
            fontSize: '12px', color: t.textSecondary, lineHeight: 1.5, marginTop: '8px',
            animation: refining === 'just-updated' ? 'aiCommentaryIn 0.3s ease-out 0.1s backwards' : 'none'
          }}>
            {row.meta}
          </div>
        )}
        
        {row.expand === 'channels' && campaign.channelAllocation && refining !== 'rebuilding' && (
          <div style={{ marginTop: '14px' }}>
            <ChannelStackedBarInline channels={campaign.channelAllocation} />
          </div>
        )}
        
        {row.expand === 'workflow' && campaign.phases && refining !== 'rebuilding' && (
          <div style={{ marginTop: '14px' }}>
            <PhasesContent campaign={campaign} />
          </div>
        )}
        
        {row.expand === 'creative' && (
          <div style={{ marginTop: '14px' }}>
            {creativeAnimating
              ? <CreativeAnimation campaign={campaign} onComplete={onCreativeAnimComplete} />
              : <CreativeArtifacts campaign={campaign} onDiscuss={onDiscuss} onEdit={onEdit} canvasSavedTarget={canvasSavedTarget} />
            }
          </div>
        )}
      </div>
      
      {/* The Discuss-and-refine UI is now the global AIWidget, opened via
          toggleDiscuss above. Anchored to discussBtnRef and primed with
          the per-row curated description + pill suggestions. */}
        </div>
      )}
    </FloatingActionChip>
  );
}

// Channel stacked bar with dot legend
function ChannelStackedBarInline({ channels }) {
  const colors = ['#4D9CF6', '#F4B638', '#5CB87B', '#A86DD8', '#E96A6A'];
  const total = channels.reduce((s, c) => s + (c.pct || c.budget || 0), 0);
  
  return (
    <div>
      <div style={{
        height: '4px',
        background: t.surfaceMuted,
        borderRadius: '2px',
        overflow: 'hidden',
        display: 'flex',
        marginBottom: '12px'
      }}>
        {channels.map((ch, i) => {
          const share = (ch.pct || ch.budget || 0) / total * 100;
          return (
            <div key={i} style={{
              width: share + '%',
              background: colors[i % colors.length],
              height: '100%'
            }} />
          );
        })}
      </div>
      <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
        {channels.map((ch, i) => (
          <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <span style={{
              width: '10px', height: '10px',
              borderRadius: '50%',
              background: colors[i % colors.length],
              flexShrink: 0
            }} />
            <span style={{ fontSize: '12px', color: t.textSecondary, fontWeight: 500 }}>
              {ch.name}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ----- Phases expanded content (lives inside the Phases ingredient row) -----
// Phase strip on top, then a list of phase rows. Active phase default-expanded;
// click another to expand it (single-open accordion).
function PhasesContent({ campaign, onDiscuss }) {
  // Default open: the active phase, else first phase
  const activePhase = campaign.phases.find(p => p.status === 'active');
  const defaultOpenId = activePhase ? activePhase.id : campaign.phases[0].id;
  const [openId, setOpenId] = useState(defaultOpenId);
  
  // Hold a ref to each phase card so we can pin its top position across toggles.
  // Without this, clicking an accordion can cause the card to move under the
  // user's cursor (the page reflows above the click point when other cards open/close).
  const cardRefs = useRef({});
  const registerCardRef = (id, el) => {
    if (el) cardRefs.current[id] = el;
  };
  
  const handleToggle = (clickedId) => {
    // Snapshot the clicked card's viewport position BEFORE the state change.
    const clickedEl = cardRefs.current[clickedId];
    const topBefore = clickedEl ? clickedEl.getBoundingClientRect().top : 0;
    
    setOpenId(openId === clickedId ? null : clickedId);
    
    // After the DOM updates, measure again and compensate for any shift.
    // useLayoutEffect is cleaner but harder here since we need the ref AFTER
    // state has flushed. requestAnimationFrame waits one frame which is enough.
    requestAnimationFrame(() => {
      const elAfter = cardRefs.current[clickedId];
      if (!elAfter) return;
      const topAfter = elAfter.getBoundingClientRect().top;
      const delta = topAfter - topBefore;
      if (Math.abs(delta) < 1) return;
      adjustScrollBy(delta);
    });
  };
  
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      {campaign.phases.map((p, i) => (
        <PhaseAccordionRow
          key={p.id}
          phase={p}
          index={i}
          isOpen={openId === p.id}
          onToggle={() => handleToggle(p.id)}
          registerCardRef={el => registerCardRef(p.id, el)}
        />
      ))}
    </div>
  );
}

// Phase accordion row.
// Closed state shows compact metadata (dates, audience, channels) so users can scan.
// Open state expands the four facts plus result.
// Card uses t.bgPrimary + a subtle border so it stays visible regardless of parent hover state.
function PhaseAccordionRow({ phase, index, isOpen, onToggle, registerCardRef }) {
  const isActive = phase.status === 'active';
  const isCompleted = phase.status === 'completed';
  
  const statusLabel = isCompleted ? 'Completed'
    : isActive ? 'Active now'
    : 'Upcoming';
  const statusColor = isCompleted ? t.textTertiary
    : isActive ? t.accent
    : t.textTertiary;
  
  const pStart = new Date(phase.startDate + 'T00:00:00');
  const pEnd = new Date(phase.endDate + 'T00:00:00');
  const dateLabel = pStart.toLocaleString('en-US', { month: 'short', day: 'numeric' })
    + ' \u2013 '
    + pEnd.toLocaleString('en-US', { month: 'short', day: 'numeric' });
  
  // Compact metadata for the closed state - shown on the right of the header
  const audienceCompact = phase.audienceSize
    ? phase.audienceSize.toLocaleString() + ' contacts'
    : phase.audienceName;
  
  return (
    <div
      ref={registerCardRef}
      style={{
        background: t.bgPrimary,
        border: '1px solid ' + t.surfaceMuted,
        borderRadius: '10px',
        overflow: 'hidden'
      }}
    >
      {/* Header - clickable to toggle */}
      <button
        onClick={onToggle}
        style={{
          width: '100%',
          padding: '14px 18px',
          background: 'transparent',
          border: 'none',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          gap: '12px',
          cursor: 'pointer', fontFamily: fontStack,
          textAlign: 'left'
        }}
      >
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', flexWrap: 'wrap', minWidth: 0, flex: 1 }}>
          {/* Active indicator dot - subtle, replaces blue card background */}
          {isActive && (
            <span style={{
              width: '6px', height: '6px', borderRadius: '50%',
              background: t.accent, flexShrink: 0,
              alignSelf: 'center'
            }} />
          )}
          <span style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary }}>
            Phase {index + 1}: {phase.name}
          </span>
          <span style={{
            fontSize: '11px', fontWeight: 600, color: statusColor,
            letterSpacing: '0.01em'
          }}>
            {statusLabel}
          </span>
        </div>
        
        {/* Closed-state metadata - hidden when open to reduce clutter */}
        {!isOpen && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: '14px',
            fontSize: '12px', color: t.textTertiary,
            fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
            flexShrink: 0
          }}>
            <span>{audienceCompact}</span>
            <span style={{ color: t.textTertiary }}>{dateLabel}</span>
          </div>
        )}
        
        <ChevronDown
          size={16}
          color={t.textTertiary}
          strokeWidth={2}
          style={{
            transform: isOpen ? 'rotate(180deg)' : 'rotate(0)',
            transition: 'transform 0.15s',
            flexShrink: 0,
            marginLeft: '4px'
          }}
        />
      </button>
      
      {/* Body */}
      {isOpen && (
        <div style={{ padding: '4px 18px 18px' }}>
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
            gap: '16px',
            rowGap: '14px',
            paddingTop: '4px'
          }}>
            <PhaseFact icon="Calendar" label="Dates" value={dateLabel} />
            <PhaseFact icon="Users" label="Audience" value={phase.audienceName + (phase.audienceSize ? ' (' + phase.audienceSize.toLocaleString() + ')' : '')} />
            <PhaseFact icon="Tag" label="Offer" value={phase.offer} />
            <PhaseFact icon="ImageIcon" label="Creative direction" value={phase.creative} />
            <PhaseFact icon="Layers" label="Channels" value={phase.channels?.join(', ')} />
          </div>
          
          {phase.result && (
            <div style={{
              marginTop: '14px',
              paddingTop: '14px',
              borderTop: '1px solid ' + t.surfaceMuted,
              fontSize: '13px', color: t.textPrimary
            }}>
              <span style={{ color: t.textTertiary, fontSize: '11px', fontWeight: 500, marginRight: '8px' }}>
                {isCompleted ? 'Result' : 'Current'}
              </span>
              <span style={{ fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }}>
                {phase.result.engagers?.toLocaleString()} engagers
              </span>
              {phase.result.engagementRate && (
                <span style={{ color: t.textSecondary, marginLeft: '6px' }}>
                  ({phase.result.engagementRate}% engagement)
                </span>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function PhaseFact({ icon, label, value }) {
  const Icon = resolveIcon(icon);
  return (
    <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start', minWidth: 0 }}>
      <Icon size={14} color={t.textTertiary} strokeWidth={1.75} style={{ flexShrink: 0, marginTop: '3px' }} />
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: '10px', color: t.textTertiary, fontWeight: 500, marginBottom: '2px' }}>
          {label}
        </div>
        <div style={{ fontSize: '13px', color: t.textPrimary, fontWeight: 500, lineHeight: 1.4 }}>
          {value}
        </div>
      </div>
    </div>
  );
}

// ----- Creative artifacts (3-column grid) -----
function CreativeArtifacts({ campaign, onDiscuss, onEdit, canvasSavedTarget }) {
  return (
    <div>
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))',
        gap: '16px'
      }}>
        <CreativeColumn label="Social post" subId="social" campaign={campaign} onDiscuss={onDiscuss} onEdit={onEdit} canvasSavedTarget={canvasSavedTarget}>
          <MockSocialPost campaign={campaign} />
        </CreativeColumn>
        <CreativeColumn label="Email" subId="email" campaign={campaign} onDiscuss={onDiscuss} onEdit={onEdit} canvasSavedTarget={canvasSavedTarget}>
          <MockEmail campaign={campaign} />
        </CreativeColumn>
        <CreativeColumn label="Text" subId="sms" campaign={campaign} onDiscuss={onDiscuss} onEdit={onEdit} canvasSavedTarget={canvasSavedTarget}>
          <MockSMS campaign={campaign} />
        </CreativeColumn>
      </div>
    </div>
  );
}

function CreativeColumn({ label, subId, campaign, onDiscuss, onEdit, canvasSavedTarget, children }) {
  const [discussOpen, setDiscussOpen] = useState(false);
  // Refining states: null | 'thinking' | 'rebuilding' | 'just-updated'
  const [refining, setRefining] = useState(null);
  // Anchor for AIWidget.
  const discussBtnRef = useRef(null);
  
  // Trigger the refining animation. Shared between AIWidget action dispatch
  // and canvas save.
  const triggerRefining = () => {
    setRefining('thinking');
    setTimeout(() => setRefining('rebuilding'), 1100);
    setTimeout(() => setRefining('just-updated'), 3200);
    setTimeout(() => setRefining(null), 6700);
  };
  
  const toggleDiscuss = (e) => {
    if (e) e.stopPropagation();
    if (discussOpen) return;
    const iconName = subId === 'social' ? 'Share2'
      : subId === 'email' ? 'Mail'
      : subId === 'sms' ? 'Smartphone'
      : 'ImageIcon';
    const config = getDiscussConfig('creative', campaign, subId);
    setDiscussOpen(true);
    onDiscuss && onDiscuss({
      label: label,
      iconName,
      primaryIntent: 'action',
      description: config && config.reasoning,
      suggestedChips: config && config.pills ? config.pills.map(p => p.label || p) : undefined,
      campaignId: campaign && campaign.id,
      variationKey: 'creative:' + subId,
      anchorRef: discussBtnRef,
      onActionDispatch: triggerRefining,
      onWidgetClose: () => setDiscussOpen(false)
    });
  };
  const closeDiscuss = () => setDiscussOpen(false);
  
  // Open the canvas for hands-on editing of this creative variant.
  const handleEditClick = () => {
    if (onEdit) onEdit({
      rowId: 'creative',
      rowLabel: label,
      iconName: subId === 'social' ? 'Share2' : subId === 'email' ? 'Mail' : subId === 'sms' ? 'Smartphone' : 'ImageIcon',
      subId
    });
  };
  
  // Watch for canvas saves that target this creative variant.
  useEffect(() => {
    if (canvasSavedTarget && canvasSavedTarget.signal > 0 && canvasSavedTarget.rowId === 'creative') {
      // For now, any creative-canvas save triggers all three variants' refining
      // animations briefly (since the canvas can edit all three). A future
      // version could include subId in the signal to scope it.
      triggerRefining();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canvasSavedTarget && canvasSavedTarget.signal]);
  
  return (
    <div>
      {/* Header: label + status, sits outside the chip's anchor zone so the
          chip aligns to the top of the card itself (intuitive proximity). */}
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        marginBottom: '8px', minHeight: '20px'
      }}>
        <div style={{
          fontSize: '12px', fontWeight: 500, color: t.textSecondary,
          display: 'flex', alignItems: 'center', gap: '8px'
        }}>
          {label}
          {refining === 'just-updated' && (
            <span style={{
              fontSize: '10px', fontWeight: 500,
              color: t.success,
              background: t.successSoft,
              padding: '2px 7px',
              borderRadius: '10px',
              animation: 'aiCommentaryIn 0.4s ease-out',
              display: 'inline-flex', alignItems: 'center', gap: '4px'
            }}>
              <Check size={9} strokeWidth={2.5} />
              Just updated
            </span>
          )}
        </div>
      </div>
      
      <FloatingActionChip
        actions={[
          { label: 'Discuss and refine', icon: 'ai', onClick: toggleDiscuss, ref: discussBtnRef, active: discussOpen },
          { label: 'Edit', icon: 'edit', onClick: handleEditClick }
        ]}
        forceShow={discussOpen}
        suppress={refining === 'thinking' || refining === 'rebuilding'}
      >
        {() => (
          <div>
            {/* The card content. While refining, overlay a "regenerating" treatment.
                While discuss popover is open, a 2px accent ring marks this as the
                subject of the conversation. */}
            <div style={{
              borderRadius: '12px',
              overflow: 'hidden',
              background: t.surface,
              position: 'relative',
              boxShadow: discussOpen ? '0 0 0 2px ' + t.accent : 'none',
              transition: 'box-shadow 0.18s ease'
            }}>
              {children}
              {(refining === 'thinking' || refining === 'rebuilding') && (
                <div style={{
                  position: 'absolute',
                  inset: 0,
                  background: 'rgba(255,255,255,0.85)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  flexDirection: 'column', gap: '10px',
                  animation: 'aiCommentaryIn 0.25s ease-out',
                  zIndex: 5
                }}>
                  <img src={TEKION_AI_LOGO} alt="" style={{
                    width: '24px', height: '24px',
                    animation: 'aiOrbit 2.4s linear infinite'
                  }} />
                  <div style={{
                    fontSize: '12px', color: t.textPrimary, fontWeight: 500,
                    textAlign: 'center', padding: '0 20px',
                    fontStyle: 'italic'
                  }}>
                    {refining === 'thinking' ? 'Considering your input.' : 'Regenerating.'}
                  </div>
                </div>
              )}
            </div>
            
            {/* The Discuss-and-refine UI is now the global AIWidget, opened
                via toggleDiscuss above and anchored to discussBtnRef. */}
          </div>
        )}
      </FloatingActionChip>
    </div>
  );
}

