// Launch animation: brief 2-step end animation
// Launch animation: a skeleton version of the PublishedConfirmation banner
// appears immediately with commentary above describing what AI is finalizing.
// After ~2s, animation ends and the real banner takes its place. Matches the
// "skeleton fills in" pattern used elsewhere.
function LaunchAnimation({ campaign, onComplete }) {
  const [phase, setPhase] = useState(0);
  // 0 = locking schedule, 1 = queuing for launch, 2 = done
  
  useEffect(() => {
    const t1 = setTimeout(() => setPhase(1), 1000);
    const t2 = setTimeout(() => {
      setPhase(2);
      if (onComplete) onComplete();
    }, 2000);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);
  
  const launchDate = campaign.startDate
    ? new Date(campaign.startDate + 'T00:00:00').toLocaleString('en-US', { month: 'long', day: 'numeric' })
    : 'the start date';
  
  const commentary = phase === 0
    ? 'Locking the schedule for ' + launchDate + '.'
    : 'Queuing for launch.';
  
  return (
    <div style={{ marginTop: '32px' }}>
      {/* Commentary - same italic style used elsewhere */}
      <div style={{
        fontSize: '12px',
        color: t.textSecondary,
        lineHeight: 1.55,
        fontStyle: 'italic',
        marginBottom: '10px',
        display: 'flex',
        alignItems: 'center',
        gap: '8px',
        animation: 'aiCommentaryIn 0.3s ease-out'
      }}>
        <img src={TEKION_AI_LOGO} alt="" style={{
          width: '14px', height: '14px',
          animation: 'aiOrbit 2.4s linear infinite'
        }} />
        {commentary}
      </div>
      
      {/* Skeleton banner - matches PublishedConfirmation shape exactly */}
      <div style={{
        padding: '20px 24px',
        background: t.surface,
        borderRadius: '12px',
        display: 'flex', alignItems: 'center', gap: '14px',
        position: 'relative',
        overflow: 'hidden'
      }}>
        {/* Animated shimmer overlay */}
        <div style={{
          position: 'absolute',
          inset: 0,
          background: 'linear-gradient(120deg, transparent 30%, ' + t.success + '22 50%, transparent 70%)',
          animation: 'iconShimmer 1.4s linear infinite',
          pointerEvents: 'none'
        }} />
        
        {/* Icon placeholder - circle that will become the checkmark */}
        <div style={{
          width: '22px', height: '22px',
          borderRadius: '50%',
          background: t.surfaceMuted,
          flexShrink: 0,
          position: 'relative',
          zIndex: 1
        }} />
        
        {/* Text placeholders */}
        <div style={{ flex: 1, minWidth: 0, position: 'relative', zIndex: 1 }}>
          <div style={{
            height: '14px',
            width: '80px',
            background: t.surfaceMuted,
            borderRadius: '3px',
            marginBottom: '6px'
          }} />
          <div style={{
            height: '11px',
            width: '320px',
            maxWidth: '90%',
            background: t.surfaceMuted,
            borderRadius: '3px'
          }} />
        </div>
      </div>
    </div>
  );
}

