function AiAtWork({ preset, onComplete }) {
  const config = AI_AT_WORK_PRESETS[preset];
  const [activeIdx, setActiveIdx] = useState(0);
  const [completedCount, setCompletedCount] = useState(0);
  const timeoutsRef = useRef([]);
  
  useEffect(() => {
    if (!config) return;
    
    // Schedule each step transition. After step N's duration, it becomes completed
    // and step N+1 becomes active. After the last step, fire onComplete.
    let cumulative = 0;
    const timeouts = [];
    config.steps.forEach((step, i) => {
      cumulative += step.durationMs;
      const tid = setTimeout(() => {
        setCompletedCount(i + 1);
        if (i < config.steps.length - 1) {
          setActiveIdx(i + 1);
        } else {
          // Last step done. Small delay so the final checkmark is visible briefly,
          // then complete.
          const finalT = setTimeout(() => {
            if (onComplete) onComplete();
          }, 400);
          timeouts.push(finalT);
        }
      }, cumulative);
      timeouts.push(tid);
    });
    timeoutsRef.current = timeouts;
    
    return () => {
      timeouts.forEach(clearTimeout);
    };
  }, [preset]);
  
  if (!config) return null;
  
  return (
    <div style={{
      marginTop: '8px',
      paddingTop: '8px',
      paddingBottom: '24px',
      maxWidth: '520px'
    }}>
      {/* Header with Tekion AI mark + working copy */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
        marginBottom: '16px'
      }}>
        <img
          src={TEKION_AI_LOGO}
          alt=""
          style={{
            width: '20px',
            height: '20px',
            animation: 'aiOrbit 2.4s linear infinite'
          }}
        />
        <span style={{
          fontSize: '13px',
          fontWeight: 600,
          color: t.textPrimary,
          letterSpacing: '-0.005em'
        }}>
          {config.headerCopy}
        </span>
      </div>
      
      {/* Step cards stack */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        {config.steps.map((step, i) => {
          const isActive = i === activeIdx && i >= completedCount;
          const isCompleted = i < completedCount;
          const isVisible = isActive || isCompleted;
          
          if (!isVisible) return null;
          
          const Icon = resolveIcon(step.icon);
          return (
            <div
              key={i}
              style={{
                padding: '11px 14px',
                background: t.bgPrimary,
                border: '1px solid ' + t.surfaceMuted,
                borderRadius: '10px',
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                position: 'relative',
                overflow: 'hidden',
                animation: 'aiStepIn 0.25s ease-out'
              }}
            >
              <Icon size={15} color={isCompleted ? t.textTertiary : t.textSecondary} strokeWidth={1.75} style={{ flexShrink: 0 }} />
              <span style={{
                flex: 1,
                fontSize: '13px',
                color: isCompleted ? t.textTertiary : t.textPrimary,
                fontWeight: 500
              }}>
                {step.label}
              </span>
              {isCompleted && (
                <Check size={13} color={t.success} strokeWidth={2.5} style={{ flexShrink: 0 }} />
              )}
              
              {/* Progress bar for active step */}
              {isActive && (
                <div style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  height: '2px',
                  background: t.accent,
                  animation: 'aiProgress ' + step.durationMs + 'ms linear forwards'
                }} />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ----- Approval CTA -----
// Sticky bar at the bottom of the viewport. Flat visual treatment: white background,
// thin top border to delineate from page content. No shadow, no rounded corners.
// Consistent with the rest of the page which avoids drop shadows entirely.
//
// The bar uses position: sticky so it pins to the bottom of whichever scroll
// container holds it (works whether <main> or document is scrolling).
//
// With only two approval stages (plan and creative), a progress indicator would
// over-formalize what's effectively two clicks. The button label and helper text
// communicate the current stage and what happens next.
function ApprovalCTA({ stage, onApprove, onDiscuss, campaign }) {
  const launchDate = campaign.startDate
    ? new Date(campaign.startDate + 'T00:00:00').toLocaleString('en-US', { month: 'long', day: 'numeric' })
    : null;
  const today = new Date('2026-05-08T00:00:00');
  const start = campaign.startDate ? new Date(campaign.startDate + 'T00:00:00') : null;
  const launchIsToday = start && start.toDateString() === today.toDateString();
  const launchIsPast = start && start < today;
  
  // Helper text describes what happens after approval. Future-dated launches
  // read as "Scheduled for X" because that matches how a dealer thinks about
  // a campaign that's been approved but isn't running yet; past/today still
  // read as "Launching" because at that point the campaign IS launching, not
  // sitting on a future schedule.
  const launchPhrase = !launchDate ? 'Ready to schedule.'
    : launchIsPast ? 'Launching now.'
    : launchIsToday ? 'Launching today.'
    : 'Scheduled for ' + launchDate;
  
  // The creative-stage CTA approves the whole campaign for launch, not just
  // the creative output. The label reflects what the user is actually
  // committing to: a campaign that will run, spend, and contact customers.
  const copy = stage === 'plan'
    ? { label: 'Approve plan', sub: "I'll get started on creatives next." }
    : { label: 'Approve campaign', sub: launchPhrase };
  
  return (
    <div style={{
      position: 'sticky',
      bottom: 0,
      marginTop: '40px',
      padding: '14px 4px',
      background: t.bgPrimary,
      borderTop: '1px solid ' + t.surfaceMuted,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      gap: '16px',
      flexWrap: 'wrap',
      zIndex: 5
    }}>
      {/* Left: helper text */}
      <span style={{ fontSize: '12px', color: t.textTertiary, lineHeight: 1.5, minWidth: 0 }}>
        {copy.sub}
      </span>
      
      {/* Right: action buttons */}
      <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexShrink: 0 }}>
        <button
          onClick={onDiscuss}
          style={{
            padding: '9px 14px',
            background: 'transparent',
            color: t.textSecondary,
            border: '1px solid ' + t.surfaceMuted,
            borderRadius: '8px',
            fontSize: '13px', fontWeight: 500,
            cursor: 'pointer', fontFamily: fontStack
          }}
          onMouseEnter={(e) => { e.currentTarget.style.borderColor = t.textTertiary; e.currentTarget.style.color = t.textPrimary; }}
          onMouseLeave={(e) => { e.currentTarget.style.borderColor = t.surfaceMuted; e.currentTarget.style.color = t.textSecondary; }}
        >
          Discuss
        </button>
        <button
          onClick={onApprove}
          style={{
            padding: '9px 18px',
            background: t.accent,
            color: t.textOnColor,
            border: 'none',
            borderRadius: '8px',
            fontSize: '13px', fontWeight: 600,
            cursor: 'pointer', fontFamily: fontStack
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.accentHover}
          onMouseLeave={(e) => e.currentTarget.style.background = t.accent}
        >
          {copy.label}
        </button>
      </div>
    </div>
  );
}

