function formatRangeLong(start, end) {
  const s = new Date(start + 'T00:00:00');
  const e = new Date(end + 'T00:00:00');
  const sStr = s.toLocaleString('en-US', { month: 'long', day: 'numeric' });
  const eStr = e.toLocaleString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  return sStr + ' to ' + eStr;
}

