// =============================================================================
// JOURNEY DETAIL PAGE - whole-page detail view, mirrors the CampaignDetailPage
// chrome (back nav -> header -> tabs -> body), with journey-shaped content.
// =============================================================================
// Defaults to Performance for active journeys (the "what is this doing right
// now" answer) and to Overview for pending_review or inactive journeys (no
// useful perf data, the user is either reviewing AI's draft or revisiting
// the config of a journey that's been turned off).
// =============================================================================
function JourneyDetailPage({ journey, onBack, backLabel, onDiscuss, isSmall }) {
  // Default landing tab: Performance for active journeys (where the user
  // wants to see what's happening). Overview for pending_review journeys
  // (where the user is reviewing AI's draft before activating) and for
  // inactive journeys (perf data is stale, the config is what matters).
  const defaultTab = (journey.status === 'pending_review' || journey.status === 'inactive') ? 'plan' : 'performance';
  const [tab, setTab] = useState(defaultTab);
  
  // Floating "scroll to top" button - appears when the top back nav has
  // scrolled out of view. Same pattern as CampaignDetailPage so the
  // affordance feels consistent across the two detail surfaces.
  const backNavRef = useRef(null);
  const [showScrollToTop, setShowScrollToTop] = useState(false);
  
  useEffect(() => {
    const el = backNavRef.current;
    if (!el) return;
    const scrollableAncestors = [];
    let parent = el.parentElement;
    while (parent && parent !== document.body) {
      const style = window.getComputedStyle(parent);
      if (style.overflowY === 'auto' || style.overflowY === 'scroll') {
        scrollableAncestors.push(parent);
      }
      parent = parent.parentElement;
    }
    const checkPosition = () => {
      if (!backNavRef.current) return;
      const rect = backNavRef.current.getBoundingClientRect();
      setShowScrollToTop(rect.bottom < -8);
    };
    checkPosition();
    window.addEventListener('scroll', checkPosition, { passive: true });
    scrollableAncestors.forEach(node => node.addEventListener('scroll', checkPosition, { passive: true }));
    window.addEventListener('resize', checkPosition, { passive: true });
    return () => {
      window.removeEventListener('scroll', checkPosition);
      window.removeEventListener('resize', checkPosition);
      scrollableAncestors.forEach(node => node.removeEventListener('scroll', checkPosition));
    };
  }, []);
  
  const scrollToTop = () => {
    const main = document.querySelector('main');
    if (main && main.scrollTo) main.scrollTo({ top: 0, behavior: 'smooth' });
    const doc = document.scrollingElement || document.documentElement;
    if (doc && doc.scrollTo) doc.scrollTo({ top: 0, behavior: 'smooth' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  
  // Anchor scroll to top on mount + when navigating between journeys
  useLayoutEffect(() => {
    const main = document.querySelector('main');
    if (main) main.scrollTop = 0;
    const doc = document.scrollingElement || document.documentElement;
    if (doc) doc.scrollTop = 0;
    setTab(defaultTab);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [journey.id]);
  
  return (
    <div>
      {/* Reuse CampaignBackNav - it's a generic shell that takes a label. */}
      <CampaignBackNav onBack={onBack} navRef={backNavRef} label={backLabel || 'Back to journeys'} />
      
      <JourneyHeader journey={journey} isSmall={isSmall} />
      
      {/* Tab strip - mirrors the CampaignDetailPage sub-nav pattern but
          tabs are journey-shaped: Plan (config), Flow (visual sequence),
          Performance (always-on health). */}
      <div style={{
        display: 'flex',
        gap: '4px',
        borderBottom: '1px solid ' + t.surfaceMuted,
        marginBottom: '24px'
      }}>
        {[
          { id: 'plan', label: 'Overview' },
          { id: 'performance', label: 'Performance' }
        ].map(tabDef => (
          <button
            key={tabDef.id}
            onClick={() => setTab(tabDef.id)}
            style={{
              padding: '10px 14px',
              background: 'transparent',
              color: tab === tabDef.id ? t.textPrimary : t.textSecondary,
              border: 'none',
              borderBottom: '2px solid ' + (tab === tabDef.id ? t.accent : 'transparent'),
              borderRadius: 0,
              fontSize: '13px',
              fontWeight: tab === tabDef.id ? 600 : 500,
              cursor: 'pointer',
              fontFamily: fontStack,
              marginBottom: '-1px'
            }}
          >
            {tabDef.label}
          </button>
        ))}
      </div>
      
      {/* Body content per active tab. Flow lives inline inside the Plan
          tab (as the third ingredient, after Trigger and Audience) since
          the journey flow is the substance of the journey, not a separate
          surface. */}
      {tab === 'plan' && <JourneyPlanBody journey={journey} onDiscuss={onDiscuss} isSmall={isSmall} />}
      {tab === 'performance' && <JourneyPerformanceBody journey={journey} onDiscuss={onDiscuss} isSmall={isSmall} />}
      
      {/* Floating scroll-to-top button - matches the CampaignDetailPage version
          for visual continuity. */}
      {showScrollToTop && (
        <button
          onClick={scrollToTop}
          aria-label="Scroll to top"
          style={{
            position: 'fixed',
            bottom: isSmall ? '76px' : '24px',
            right: isSmall ? '16px' : '32px',
            width: '42px',
            height: '42px',
            borderRadius: '14px',
            background: t.bgPrimary,
            border: 'none',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: t.textPrimary,
            boxShadow: '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)',
            zIndex: 65,
            transition: 'transform 0.15s, box-shadow 0.15s',
            animation: 'fadeIn 0.18s ease'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = 'translateY(-2px)';
            e.currentTarget.style.boxShadow = '0 6px 20px rgba(22,22,22,0.08), 0 1px 3px rgba(22,22,22,0.04)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'translateY(0)';
            e.currentTarget.style.boxShadow = '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)';
          }}
        >
          <ChevronUp size={16} strokeWidth={2} />
        </button>
      )}
    </div>
  );
}

// ----- Journey detail header: title + status chip + subtitle + status block -----
function JourneyHeader({ journey, isSmall }) {
  const departmentLabel = journey.department
    ? journey.department.charAt(0).toUpperCase() + journey.department.slice(1)
    : null;
  const activeSinceLabel = journey.activeSince ? formatActiveSince(journey.activeSince) : null;
  const isPendingReview = journey.status === 'pending_review';
  
  return (
    <div style={{ marginBottom: '28px' }}>
      {/* Title row */}
      <div style={{
        display: 'flex',
        alignItems: 'flex-start',
        justifyContent: 'space-between',
        gap: '24px',
        flexWrap: 'wrap',
        marginBottom: '20px'
      }}>
        <div style={{ flex: 1, minWidth: '240px' }}>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            flexWrap: 'wrap'
          }}>
            <h1 style={{
              fontSize: isSmall ? '20px' : '24px', fontWeight: 600, margin: 0,
              color: t.textPrimary, letterSpacing: '-0.015em', lineHeight: 1.2
            }}>
              {journey.name}
            </h1>
            <JourneyStatusChip status={journey.status} />
          </div>
          <div style={{ fontSize: '13px', color: t.textSecondary, marginTop: '6px', lineHeight: 1.5 }}>
            {journey.description}
            {departmentLabel || activeSinceLabel ? (
              <div style={{ fontSize: '12px', color: t.textTertiary, marginTop: '4px' }}>
                {departmentLabel}
                {departmentLabel && activeSinceLabel ? ' \u00b7 ' : ''}
                {activeSinceLabel ? 'Active since ' + activeSinceLabel : ''}
              </div>
            ) : null}
          </div>
        </div>
        
        {/* Right cluster: Activate CTA for pending-review journeys,
            overflow menu otherwise. */}
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexShrink: 0 }}>
          {isPendingReview && (
            <button
              onClick={() => alert('Activate journey - coming next round')}
              style={{
                padding: '9px 16px',
                background: t.accent, color: t.textOnColor,
                border: 'none', borderRadius: '8px',
                fontSize: '13px', fontWeight: 600,
                cursor: 'pointer', fontFamily: fontStack,
                display: 'flex', alignItems: 'center', gap: '6px'
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = t.accentHover}
              onMouseLeave={(e) => e.currentTarget.style.background = t.accent}
            >
              Activate journey
            </button>
          )}
          <button style={{
            padding: '7px 8px', background: 'transparent', color: t.textSecondary,
            border: 'none', borderRadius: '8px', cursor: 'pointer',
            display: 'flex', alignItems: 'center'
          }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <MoreHorizontal size={16} strokeWidth={1.75} />
          </button>
        </div>
      </div>
      
      {/* Status block - In motion / Converted this month / Conversion rate.
          Hidden for pending-review journeys since they have no performance
          data yet. */}
      {!isPendingReview && <JourneyStatusBlock journey={journey} />}
    </div>
  );
}

// Status chip - three-state journey taxonomy. Active is green (running
// cleanly, no special treatment). Pending review is accent (drafted, waiting
// for the user). Inactive is grey (off, either manually or by the system).
function JourneyStatusChip({ status }) {
  let bg, fg, label, dot;
  if (status === 'active') {
    bg = t.successSoft; fg = t.success; label = 'Active'; dot = t.success;
  } else if (status === 'pending_review') {
    bg = t.accentSoft; fg = t.accent; label = 'Pending review'; dot = t.accent;
  } else if (status === 'inactive') {
    bg = t.surfaceMuted; fg = t.textSecondary; label = 'Inactive'; dot = t.textTertiary;
  } else {
    bg = t.surfaceMuted; fg = t.textSecondary; label = status; dot = t.textTertiary;
  }
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: '6px',
      padding: '3px 9px 3px 8px',
      background: bg, color: fg,
      borderRadius: '5px',
      fontSize: '11px', fontWeight: 600,
      whiteSpace: 'nowrap'
    }}>
      <span style={{
        width: '6px', height: '6px', borderRadius: '50%', background: dot
      }} />
      {label}
    </span>
  );
}

// Status block - the journey equivalent of CampaignStatusBlock. Shows the
// "what is this doing right now" metrics across the top of the detail page.
function JourneyStatusBlock({ journey }) {
  // KPI bar mirrors CampaignStatusBlock's layout exactly: value 16px above
  // an 11px label, 28px gap between metrics, surface-filled rounded card.
  // Sub-lines (trend, qualifier) are intentionally absent here - trend
  // belongs on the Performance tab where it has space to breathe; this
  // bar is for at-a-glance reading. Stages metric was removed because
  // it was a static config detail (4 touches won't change day-to-day),
  // not an operating signal worth header real estate.
  return (
    <div style={{
      padding: '16px 20px',
      background: t.surface,
      borderRadius: '12px'
    }}>
      <div style={{
        display: 'flex',
        gap: '28px',
        flexWrap: 'wrap'
      }}>
        <JourneyHeaderMetric
          label="In motion"
          value={journey.inMotion.toLocaleString()}
        />
        <JourneyHeaderMetric
          label="Converted this month"
          value={journey.convertedThisMonth.toLocaleString()}
        />
        {journey.conversionRate !== null && journey.conversionRate !== undefined && (
          <JourneyHeaderMetric
            label="Conversion rate"
            value={journey.conversionRate.toFixed(1) + '%'}
          />
        )}
      </div>
    </div>
  );
}

function JourneyHeaderMetric({ label, value }) {
  // Value-on-top, label-below. Matches the CampaignStatusBlock metric
  // shape: 16px / 600 / tabular-nums value with -0.005em letter-spacing,
  // 11px / 500 / tertiary label sitting 2px under it.
  return (
    <div>
      <div style={{
        fontSize: '16px', fontWeight: 600, color: t.textPrimary,
        fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
        letterSpacing: '-0.005em', lineHeight: 1.2
      }}>
        {value}
      </div>
      <div style={{
        fontSize: '11px', color: t.textTertiary,
        marginTop: '2px', fontWeight: 500
      }}>
        {label}
      </div>
    </div>
  );
}

// Format an ISO date as "Month YYYY" (e.g. "2025-08-12" -> "Aug 2025").
function formatActiveSince(iso) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00');
  if (isNaN(d.getTime())) return iso;
  return d.toLocaleString('en-US', { month: 'short', year: 'numeric' });
}

// =============================================================================
// PLAN TAB - 7 ingredient rows: Trigger, Audience, Touches, Channels,
// Suppression, Goal, Compliance. Read-only this round; clicking opens a
// placeholder. The shape mirrors Campaign's ingredient-row pattern visually
// but the content is journey-shaped (no Offer/Budget/Schedule).
// =============================================================================
function JourneyPlanBody({ journey, onDiscuss, isSmall }) {
  // The Plan tab reads top-to-bottom as a narrative: when does this fire
  // (Trigger), for whom (Audience, with suppression folded into its meta
  // line), what happens to them (Flow - the expanded visualization, with
  // per-stage channel mix shown on each stage card), what counts as
  // success (Goal), and what guardrails apply (Compliance).
  //
  // Channels was removed because the per-stage channel mix on each Flow
  // card already surfaces that information without redundancy. Suppression
  // was removed because journeys apply standard rules across the board
  // (DNC, active deal, recent contact) and the suppression count for the
  // current audience now lives in the Audience meta line, again matching
  // the Campaign detail pattern.
  const trigger = deriveTrigger(journey);
  const audience = deriveAudience(journey);
  const goal = deriveGoal(journey);
  
  const triggerRow = { id: 'trigger', label: 'Trigger', value: trigger.value, meta: trigger.meta, iconName: 'Zap' };
  const audienceRow = { id: 'audience', label: 'Audience', value: audience.value, meta: audience.meta, iconName: 'Users' };
  const goalRow = { id: 'goal', label: 'Goal', value: goal.value, meta: goal.meta, iconName: 'Target' };
  const complianceRow = { id: 'compliance', label: 'Compliance', value: 'TCPA opt-in required', meta: 'Brand-compliance check on every creative refresh', iconName: 'ShieldCheck' };
  
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '0' }}>
      <JourneyPlanRow row={triggerRow} journey={journey} onDiscuss={onDiscuss} />
      <JourneyPlanRow row={audienceRow} journey={journey} onDiscuss={onDiscuss} />
      <JourneyFlowInlineSection journey={journey} onDiscuss={onDiscuss} isSmall={isSmall} />
      <JourneyPlanRow row={goalRow} journey={journey} onDiscuss={onDiscuss} />
      <JourneyPlanRow row={complianceRow} journey={journey} onDiscuss={onDiscuss} />
    </div>
  );
}

// Single ingredient row on the Plan tab. Visual matches the Campaign
// IngredientRow: transparent by default, surface fill on hover, 36px icon
// container, 11px label, 15px value, optional meta subtext below the
// value. No card background - rows sit flat on the canvas with breathing
// room between them.
function JourneyPlanRow({ row, journey, onDiscuss }) {
  const IconMap = {
    Zap, Users, Target, ShieldCheck
  };
  const Icon = IconMap[row.iconName] || Target;
  const [hover, setHover] = useState(false);
  
  return (
    <div
      onClick={() => alert(row.label + ' editor - coming next round')}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        // Negative side margin extends the hover fill beyond the content
        // column so it reads as a row, not a tile - mirrors Campaign's
        // IngredientRow geometry.
        padding: '18px 16px',
        margin: '0 -16px',
        borderRadius: '10px',
        background: hover ? t.surface : 'transparent',
        cursor: 'pointer',
        transition: 'background 0.18s ease',
        display: 'flex',
        alignItems: 'flex-start',
        gap: '14px',
        position: 'relative'
      }}
    >
      <div style={{
        width: '36px', height: '36px',
        borderRadius: '8px',
        // Icon sits on the surface fill - flips to bgPrimary on hover so
        // the icon container remains distinct from the row background.
        background: hover ? t.bgPrimary : t.surface,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        flexShrink: 0,
        transition: 'background 0.18s ease'
      }}>
        <Icon size={16} strokeWidth={1.75} color={t.textSecondary} />
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontSize: '11px', color: t.textTertiary,
          fontWeight: 500, marginBottom: '3px'
        }}>
          {row.label}
        </div>
        <div style={{
          fontSize: '15px', color: t.textPrimary,
          lineHeight: 1.45, fontWeight: 500
        }}>
          {row.value}
        </div>
        {row.meta && (
          <div style={{
            fontSize: '12px', color: t.textSecondary,
            lineHeight: 1.5, marginTop: '8px'
          }}>
            {row.meta}
          </div>
        )}
      </div>
      <button
        onClick={(e) => {
          e.stopPropagation();
          onDiscuss && onDiscuss({
            label: row.label + ' for ' + journey.name,
            displayLabel: 'journey',
            prefilledQuestion: 'Walk me through the ' + row.label.toLowerCase() + ' for this journey.'
          });
        }}
        style={{
          padding: '6px 8px',
          background: 'transparent', color: t.textTertiary,
          border: 'none', borderRadius: '6px', cursor: 'pointer',
          display: 'flex', alignItems: 'center',
          flexShrink: 0,
          opacity: hover ? 1 : 0,
          transition: 'opacity 0.18s ease, background 0.12s, color 0.12s'
        }}
        onMouseEnter={(e) => { e.currentTarget.style.background = t.bgPrimary; e.currentTarget.style.color = t.accent; }}
        onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textTertiary; }}
        title="Discuss"
      >
        <MessageCircle size={14} strokeWidth={1.75} />
      </button>
    </div>
  );
}

// Helpers - derive ingredient values from journey fields. Each returns a
// { value, meta } shape so the Plan row can render a short headline value
// with optional one-line subtext below, matching the Campaign detail
// IngredientRow pattern. meta is null when the ingredient is naturally
// single-line and doesn't need elaboration.
function deriveTrigger(j) {
  const triggerMap = {
    j1: { value: 'Lease maturity in 90, 60, 30, or 7 days', meta: 'Per-customer trigger, perpetual' },
    j2: { value: '90+ days past service interval', meta: 'Per-customer trigger, perpetual' },
    j3: { value: '14 days after vehicle delivery', meta: 'Per-customer trigger, perpetual' },
    j4: { value: 'No activity for 18 months', meta: 'Per-customer trigger, perpetual' },
    j5: { value: 'EV inventory or service engagement in last 30 days', meta: 'Per-customer trigger, perpetual' },
    j6: { value: 'Customer birthday', meta: 'Per-customer trigger, perpetual' },
    j7: { value: 'New buyer takes delivery', meta: 'Per-customer trigger, perpetual' }
  };
  return triggerMap[j.id] || { value: 'Configured trigger condition', meta: null };
}

function deriveAudience(j) {
  // Audience meta folds the suppression count into the sub-line, matching
  // the Campaign audience pattern ("3,400 contacts" / "Cold leads, 60-180
  // days silent · 87 suppressed"). Suppression isn't a separate ingredient
  // since journeys apply the same standard rules everywhere - DNC list,
  // active deal in progress, contacted in last 14 days - and surfacing
  // those rules as their own row was redundant.
  const audienceMap = {
    j1: { value: 'All current lessees', meta: 'Not opted out, valid contact info \u00b7 32 suppressed (active deal)' },
    j2: { value: 'Service customers, 90+ days past due', meta: 'Roughly 1,830 eligible \u00b7 94 suppressed (active appointment)' },
    j3: { value: 'All new buyers, last 30 days', meta: 'Not opted out \u00b7 7 suppressed (already on satisfaction list)' },
    j4: { value: 'Dormant customers, 18+ months', meta: 'Equity-positive preferred \u00b7 28 suppressed (active deal, DNC)' },
    j5: { value: 'EV-engaged customers, last 30 days', meta: 'Engaged with EV content or visited an EV detail page' },
    j6: { value: 'All active customers', meta: 'With valid birthday on file \u00b7 14 suppressed (recent contact)' },
    j7: { value: 'All new buyers, post-delivery', meta: '~142 customers per month, suppression rules apply at activation' }
  };
  return audienceMap[j.id] || { value: 'Customers matching the trigger', meta: 'Standard suppression rules apply' };
}

function deriveGoal(j) {
  const goalMap = {
    j1: { value: 'Lease renewal or vehicle purchase', meta: 'Within 60 days of lease maturity' },
    j2: { value: 'Service appointment booked', meta: 'Within 30 days of trigger' },
    j3: { value: 'Review submitted or first paid service booked', meta: null },
    j4: { value: 'Showroom visit, test drive, or service appointment', meta: 'Within 90 days of trigger' },
    j5: { value: 'EV test drive scheduled', meta: null },
    j6: { value: 'Service appointment or sales hand-raiser', meta: null },
    j7: { value: 'First service appointment booked', meta: 'Within 90 days of delivery' }
  };
  return goalMap[j.id] || { value: 'Customer engagement leading to a dealership visit', meta: null };
}

// =============================================================================
// FLOW INLINE SECTION - lives inside the Plan tab as the third ingredient.
// Outer visual matches the Campaign Workflow ingredient: flat, transparent
// row with the same 36px icon, 11px label, 15px value pattern as the
// surrounding Plan rows. Below the row, the stage sequence renders as a
// stack of bordered cards - mirrors the Workflow phase-card pattern from
// Campaign detail.
// =============================================================================
function JourneyFlowInlineSection({ journey, onDiscuss, isSmall }) {
  const [hover, setHover] = useState(false);
  const stages = journey.stages || [];
  const stageRows = stages.map((label, i) => ({
    index: i + 1,
    label,
    channel: stageChannelFor(journey, i),
    customers: stageCustomersFor(journey, i),
    dropoff: stageDropoffFor(journey, i)
  }));
  
  const stageCount = stageRows.length;
  const valueLine = stageCount === 0
    ? 'Not configured'
    : stageCount + (stageCount === 1 ? '-touch sequence' : '-touch sequence');
  const channelsList = Array.from(new Set(stageRows.map(s => s.channel))).join(' \u00b7 ');
  
  return (
    <div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        padding: '18px 16px',
        margin: '0 -16px',
        borderRadius: '10px',
        background: hover ? t.surface : 'transparent',
        transition: 'background 0.18s ease',
        position: 'relative'
      }}
    >
      {/* Outer row: icon + label + value + meta + discuss button. Identical
          geometry to JourneyPlanRow so the Flow section reads as the same
          ingredient family. */}
      <div style={{
        display: 'flex',
        alignItems: 'flex-start',
        gap: '14px'
      }}>
        <div style={{
          width: '36px', height: '36px',
          borderRadius: '8px',
          background: hover ? t.bgPrimary : t.surface,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          flexShrink: 0,
          transition: 'background 0.18s ease'
        }}>
          <Workflow size={16} strokeWidth={1.75} color={t.textSecondary} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            fontSize: '11px', color: t.textTertiary,
            fontWeight: 500, marginBottom: '3px'
          }}>
            Flow
          </div>
          <div style={{
            fontSize: '15px', color: t.textPrimary,
            lineHeight: 1.45, fontWeight: 500
          }}>
            {valueLine}
          </div>
          {channelsList && stageCount > 0 && (
            <div style={{
              fontSize: '12px', color: t.textSecondary,
              lineHeight: 1.5, marginTop: '8px'
            }}>
              {channelsList}
            </div>
          )}
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation();
            onDiscuss && onDiscuss({
              label: 'Flow for ' + journey.name,
              displayLabel: 'journey',
              prefilledQuestion: 'Walk me through the flow of this journey. Why these stages?'
            });
          }}
          style={{
            padding: '6px 8px',
            background: 'transparent', color: t.textTertiary,
            border: 'none', borderRadius: '6px', cursor: 'pointer',
            display: 'flex', alignItems: 'center',
            flexShrink: 0,
            opacity: hover ? 1 : 0,
            transition: 'opacity 0.18s ease, background 0.12s, color 0.12s'
          }}
          onMouseEnter={(e) => { e.currentTarget.style.background = t.bgPrimary; e.currentTarget.style.color = t.accent; }}
          onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textTertiary; }}
          title="Discuss"
        >
          <MessageCircle size={14} strokeWidth={1.75} />
        </button>
      </div>
      
      {/* Stage cards: bordered, rounded, indented under the icon column so
          the stages visually nest under the Flow label. Mirrors the
          Workflow phase-card pattern from Campaign detail. */}
      {stageCount > 0 && (
        <div style={{
          marginTop: '16px',
          marginLeft: '50px',
          display: 'flex',
          flexDirection: 'column',
          gap: '8px'
        }}>
          {stageRows.map((stage, i) => (
            <JourneyStageCard key={i} stage={stage} journeyId={journey.id} isSmall={isSmall} />
          ))}
        </div>
      )}
    </div>
  );
}

// =============================================================================
// JOURNEY STAGE CREATIVES - per-stage creative content keyed by journey id
// and stage index. View-only, used to populate the previews that expand
// inside JourneyStageCard. Authoring real per-stage creative for every
