// Per-stage creative lookup. Returns { email?, sms? } or null if the stage
// doesn't have authored content. Real journeys would store this on the
// stage config object; for the prototype it's keyed by id+index.
function getStageCreatives(journeyId, stageIndex) {
  return JOURNEY_STAGE_CREATIVES[journeyId]?.[stageIndex] || null;
}

// Parse "Email + SMS" -> ['email', 'sms']. "BDC call" -> ['bdc']. Used to
// decide which preview types to render in the expanded stage card.
function parseStageChannels(channelLabel) {
  return channelLabel
    .toLowerCase()
    .split(/[+,]/)
    .map(s => s.trim())
    .map(s => {
      if (s.includes('email')) return 'email';
      if (s.includes('sms') || s.includes('text')) return 'sms';
      if (s.includes('bdc') || s.includes('call')) return 'bdc';
      if (s.includes('mail')) return 'directmail';
      return s;
    });
}

