// Stage card - one per touch in the journey. Bordered card with a small
// header (stage name + step-of-N hint) and a meta row below (channel +
// in-stage count + drop-off). Visual cousin to the Workflow phase-card
// from Campaign detail, but condensed since journey stages don't have
// their own date ranges, audience splits, or creative variants the way
// campaign phases do.
//
// Click anywhere on the top row to expand and reveal the per-channel
// creative previews. Chevron on the right indicates the affordance.
function JourneyStageCard({ stage, journeyId, isSmall }) {
  const [expanded, setExpanded] = useState(false);
  const channels = parseStageChannels(stage.channel);
  const creatives = getStageCreatives(journeyId, stage.index - 1);
  // A stage is previewable if any of its channels has a creative or is
  // an inherently non-previewable channel like BDC call (we still want
  // to show the chevron in that case, since users may want to know what
  // happens at that step).
  const hasContent = channels.length > 0;
  
  return (
    <div style={{
      background: t.bgPrimary,
      border: '1px solid ' + t.surfaceMuted,
      borderRadius: '10px',
      overflow: 'hidden'
    }}>
      {/* Top row - click to expand */}
      <div
        onClick={() => hasContent && setExpanded(v => !v)}
        style={{
          padding: '14px 16px',
          display: 'flex',
          alignItems: 'center',
          gap: '14px',
          flexWrap: isSmall ? 'wrap' : 'nowrap',
          cursor: hasContent ? 'pointer' : 'default',
          transition: 'background 0.12s'
        }}
        onMouseEnter={(e) => { if (hasContent) e.currentTarget.style.background = t.surface; }}
        onMouseLeave={(e) => { e.currentTarget.style.background = t.bgPrimary; }}
      >
        {/* Stage index badge */}
        <div style={{
          width: '24px', height: '24px',
          borderRadius: '50%',
          background: t.accentSoft, color: t.accent,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: '12px', fontWeight: 600,
          fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
          flexShrink: 0
        }}>
          {stage.index}
        </div>
        
        {/* Stage label */}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            fontSize: '14px', fontWeight: 600, color: t.textPrimary,
            lineHeight: 1.35
          }}>
            {stage.label}
          </div>
          <div style={{
            fontSize: '12px', color: t.textTertiary,
            lineHeight: 1.5, marginTop: '2px'
          }}>
            {stage.channel}
          </div>
        </div>
        
        {/* Right-side metrics. Two compact stats: customers currently in
            this stage, and stage-level drop-off. */}
        <div style={{
          display: 'flex', gap: '24px', alignItems: 'center',
          flexShrink: 0,
          marginLeft: isSmall ? '38px' : 0
        }}>
          <div style={{ textAlign: 'right', minWidth: '70px' }}>
            <div style={{
              fontSize: '11px', color: t.textTertiary,
              fontWeight: 500, marginBottom: '2px'
            }}>
              In stage
            </div>
            <div style={{
              fontSize: '14px', fontWeight: 600, color: t.textPrimary,
              fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
            }}>
              {stage.customers.toLocaleString()}
            </div>
          </div>
          <div style={{ textAlign: 'right', minWidth: '60px' }}>
            <div style={{
              fontSize: '11px', color: t.textTertiary,
              fontWeight: 500, marginBottom: '2px'
            }}>
              Drop-off
            </div>
            <div style={{
              fontSize: '14px', fontWeight: 600,
              color: stage.dropoff > 30 ? t.warning : t.textPrimary,
              fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
            }}>
              {stage.dropoff}%
            </div>
          </div>
          {hasContent && (
            <div style={{
              flexShrink: 0,
              color: t.textTertiary,
              display: 'flex', alignItems: 'center',
              transform: expanded ? 'rotate(90deg)' : 'rotate(0deg)',
              transition: 'transform 0.18s ease'
            }}>
              <ChevronRight size={16} strokeWidth={1.75} />
            </div>
          )}
        </div>
      </div>
      
      {/* Expanded creative panel - one preview per channel for this stage. */}
      {expanded && hasContent && (
        <div style={{
          padding: '4px 16px 16px',
          borderTop: '1px solid ' + t.surfaceMuted,
          background: t.surface
        }}>
          <div style={{
            fontSize: '11px', color: t.textTertiary,
            fontWeight: 500, margin: '12px 0 10px'
          }}>
            Creative for this touch
          </div>
          <div style={{
            display: 'grid',
            gridTemplateColumns: isSmall || channels.length === 1 ? '1fr' : '1fr 1fr',
            gap: '10px'
          }}>
            {channels.map((ch, ci) => {
              if (ch === 'email' && creatives?.email) {
                return <JourneyEmailPreview key={ci} creative={creatives.email} />;
              }
              if (ch === 'sms' && creatives?.sms) {
                return <JourneySmsPreview key={ci} creative={creatives.sms} />;
              }
              // Channel exists for this stage but no preview content - either
              // a non-previewable channel (BDC, direct mail) or just unmapped
              // content. Show the placeholder either way.
              const label = ch === 'email' ? 'Email'
                : ch === 'sms' ? 'SMS'
                : ch === 'bdc' ? 'BDC call'
                : ch === 'directmail' ? 'Direct mail'
                : ch.charAt(0).toUpperCase() + ch.slice(1);
              return <JourneyChannelPlaceholder key={ci} channelLabel={label} />;
            })}
          </div>
        </div>
      )}
    </div>
  );
}

// Stage-channel mapping - rough mapping that varies by journey + stage index.
function stageChannelFor(j, i) {
  if (j.id === 'j1') {
    return ['Email', 'Email', 'Email + SMS', 'SMS'][i] || 'Email';
  }
  if (j.id === 'j2') {
    return ['SMS', 'Email', 'BDC call'][i] || 'SMS';
  }
  if (j.id === 'j3') {
    return ['Email', 'Email', 'Email'][i] || 'Email';
  }
  if (j.id === 'j4') {
    return ['Email', 'Email', 'Direct mail'][i] || 'Email';
  }
  if (j.id === 'j5') {
    return ['Email', 'Email', 'Email'][i] || 'Email';
  }
  if (j.id === 'j6') {
    return 'SMS';
  }
  if (j.id === 'j7') {
    return ['Email', 'Email + SMS', 'Email'][i] || 'Email';
  }
  return 'Email';
}

// Stage-population estimate - rough funnel. Real journeys would track this
// via attribution. For the prototype, derive from in-motion + a decay curve.
function stageCustomersFor(j, i) {
  const base = j.inMotion || 0;
  if (base === 0) return 0;
  const decay = [1.0, 0.78, 0.58, 0.42];
  return Math.round(base * (decay[i] || 0.3));
}

// Stage-drop-off estimate - inverse of population delta. Stage 1 has no
// drop-off (it's the entry). Later stages compound.
function stageDropoffFor(j, i) {
  if (i === 0) return 0;
  // Approximate per-stage drop-off from the decay curve above.
  const drops = [0, 22, 26, 28];
  return drops[i] || 30;
}

// =============================================================================
// PERFORMANCE TAB - the always-on health monitoring surface. Three sections:
// summary cards, attributed gross trend (placeholder bar), and stage funnel.
// =============================================================================
function JourneyPerformanceBody({ journey, onDiscuss, isSmall }) {
  // For pending-review journeys this tab shouldn't really be visible (we
  // default to Overview for them), but render an empty state if someone
  // navigates here.
  if (journey.status === 'pending_review') {
    return (
      <div style={{
        padding: '48px 32px',
        textAlign: 'center',
        background: t.surface,
        borderRadius: '12px',
        color: t.textSecondary
      }}>
        <div style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary, marginBottom: '6px' }}>
          No performance data yet
        </div>
        <div style={{ fontSize: '13px', color: t.textTertiary }}>
          Activate this journey to start collecting performance signals.
        </div>
      </div>
    );
  }
  
  // Synthesize a 6-month trend - last value = convertedThisMonth, earlier
  // months drift up/down a bit. Reads as plausible without backing data.
  const trend = synthesizeTrend(journey.convertedThisMonth || 0);
  const trendMax = Math.max(...trend.values, 1);
  
  // Funnel - reuse the same per-stage population helpers from the Flow body
  // so the two tabs stay numerically consistent.
  const stageFunnel = (journey.stages || []).map((label, i) => ({
    label,
    customers: stageCustomersFor(journey, i),
    pctOfStart: journey.inMotion ? Math.round(100 * stageCustomersFor(journey, i) / journey.inMotion) : 0
  }));
  
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
      {/* Top summary cards - bigger than the header status block, more
          editorial. Each card includes a one-liner of context so the
          numbers read as meaningful, not just decoration. */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: isSmall ? '1fr' : 'repeat(3, 1fr)',
        gap: '12px'
      }}>
        <JourneyPerfCard
          label="Customers in motion"
          value={journey.inMotion.toLocaleString()}
          sub="moving through the journey right now"
        />
        <JourneyPerfCard
          label="Converted this month"
          value={journey.convertedThisMonth.toLocaleString()}
          sub={journey.convertedTrend || 'no trend data'}
        />
        <JourneyPerfCard
          label="Conversion rate"
          value={journey.conversionRate !== null && journey.conversionRate !== undefined
            ? journey.conversionRate.toFixed(1) + '%'
            : '\u2014'}
          sub="of customers reaching the goal"
        />
      </div>
      
      {/* Trend bar - last 6 months of conversions. Visual is a simple bar
          row, no axes. The point here is "is the line going up or down,"
          not precise numeric read. */}
      <div style={{
        padding: '20px',
        background: t.surface,
        borderRadius: '12px'
      }}>
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: '16px' }}>
          <div>
            <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, marginBottom: '4px' }}>
              Conversions, last 6 months
            </div>
            <div style={{
              fontSize: '20px', fontWeight: 600, color: t.textPrimary,
              fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
              letterSpacing: '-0.01em'
            }}>
              {trend.values.reduce((a, b) => a + b, 0).toLocaleString()} total
            </div>
          </div>
          <div style={{ fontSize: '12px', color: t.textSecondary }}>
            {journey.convertedTrend || ''}
          </div>
        </div>
        <div style={{
          display: 'flex', alignItems: 'flex-end', gap: '8px',
          height: '120px',
          paddingTop: '8px'
        }}>
          {trend.values.map((v, i) => (
            <div key={i} style={{
              flex: 1,
              display: 'flex', flexDirection: 'column', alignItems: 'center',
              gap: '8px'
            }}>
              <div style={{
                width: '100%',
                height: Math.max(4, (v / trendMax) * 96) + 'px',
                background: i === trend.values.length - 1 ? t.accent : t.accentSoft,
                borderRadius: '6px 6px 2px 2px',
                transition: 'height 0.2s'
              }} />
              <div style={{
                fontSize: '10px', color: t.textTertiary, fontWeight: 500,
                fontFamily: fontStack
              }}>
                {trend.labels[i]}
              </div>
            </div>
          ))}
        </div>
      </div>
      
      {/* Stage funnel - shows how customers attrit through the journey. */}
      {stageFunnel.length > 0 && (
        <div style={{
          padding: '20px',
          background: t.surface,
          borderRadius: '12px'
        }}>
          <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, marginBottom: '14px' }}>
            Stage funnel
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {stageFunnel.map((row, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
                <div style={{
                  width: '140px', fontSize: '13px', color: t.textPrimary, fontWeight: 500,
                  whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis'
                }}>
                  {row.label}
                </div>
                <div style={{ flex: 1, position: 'relative', height: '20px' }}>
                  <div style={{
                    position: 'absolute', left: 0, top: 0, bottom: 0,
                    width: row.pctOfStart + '%',
                    background: t.accentSoft,
                    borderRadius: '6px',
                    transition: 'width 0.3s'
                  }} />
                </div>
                <div style={{
                  width: '70px', textAlign: 'right',
                  fontSize: '13px', fontWeight: 600, color: t.textPrimary,
                  fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
                }}>
                  {row.customers.toLocaleString()}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// Small perf card used inside JourneyPerformanceBody summary row.
function JourneyPerfCard({ label, value, sub }) {
  return (
    <div style={{
      padding: '16px 18px',
      background: t.surface,
      borderRadius: '12px'
    }}>
      <div style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, marginBottom: '6px' }}>
        {label}
      </div>
      <div style={{
        fontSize: '24px', fontWeight: 600, color: t.textPrimary,
        fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
        letterSpacing: '-0.02em', lineHeight: 1.15, marginBottom: '6px'
      }}>
        {value}
      </div>
      <div style={{ fontSize: '12px', color: t.textTertiary, lineHeight: 1.45 }}>
        {sub}
      </div>
    </div>
  );
}

// Synthesize a plausible 6-month trend ending at currentValue. The first
// 5 months vary +/-30% off currentValue so the bar chart reads as data,
// not a placeholder.
function synthesizeTrend(currentValue) {
  // Deterministic per-value so re-renders don't reshuffle.
  const offsets = [-0.18, 0.05, -0.12, 0.08, -0.04, 0];
  const labels = ['Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May'];
  const values = offsets.map(o => Math.max(0, Math.round(currentValue * (1 + o))));
  return { values, labels };
}

