function ReputationWorkspace({ isTablet, isSmall, onDiscuss }) {
  const [filterSource, setFilterSource] = useState('all');
  const [filterRating, setFilterRating] = useState('all');
  
  // Apply filters
  const matchFilters = (r) => {
    if (filterSource !== 'all' && r.source.toLowerCase() !== filterSource) return false;
    if (filterRating !== 'all') {
      if (filterRating === '5' && r.rating !== 5) return false;
      if (filterRating === '4' && r.rating !== 4) return false;
      if (filterRating === '3orless' && r.rating > 3) return false;
    }
    return true;
  };
  
  const filtered = REVIEWS_SEED.filter(matchFilters);
  
  const needsEye = filtered.filter(r => r.aiResponse && !r.sentResponse);
  const autoHandling = filtered.filter(r => r.autoReplied);
  const recent = filtered.filter(r => r.sentResponse);
  
  // Aggregate metrics
  const allReviews = REVIEWS_SEED;
  const avgRating = (allReviews.reduce((sum, r) => sum + r.rating, 0) / allReviews.length).toFixed(1);
  const last7Negatives = allReviews.filter(r => r.rating <= 3).length;
  
  return (
    <div>
      {/* Aggregate metrics */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: isSmall ? '1fr 1fr' : 'repeat(4, 1fr)',
        gap: '12px',
        marginBottom: '24px'
      }}>
        <SummaryCard
          label="Avg rating, last 30 days"
          value={avgRating + ' \u2605'}
          sub="across all sources"
        />
        <SummaryCard
          label="Needs your eye"
          value={String(needsEye.length)}
          sub={needsEye.length === 1 ? 'review with draft' : 'reviews with drafts'}
          accent={needsEye.length > 0}
        />
        <SummaryCard
          label="Auto-handled"
          value={String(autoHandling.length)}
          sub="positive replies sent today"
        />
        <SummaryCard
          label="Negatives, last 7 days"
          value={String(last7Negatives)}
          sub="3 or fewer stars"
        />
      </div>
      
      {/* Filter strip */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: '8px',
        marginBottom: '24px',
        flexWrap: 'wrap'
      }}>
        <FilterPill
          label="Source"
          value={filterSource}
          options={[
            { value: 'all', label: 'All' },
            { value: 'google', label: 'Google' },
            { value: 'dealerrater', label: 'DealerRater' },
            { value: 'yelp', label: 'Yelp' }
          ]}
          onChange={setFilterSource}
        />
        <FilterPill
          label="Rating"
          value={filterRating}
          options={[
            { value: 'all', label: 'All' },
            { value: '5', label: '5 stars only' },
            { value: '4', label: '4 stars' },
            { value: '3orless', label: '3 stars or fewer' }
          ]}
          onChange={setFilterRating}
        />
      </div>
      
      {/* Needs your eye zone */}
      {needsEye.length > 0 && (
        <ReviewSection
          title="Needs your eye"
          count={needsEye.length}
          subtitle="I have responses drafted. Approve, refine, or escalate."
        >
          {needsEye.map(r => (
            <ReviewCard key={r.id} review={r} mode="draft" onDiscuss={onDiscuss} />
          ))}
        </ReviewSection>
      )}
      
      {/* Auto-handling zone */}
      {autoHandling.length > 0 && (
        <ReviewSection
          title="Auto-handled"
          count={autoHandling.length}
          subtitle="Positive reviews. I'm sending branded thank-yous automatically. Spot-check or pause auto-reply if needed."
        >
          {autoHandling.map(r => (
            <ReviewCard key={r.id} review={r} mode="autoreplied" onDiscuss={onDiscuss} />
          ))}
        </ReviewSection>
      )}
      
      {/* Recent zone */}
      {recent.length > 0 && (
        <ReviewSection
          title="Recent"
          count={recent.length}
          subtitle="Responses sent in the last 7 days."
        >
          {recent.map(r => (
            <ReviewCard key={r.id} review={r} mode="sent" onDiscuss={onDiscuss} />
          ))}
        </ReviewSection>
      )}
      
      {/* Empty state */}
      {needsEye.length === 0 && autoHandling.length === 0 && recent.length === 0 && (
        <div style={{
          padding: '48px 32px',
          textAlign: 'center',
          background: t.surface,
          borderRadius: '12px',
          color: t.textSecondary
        }}>
          <div style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary, marginBottom: '6px' }}>
            No reviews match these filters
          </div>
          <div style={{ fontSize: '13px', color: t.textTertiary }}>
            Adjust your filters to see more.
          </div>
        </div>
      )}
    </div>
  );
}

// ----- Review section wrapper -----
function ReviewSection({ title, subtitle, count, children }) {
  return (
    <div style={{ marginBottom: '32px' }}>
      <div style={{ marginBottom: '12px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
          <h2 style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, margin: 0, letterSpacing: '-0.005em' }}>
            {title}
          </h2>
          <span style={{ fontSize: '12px', color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', fontWeight: 500 }}>
            {count}
          </span>
        </div>
        {subtitle && (
          <p style={{ fontSize: '12px', color: t.textTertiary, margin: '4px 0 0', lineHeight: 1.5 }}>
            {subtitle}
          </p>
        )}
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        {children}
      </div>
    </div>
  );
}

// ----- Star renderer -----
function StarRow({ rating }) {
  return (
    <div style={{ display: 'flex', gap: '1px' }}>
      {[1,2,3,4,5].map(n => (
        <Star
          key={n}
          size={12}
          strokeWidth={1.5}
          color={n <= rating ? t.warning : t.surfaceMuted}
          fill={n <= rating ? t.warning : 'none'}
        />
      ))}
    </div>
  );
}

// ----- Review card -----
function ReviewCard({ review, mode, onDiscuss }) {
  const [editedDraft, setEditedDraft] = useState(review.aiResponse || '');
  const [isEditing, setIsEditing] = useState(false);
  
  return (
    <div style={{
      padding: mode === 'autoreplied' ? '12px 16px' : '16px 20px',
      background: t.surface,
      borderRadius: '10px'
    }}>
      {/* Header: source, stars, reviewer, timestamp */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
        marginBottom: mode === 'autoreplied' ? '6px' : '10px',
        flexWrap: 'wrap'
      }}>
        <div style={{
          fontSize: '11px', fontWeight: 600, color: t.textSecondary,
          padding: '2px 8px', background: t.bgPrimary, borderRadius: '5px'
        }}>
          {review.source}
        </div>
        <StarRow rating={review.rating} />
        <div style={{ fontSize: '12px', color: t.textPrimary, fontWeight: 500 }}>
          {review.reviewer}
        </div>
        <div style={{ fontSize: '11px', color: t.textTertiary }}>
          {review.timestamp}
        </div>
      </div>
      
      {/* Review text */}
      <div style={{
        fontSize: mode === 'autoreplied' ? '12px' : '13px',
        color: t.textPrimary,
        lineHeight: 1.55,
        marginBottom: mode === 'autoreplied' ? 0 : '14px'
      }}>
        {mode === 'autoreplied' ? truncate(review.review, 140) : review.review}
      </div>
      
      {/* AI commentary - shown for draft mode only */}
      {mode === 'draft' && review.aiCommentary && (
        <div style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: '8px',
          padding: '10px 12px',
          background: t.bgPrimary,
          borderRadius: '8px',
          marginBottom: '12px'
        }}>
          <img src={TEKION_AI_LOGO} alt="" style={{ width: '14px', height: '14px', marginTop: '2px', flexShrink: 0 }} />
          <div style={{ fontSize: '12px', color: t.textSecondary, lineHeight: 1.5 }}>
            {review.aiCommentary}
          </div>
        </div>
      )}
      
      {/* Draft response (editable) - draft mode */}
      {mode === 'draft' && (
        <>
          <div style={{ fontSize: '11px', fontWeight: 600, color: t.textTertiary, marginBottom: '6px', letterSpacing: '0.02em' }}>
            Draft response
          </div>
          {isEditing ? (
            <textarea
              value={editedDraft}
              onChange={(e) => setEditedDraft(e.target.value)}
              style={{
                width: '100%',
                minHeight: '100px',
                padding: '12px 14px',
                background: t.bgPrimary,
                border: '1px solid ' + t.accent,
                borderRadius: '8px',
                fontSize: '13px',
                color: t.textPrimary,
                fontFamily: fontStack,
                lineHeight: 1.55,
                outline: 'none',
                resize: 'vertical',
                boxSizing: 'border-box',
                marginBottom: '12px'
              }}
            />
          ) : (
            <div style={{
              padding: '12px 14px',
              background: t.bgPrimary,
              borderRadius: '8px',
              fontSize: '13px', color: t.textPrimary, lineHeight: 1.55,
              marginBottom: '12px'
            }}>
              {editedDraft}
            </div>
          )}
          
          {/* Action buttons */}
          <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
            <button
              onClick={() => alert('Response sent (prototype)')}
              style={{
                padding: '7px 14px',
                background: t.accent,
                color: t.textOnColor,
                border: 'none',
                borderRadius: '7px',
                fontSize: '12px', fontWeight: 600,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = t.accentHover}
              onMouseLeave={(e) => e.currentTarget.style.background = t.accent}
            >
              Send
            </button>
            <button
              onClick={() => setIsEditing(!isEditing)}
              style={{
                padding: '7px 12px',
                background: 'transparent',
                color: t.textSecondary,
                border: 'none',
                borderRadius: '7px',
                fontSize: '12px', fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textPrimary; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
            >
              {isEditing ? 'Done editing' : 'Refine'}
            </button>
            <button
              onClick={() => alert('Escalated to store ops (prototype)')}
              style={{
                padding: '7px 12px',
                background: 'transparent',
                color: t.textSecondary,
                border: 'none',
                borderRadius: '7px',
                fontSize: '12px', fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textPrimary; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
            >
              Escalate
            </button>
            <button
              onClick={() => onDiscuss({ label: 'Review from ' + review.reviewer, prefilledQuestion: 'Help me think about how to respond to this review.' })}
              style={{
                padding: '7px 12px',
                background: 'transparent',
                color: t.textSecondary,
                border: 'none',
                borderRadius: '7px',
                fontSize: '12px', fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textPrimary; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
            >
              Discuss
            </button>
          </div>
        </>
      )}
      
      {/* Auto-replied state */}
      {mode === 'autoreplied' && (
        <div style={{
          fontSize: '11px',
          color: t.textTertiary,
          marginTop: '8px',
          fontStyle: 'italic'
        }}>
          AI sent a branded thank-you reply.
        </div>
      )}
      
      {/* Sent response */}
      {mode === 'sent' && (
        <>
          <div style={{
            padding: '12px 14px',
            background: t.bgPrimary,
            borderRadius: '8px',
            fontSize: '13px', color: t.textPrimary, lineHeight: 1.55,
            marginBottom: '8px'
          }}>
            {review.sentResponse}
          </div>
          <div style={{ fontSize: '11px', color: t.textTertiary }}>
            {review.refinedFromAI ? 'Refined from AI draft and ' : ''}sent by {review.sentBy}, {review.sentAt}
          </div>
        </>
      )}
    </div>
  );
}

function truncate(text, max) {
  if (text.length <= max) return text;
  return text.slice(0, max - 1).trim() + '\u2026';
}


