function OEMProgramsWorkspace({ isTablet, isSmall, onDiscuss }) {
  const [selectedOEM, setSelectedOEM] = useState(null);
  
  // Aggregate metrics
  const totalAvailable = OEMS_SEED.reduce((sum, o) => sum + o.funds.available, 0);
  const totalExpiring = OEMS_SEED.reduce((sum, o) => sum + o.funds.expiringThisQuarter, 0);
  const totalDrafts = OEMS_SEED.reduce((sum, o) => sum + o.claims.drafts, 0);
  const totalDisputed = OEMS_SEED.reduce((sum, o) => sum + o.claims.disputed, 0);
  
  // Sort: needs attention first
  const sortedOEMs = [...OEMS_SEED].sort((a, b) => {
    if (a.needsAttention !== b.needsAttention) return a.needsAttention ? -1 : 1;
    return 0;
  });
  
  return (
    <div>
      {/* Aggregate summary */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: isSmall ? '1fr 1fr' : 'repeat(4, 1fr)',
        gap: '12px',
        marginBottom: '24px'
      }}>
        <SummaryCard
          label="Co-op available"
          value={'$' + (totalAvailable / 1000).toFixed(0) + 'K'}
          sub="across all OEMs"
        />
        <SummaryCard
          label="Expiring this quarter"
          value={'$' + (totalExpiring / 1000).toFixed(0) + 'K'}
          sub="if not used by quarter-end"
          accent={totalExpiring > 0}
        />
        <SummaryCard
          label="Claims to review"
          value={String(totalDrafts)}
          sub={totalDrafts === 1 ? 'draft awaiting your eye' : 'drafts awaiting your eye'}
          accent={totalDrafts > 0}
        />
        <SummaryCard
          label="Disputed claims"
          value={String(totalDisputed)}
          sub={totalDisputed === 1 ? 'OEM denial in flight' : 'OEM denials in flight'}
          accent={totalDisputed > 0}
        />
      </div>
      
      {/* OEMs header */}
      <div style={{ marginBottom: '12px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
          <h2 style={{ fontSize: '15px', fontWeight: 600, color: t.textPrimary, margin: 0, letterSpacing: '-0.005em' }}>
            Manufacturers
          </h2>
          <span style={{ fontSize: '12px', color: t.textTertiary, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', fontWeight: 500 }}>
            {OEMS_SEED.length}
          </span>
        </div>
      </div>
      
      {/* OEM cards */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: isSmall ? '1fr' : 'repeat(auto-fit, minmax(380px, 1fr))',
        gap: '12px'
      }}>
        {sortedOEMs.map(oem => (
          <OEMCard
            key={oem.id}
            oem={oem}
            onClick={() => setSelectedOEM(oem)}
            onDiscuss={onDiscuss}
          />
        ))}
      </div>
      
      {/* Detail placeholder */}
      {selectedOEM && (
        <OEMDetailPlaceholder oem={selectedOEM} onClose={() => setSelectedOEM(null)} />
      )}
    </div>
  );
}

