// ============= STANCE RENDERER WITH AI-HIGHLIGHTED PRINCIPLES =============
// Renders the stance text with specific phrases underlined. Each underlined phrase
// is clickable and opens the discuss panel with that principle as context.
function renderStanceWithPrinciples(text, principles, onDiscuss) {
  if (!principles || principles.length === 0) {
    return text;
  }
  
  // Build a list of all match positions across the text
  const matches = [];
  principles.forEach(phrase => {
    let searchStart = 0;
    while (true) {
      const idx = text.indexOf(phrase, searchStart);
      if (idx === -1) break;
      matches.push({ start: idx, end: idx + phrase.length, phrase });
      searchStart = idx + phrase.length;
    }
  });
  
  // Sort and de-overlap (keep the first occurrence if overlap)
  matches.sort((a, b) => a.start - b.start);
  const filtered = [];
  let lastEnd = -1;
  for (const m of matches) {
    if (m.start >= lastEnd) {
      filtered.push(m);
      lastEnd = m.end;
    }
  }
  
  // Walk the text, splitting around the matches
  const out = [];
  let cursor = 0;
  filtered.forEach((m, i) => {
    if (m.start > cursor) {
      out.push(<React.Fragment key={`t${i}`}>{text.slice(cursor, m.start)}</React.Fragment>);
    }
    out.push(
      <span
        key={`m${i}`}
        onClick={(e) => {
          e.stopPropagation();
          onDiscuss({
            label: m.phrase,
            prefilledQuestion: `Tell me how you are applying this principle: "${m.phrase}". What does this mean for the work you are doing?`
          });
        }}
        style={{
          textDecoration: 'underline',
          textDecorationColor: t.textTertiary,
          textDecorationThickness: '1.5px',
          textUnderlineOffset: '4px',
          cursor: 'pointer',
          transition: 'background 0.12s, text-decoration-color 0.12s',
          borderRadius: '3px',
          padding: '0 2px',
          margin: '0 -1px'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.background = t.surfaceMuted;
          e.currentTarget.style.textDecorationColor = t.textSecondary;
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.background = 'transparent';
          e.currentTarget.style.textDecorationColor = t.textTertiary;
        }}
      >
        {m.phrase}
      </span>
    );
    cursor = m.end;
  });
  if (cursor < text.length) {
    out.push(<React.Fragment key="tail">{text.slice(cursor)}</React.Fragment>);
  }
  
  return out;
}

// ============= CLICKABLE PROSE PARSER =============
// Splits prose on **bold** markers and renders bold spans as clickable, opening discuss panel
function parseClickableProse(text, onDiscuss) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      const content = part.slice(2, -2);
      return (
        <span
          key={i}
          onClick={(e) => {
            e.stopPropagation();
            onDiscuss({
              label: content,
              prefilledQuestion: `Walk me through ${content}, what is driving this?`
            });
          }}
          style={{
            color: t.textPrimary,
            fontWeight: 600,
            cursor: 'pointer',
            borderRadius: '4px',
            padding: '0 3px',
            margin: '0 -1px',
            transition: 'background 0.12s'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.accentSoft}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          {content}
        </span>
      );
    }
    return <React.Fragment key={i}>{part}</React.Fragment>;
  });
}

// ============= DISCUSSABLE WRAPPER =============
// Wraps any element to be "discussable" with hover halo + chip
//
// Hover behavior:
// - 250ms entry delay: cursor must rest on the wrapper before chip appears.
//   Prevents fast cursor traversal across stacked cards from lighting all chips.
// - 200ms exit delay: cursor leaving the wrapper has 200ms to reach the chip
//   before it dismisses. Bridges the 8px gap between card and chip.
// - The chip's interactive area extends 8px around its visible body, so the
//   gap between chip and card is part of the chip's hover capture zone.
function Discussable({ label, prefilledQuestion, description, suggestedChips, displayLabel, parentLabel, onDiscuss, children, style, actions }) {
  const [hover, setHover] = useState(false);
  // discussOpen mirrors when THIS Discussable opened the global AIWidget.
  // While true, the chip stays forceShown and the wrapper gets a subtle
  // selection treatment - so the user sees which card the popover ties to.
  const [discussOpen, setDiscussOpen] = useState(false);
  const hoverInTimeoutRef = useRef(null);
  const hoverOutTimeoutRef = useRef(null);
  // Anchor for AIWidget positioning. We point at the chip's outer wrapper
  // because the chip is the visible affordance the user just clicked - and
  // the chip's location is what spatially "owns" the popover.
  const chipAnchorRef = useRef(null);
  
  // Default action set, can be extended via the `actions` prop. Forwards
  // optional AIWidget hints (description, suggestedChips, displayLabel,
  // parentLabel, anchorRef) so the widget can render curated content and
  // anchor itself to this card. Passes onWidgetClose so the chip can clear
  // its sticky-shown state when the widget dismisses.
  const allActions = actions || [
    {
      label: 'Discuss',
      icon: 'ai',
      onClick: () => {
        setDiscussOpen(true);
        onDiscuss({
          label,
          prefilledQuestion,
          description,
          suggestedChips,
          displayLabel,
          parentLabel,
          anchorRef: chipAnchorRef,
          onWidgetClose: () => setDiscussOpen(false)
        });
      }
    }
  ];

  const handleMouseEnter = () => {
    // Cancel any pending exit
    if (hoverOutTimeoutRef.current) {
      clearTimeout(hoverOutTimeoutRef.current);
      hoverOutTimeoutRef.current = null;
    }
    // Already shown - nothing to do
    if (hover) return;
    // Schedule entry after delay - requires deliberate hover, not casual sweep
    if (hoverInTimeoutRef.current) clearTimeout(hoverInTimeoutRef.current);
    hoverInTimeoutRef.current = setTimeout(() => {
      setHover(true);
      hoverInTimeoutRef.current = null;
    }, 250);
  };

  // Used by chip itself - already deliberate, skip the entry delay
  const handleChipMouseEnter = () => {
    if (hoverOutTimeoutRef.current) {
      clearTimeout(hoverOutTimeoutRef.current);
      hoverOutTimeoutRef.current = null;
    }
    if (hoverInTimeoutRef.current) {
      clearTimeout(hoverInTimeoutRef.current);
      hoverInTimeoutRef.current = null;
    }
    setHover(true);
  };

  const handleMouseLeave = () => {
    // Cancel any pending entry - cursor left before delay completed
    if (hoverInTimeoutRef.current) {
      clearTimeout(hoverInTimeoutRef.current);
      hoverInTimeoutRef.current = null;
    }
    // Schedule dismiss after delay - bridges the 8px gap to the chip
    hoverOutTimeoutRef.current = setTimeout(() => {
      setHover(false);
    }, 200);
  };
  
  return (
    <div
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      style={{
        position: 'relative',
        // Subtle selection treatment while AIWidget is open from this card.
        // Mirrors the "this card is what the popover ties to" affordance
        // we have on campaign-detail rows.
        boxShadow: discussOpen ? 'inset 0 0 0 2px ' + t.accent : 'none',
        borderRadius: discussOpen ? '10px' : (style && style.borderRadius) || '0',
        transition: 'box-shadow 0.18s ease',
        ...style
      }}
    >
      {children}
      {/* Chip hit area: invisible 8px padding around the visible chip so the
          gap zone (between chip and card) is part of the hover capture.
          The chip is forced visible while AIWidget is open from this card
          so the relationship reads as a selection state, not a dismissal. */}
      <div
        ref={chipAnchorRef}
        onMouseEnter={handleChipMouseEnter}
        onMouseLeave={handleMouseLeave}
        style={{
          position: 'absolute',
          bottom: 'calc(100% + 0px)',
          right: '4px',
          padding: '8px',
          zIndex: 10,
          pointerEvents: (hover || discussOpen) ? 'auto' : 'none',
          opacity: (hover || discussOpen) ? 1 : 0,
          transition: 'opacity 0.12s ease, transform 0.12s ease',
          transform: (hover || discussOpen) ? 'translateY(0)' : 'translateY(2px)'
        }}
      >
        {/* Visible chip body */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            background: t.bgPrimary,
            borderRadius: '8px',
            padding: '2px',
            boxShadow: '0 2px 8px rgba(22,22,22,0.1), 0 1px 3px rgba(22,22,22,0.06)'
          }}
        >
          {allActions.map((action, i) => (
            <button
              key={i}
              onClick={(e) => {
                e.stopPropagation();
                action.onClick();
              }}
              onMouseEnter={handleChipMouseEnter}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                padding: '6px 10px',
                background: 'transparent',
                color: t.textPrimary,
                border: 'none',
                borderRadius: '6px',
                fontSize: '12px',
                fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack,
                transition: 'background 0.12s'
              }}
              onMouseOver={(e) => e.currentTarget.style.background = t.surfaceMuted}
              onMouseOut={(e) => e.currentTarget.style.background = 'transparent'}
            >
              {action.icon === 'ai' && (
                <img src={TEKION_AI_LOGO} alt="" style={{ width: '14px', height: '14px' }} />
              )}
              {action.icon === 'edit' && (
                <Edit2 size={12} strokeWidth={1.75} color={t.textPrimary} />
              )}
              {action.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// ============= FLOATING ACTION CHIP =============
// Global hover-CTA component. Mirrors the Home tile "Discuss" chip pattern:
// floats above-and-right of the wrapped content on hover, with shadow + fade.
//
// Differs from Discussable in two ways:
//   1. Supports multiple actions in one chip (Home's Discuss + Edit pattern).
//   2. Exposes hover state via render-prop so the wrapped content can react
//      (e.g., apply a background tint on hover) while sharing the same hover
//      capture zone as the chip.
//
// Usage:
//   <FloatingActionChip
//     actions={[
//       { label: 'Discuss and refine', icon: 'ai', onClick: ..., ref: discussBtnRef },
//       { label: 'Edit', icon: 'edit', onClick: ... }
//     ]}
//     forceShow={discussOpen}  // keep chip visible while popover is open
//     suppress={refining}       // hide chip during refining animation
//   >
//     {(hover) => (
//       <div style={{ background: hover ? t.surface : 'transparent' }}>
//         ...content...
//       </div>
//     )}
//   </FloatingActionChip>
//
// Hover behavior matches Discussable: 250ms entry delay (prevents flicker on
// quick scan), 200ms exit delay (bridges the 8px gap between chip and content
// so the cursor can move from content to chip without dismiss).
function FloatingActionChip({ actions, children, style, suppress, forceShow }) {
  const [hover, setHover] = useState(false);
  const hoverInTimeoutRef = useRef(null);
  const hoverOutTimeoutRef = useRef(null);
  
  const handleMouseEnter = () => {
    if (hoverOutTimeoutRef.current) {
      clearTimeout(hoverOutTimeoutRef.current);
      hoverOutTimeoutRef.current = null;
    }
    if (hover) return;
    if (hoverInTimeoutRef.current) clearTimeout(hoverInTimeoutRef.current);
    hoverInTimeoutRef.current = setTimeout(() => {
      setHover(true);
      hoverInTimeoutRef.current = null;
    }, 250);
  };
  
  // Used by chip itself - already deliberate, skip the entry delay
  const handleChipMouseEnter = () => {
    if (hoverOutTimeoutRef.current) {
      clearTimeout(hoverOutTimeoutRef.current);
      hoverOutTimeoutRef.current = null;
    }
    if (hoverInTimeoutRef.current) {
      clearTimeout(hoverInTimeoutRef.current);
      hoverInTimeoutRef.current = null;
    }
    setHover(true);
  };
  
  const handleMouseLeave = () => {
    if (hoverInTimeoutRef.current) {
      clearTimeout(hoverInTimeoutRef.current);
      hoverInTimeoutRef.current = null;
    }
    hoverOutTimeoutRef.current = setTimeout(() => {
      setHover(false);
    }, 200);
  };
  
  const showChip = (hover || forceShow) && !suppress;
  
  // Support both children-as-function (gets hover state) and plain children
  const renderedChildren = typeof children === 'function' ? children(hover) : children;
  
  return (
    <div
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      style={{
        position: 'relative',
        ...style
      }}
    >
      {renderedChildren}
      {/* Chip hit area: invisible 8px padding around the visible chip so the
          gap zone (between chip and card) is part of the chip's hover capture */}
      <div
        onMouseEnter={handleChipMouseEnter}
        onMouseLeave={handleMouseLeave}
        style={{
          position: 'absolute',
          bottom: 'calc(100% + 0px)',
          right: '4px',
          padding: '8px',
          zIndex: 10,
          pointerEvents: showChip ? 'auto' : 'none',
          opacity: showChip ? 1 : 0,
          transition: 'opacity 0.12s ease, transform 0.12s ease',
          transform: showChip ? 'translateY(0)' : 'translateY(2px)'
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            background: t.bgPrimary,
            borderRadius: '8px',
            padding: '2px',
            boxShadow: '0 2px 8px rgba(22,22,22,0.1), 0 1px 3px rgba(22,22,22,0.06)'
          }}
        >
          {actions.map((action, i) => (
            <button
              key={i}
              ref={action.ref}
              onClick={(e) => {
                e.stopPropagation();
                action.onClick();
              }}
              onMouseEnter={handleChipMouseEnter}
              data-action-button={action.label}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                padding: '6px 10px',
                background: action.active ? t.accentSoft : 'transparent',
                color: action.active ? t.accent : t.textPrimary,
                border: 'none',
                borderRadius: '6px',
                fontSize: '12px',
                fontWeight: 500,
                cursor: 'pointer',
                fontFamily: fontStack,
                transition: 'background 0.12s'
              }}
              onMouseOver={(e) => {
                if (!action.active) e.currentTarget.style.background = t.surfaceMuted;
              }}
              onMouseOut={(e) => {
                if (!action.active) e.currentTarget.style.background = 'transparent';
              }}
            >
              {action.icon === 'ai' && (
                <img src={TEKION_AI_LOGO} alt="" style={{ width: '14px', height: '14px' }} />
              )}
              {action.icon === 'edit' && (
                <Edit2 size={12} strokeWidth={1.75} color={action.active ? t.accent : t.textPrimary} />
              )}
              {action.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// ============= APPROVAL CARD =============
// Single card pattern with two CTA modes. The card is a triage trigger:
// it tells the user what's needed and routes them to a fuller surface to act.
// Inline approval is reserved for confirmation-level decisions only.
//
// Anatomy: icon + headline + short description + meta strip + action row.
// No status pills, no AI logo, no inline reasoning paragraph.
//
// Kinds (icon library):
//   'campaign-plan' · 'budget' · 'objectives' · 'new-outreach' ·
//   'creative' · 'comms' · 'compliance'
//
// Modes:
//   'view' (default) -> [View] [Dismiss]
//   'approve'        -> [Approve] [Dismiss]

// Maps approval type (the schema field) to its icon + label. All 9 types
// from the approval-card spec are covered; legacy 'kind' values are also
// kept for back-compat with other rendering paths.
const APPROVAL_CARD_KINDS = {
  // New type values (per spec)
  'campaign-new':        { icon: Megaphone,    label: 'New campaign' },
  'campaign-edit':       { icon: Megaphone,    label: 'Campaign edit' },
  'campaign-creative':   { icon: ImageIcon,    label: 'Campaign creative' },
  'campaign-insight':    { icon: TrendingUp,   label: 'Insight' },
  // Journey-specific types. All carry the Route icon since journey is
  // the parent concept; the type differentiates the *reason* the user
  // is being asked to weigh in (new draft, health drop, paused).
  'journey-new':         { icon: Route,        label: 'New journey' },
  'journey-health':      { icon: Route,        label: 'Journey health' },
  'journey-paused':      { icon: Route,        label: 'Paused journey' },
  'plan-revise':         { icon: BarChart3,    label: 'Plan' },
  'budget-revise':       { icon: DollarSign,   label: 'Budget' },
  'objectives-revise':   { icon: Target,       label: 'Objectives' },
  'components-revise':   { icon: Layers,       label: 'Components' },
  'reputation':          { icon: Star,         label: 'Reputation' },
  'compliance':          { icon: Shield,       label: 'Compliance' },
  'oem-coop':            { icon: Award,        label: 'OEM co-op' },
  // Legacy kind values (still used by CampaignRichCard which derives kind from objective)
  'campaign-plan':       { icon: Megaphone,    label: 'Campaign plan' },
  'journey-plan':        { icon: Route,        label: 'Journey' },
  'budget':              { icon: DollarSign,   label: 'Budget' },
  'objectives':          { icon: Target,       label: 'Objectives' },
  'creative':            { icon: ImageIcon,    label: 'Creative' },
  'comms':               { icon: MessageCircle, label: 'Communication' }
};

// ApprovalCard renders the unified approval shape (heading + description +
// meta + CTA + dismiss) used everywhere approval cards appear: Home, Inbox,
// and the Campaigns workspace "Needs approval" zone.
//
// Accepts both new field names (type, heading) and legacy ones (kind,
// headline) for back-compat during the transition. New code should use the
// `type` and `heading` props.
function ApprovalCard({
  // New unified API
  type,
  heading,
  // Legacy back-compat
  kind = 'campaign-plan',
  headline,
  // Shared fields
  description,
  meta = [],
  mode = 'view',
  ctaLabel,
  onView,
  onApprove,
  onAcknowledge,
  onOverride,
  onDismiss
}) {
  // Resolve type (preferred) or kind (legacy) to the icon + label config.
  const resolvedKind = type || kind;
  const kindConfig = APPROVAL_CARD_KINDS[resolvedKind] || APPROVAL_CARD_KINDS['campaign-plan'];
  const Icon = kindConfig.icon;
  const resolvedHeading = heading || headline;
  
  // Mode determines primary/secondary verbs and which handlers are wired.
  // In view mode, an explicit ctaLabel can replace the default "View" label
  // so each card can communicate exactly what tapping it will do.
  let primaryLabel, primaryHandler, secondaryLabel, secondaryHandler;
  if (mode === 'approve') {
    primaryLabel = 'Approve';
    primaryHandler = onApprove;
    secondaryLabel = 'Dismiss';
    secondaryHandler = onDismiss;
  } else if (mode === 'acknowledge') {
    primaryLabel = 'Acknowledge';
    primaryHandler = onAcknowledge;
    secondaryLabel = 'Override';
    secondaryHandler = onOverride;
  } else {
    primaryLabel = ctaLabel || 'View';
    primaryHandler = onView;
    secondaryLabel = 'Dismiss';
    secondaryHandler = onDismiss;
  }
  
  return (
    <div style={{
      padding: '18px',
      background: t.surface,
      borderRadius: '10px',
      display: 'flex',
      gap: '14px',
      alignItems: 'flex-start'
    }}>
      {/* Icon block */}
      <div
        title={kindConfig.label}
        style={{
          width: '40px',
          height: '40px',
          borderRadius: '9px',
          background: t.surfaceMuted,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0
        }}
      >
        <Icon size={18} color={t.textSecondary} strokeWidth={1.75} />
      </div>
      
      {/* Content column */}
      <div style={{ flex: 1, minWidth: 0 }}>
        {/* Heading - the required user action, per spec */}
        <h3 style={{
          fontSize: '15px',
          fontWeight: 600,
          color: t.textPrimary,
          margin: 0,
          letterSpacing: '-0.005em',
          lineHeight: 1.35
        }}>
          {resolvedHeading}
        </h3>
        
        {/* Short description - additional context, one-liner */}
        {description && (
          <p style={{
            fontSize: '13px',
            color: t.textSecondary,
            margin: '4px 0 0',
            lineHeight: 1.5
          }}>
            {description}
          </p>
        )}
        
        {/* Meta strip - facts separated by dots */}
        {meta && meta.length > 0 && (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            flexWrap: 'wrap',
            marginTop: '10px',
            fontSize: '12px',
            color: t.textTertiary,
            fontFamily: fontStack,
            fontVariantNumeric: 'tabular-nums'
          }}>
            {meta.map((m, i) => (
              <React.Fragment key={i}>
                {i > 0 && <span style={{ color: t.textTertiary }}>·</span>}
                <span>{m}</span>
              </React.Fragment>
            ))}
          </div>
        )}
        
        {/* Action row */}
        {(primaryHandler || secondaryHandler) && (
          <div style={{
            display: 'flex',
            gap: '6px',
            marginTop: '14px'
          }}>
            {primaryHandler && (
              <button
                onClick={primaryHandler}
                style={{
                  padding: '7px 16px',
                  background: t.accent,
                  color: t.textOnColor,
                  border: 'none',
                  borderRadius: '7px',
                  fontSize: '12px',
                  fontWeight: 600,
                  cursor: 'pointer',
                  fontFamily: fontStack
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = t.accentHover}
                onMouseLeave={(e) => e.currentTarget.style.background = t.accent}
              >
                {primaryLabel}
              </button>
            )}
            {secondaryHandler && (
              <button
                onClick={secondaryHandler}
                style={{
                  padding: '7px 14px',
                  background: 'transparent',
                  color: t.textSecondary,
                  border: 'none',
                  borderRadius: '7px',
                  fontSize: '12px',
                  fontWeight: 500,
                  cursor: 'pointer',
                  fontFamily: fontStack
                }}
                onMouseEnter={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textPrimary; }}
                onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
              >
                {secondaryLabel}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ============= FILTER DROPDOWN =============
function FilterDropdown({ label, value, onChange, options }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  
  // Close on outside click
  useEffect(() => {
    const onDocClick = (e) => {
      if (ref.current && !ref.current.contains(e.target)) {
        setOpen(false);
      }
    };
    if (open) document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [open]);

  const currentLabel = options.find(o => o.value === value)?.label || 'All';

  return (
    <div ref={ref} style={{ position: 'relative' }}>
      <button
        onClick={() => setOpen(!open)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          padding: '8px 12px',
          background: t.surface,
          color: t.textPrimary,
          border: 'none',
          borderRadius: '8px',
          fontSize: '13px',
          fontWeight: 500,
          cursor: 'pointer',
          fontFamily: fontStack,
          transition: 'background 0.12s'
        }}
        onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
        onMouseLeave={(e) => e.currentTarget.style.background = t.surface}
      >
        <span style={{ color: t.textTertiary, fontWeight: 500 }}>{label}:</span>
        <span>{currentLabel}</span>
        <ChevronDown size={14} color={t.textTertiary} style={{
          transform: open ? 'rotate(180deg)' : 'rotate(0)',
          transition: 'transform 0.15s'
        }} />
      </button>
      
      {open && (
        <div style={{
          position: 'absolute',
          top: 'calc(100% + 4px)',
          left: 0,
          minWidth: '180px',
          background: t.bgPrimary,
          borderRadius: '10px',
          padding: '4px',
          boxShadow: '0 2px 8px rgba(22,22,22,0.08), 0 8px 24px rgba(22,22,22,0.08)',
          zIndex: 30,
          maxHeight: '280px',
          overflowY: 'auto'
        }}>
          {options.map(opt => {
            const isSelected = opt.value === value;
            return (
              <button
                key={opt.value}
                onClick={() => {
                  onChange(opt.value);
                  setOpen(false);
                }}
                style={{
                  width: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '8px 12px',
                  background: isSelected ? t.accentSoft : 'transparent',
                  color: isSelected ? t.accent : t.textPrimary,
                  border: 'none',
                  borderRadius: '6px',
                  fontSize: '13px',
                  fontWeight: isSelected ? 600 : 500,
                  cursor: 'pointer',
                  fontFamily: fontStack,
                  textAlign: 'left'
                }}
                onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = t.surfaceMuted; }}
                onMouseLeave={(e) => { if (!isSelected) e.currentTarget.style.background = 'transparent'; }}
              >
                <span>{opt.label}</span>
                {isSelected && <Check size={13} strokeWidth={2.5} />}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ============= COMPACT ASK BAR =============
function CompactAskBar({ input, setInput, onSend, isCompact, isSmall, navExpanded }) {
  const left = isCompact ? 0 : (navExpanded ? 224 : 64);
  const { aiWorking, setAiWorking, doneFlash } = useContext(AiWorkingContext);
  
  // Working: campaign is being built/generated by AI
  // DoneFlash: brief celebratory state right after work completes
  const isWorking = aiWorking !== null;
  const isFlashing = doneFlash !== null;
  
  // Copy for each state
  const workingLabel = aiWorking === 'coldStart' ? 'Building campaign'
    : aiWorking === 'creative' ? 'Generating creatives'
    : aiWorking === 'launch' ? 'Queuing for launch'
    : '';
  
  const doneLabel = doneFlash?.kind === 'coldStart' ? 'Campaign ready to review'
    : doneFlash?.kind === 'creative' ? 'Creatives ready to review'
    : doneFlash?.kind === 'launch' ? 'Campaign queued'
    : '';
  
  // Stop button cancels the current AI work
  const handleStop = () => {
    setAiWorking(null);
  };
  
  return (
    <div style={{
      position: 'fixed',
      bottom: 0,
      left: left + 'px',
      right: 0,
      zIndex: 60,
      pointerEvents: 'none'
    }}>
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        padding: isSmall ? '0 16px 16px' : '0 32px 24px',
        pointerEvents: 'auto'
      }}>
        {/* While AI is working: replace the input pill with a working-state pill */}
        {isWorking ? (
          <div style={{
            width: isSmall ? '100%' : '320px',
            background: t.bgPrimary,
            borderRadius: '14px',
            padding: '8px 10px 8px 14px',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
            boxShadow: '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)',
            transition: 'all 0.2s ease',
            animation: 'aiCommentaryIn 0.3s ease-out'
          }}>
            <img src={TEKION_AI_LOGO} alt="" style={{
              width: '20px', height: '20px', flexShrink: 0,
              animation: 'aiOrbit 2.4s linear infinite'
            }} />
            <span style={{
              flex: 1,
              fontSize: '13px', fontWeight: 500,
              color: t.textPrimary,
              minWidth: 0,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}>
              {workingLabel}
              <span style={{ color: t.textTertiary, marginLeft: '4px' }}>
                <DotPulse />
              </span>
            </span>
            <button
              onClick={handleStop}
              aria-label="Stop"
              title="Stop"
              style={{
                width: '26px', height: '26px',
                background: t.surfaceMuted,
                color: t.textSecondary,
                border: 'none', borderRadius: '7px', cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                transition: 'background 0.15s'
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = t.surfaceMuted; e.currentTarget.style.color = t.textSecondary; }}
            >
              <div style={{ width: '10px', height: '10px', background: 'currentColor', borderRadius: '2px' }} />
            </button>
          </div>
        ) : isFlashing ? (
          // Brief done-flash state
          <div style={{
            width: isSmall ? '100%' : '320px',
            background: t.successSoft,
            borderRadius: '14px',
            padding: '8px 14px',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
            boxShadow: '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)',
            transition: 'all 0.2s ease',
            animation: 'aiCommentaryIn 0.3s ease-out'
          }}>
            <div style={{
              width: '20px', height: '20px', flexShrink: 0,
              background: t.success,
              borderRadius: '50%',
              display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              <Check size={13} color={t.bgPrimary} strokeWidth={3} />
            </div>
            <span style={{ fontSize: '13px', fontWeight: 500, color: t.textPrimary }}>
              {doneLabel}
            </span>
          </div>
        ) : (
          // Normal state
          <div style={{
            width: isSmall ? '100%' : '280px',
            background: t.bgPrimary,
            borderRadius: '14px',
            padding: '8px 10px 8px 14px',
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            boxShadow: '0 4px 16px rgba(22,22,22,0.06), 0 1px 3px rgba(22,22,22,0.04)',
            transition: 'all 0.2s ease'
          }}>
            <img src={TEKION_AI_LOGO} alt="" style={{ width: '20px', height: '20px', flexShrink: 0 }} />
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') onSend(); }}
              placeholder="Ask Tekion AI"
              style={{
                flex: 1, background: 'transparent', border: 'none',
                color: t.textPrimary, fontSize: '13px', outline: 'none',
                fontFamily: fontStack, minWidth: 0
              }}
            />
            <button
              aria-label="Voice"
              style={{
                width: '26px', height: '26px',
                background: 'transparent', border: 'none',
                borderRadius: '6px', cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: t.textTertiary, flexShrink: 0
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              <Mic size={14} />
            </button>
            <button
              onClick={onSend}
              aria-label="Send"
              style={{
                width: '26px', height: '26px',
                background: input.trim() ? t.accent : t.surfaceMuted,
                color: input.trim() ? t.textOnColor : t.textTertiary,
                border: 'none', borderRadius: '7px', cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                transition: 'background 0.15s'
              }}
            >
              <SendIcon size={12} />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// Three-dot pulse for the working state label.
function DotPulse() {
  return (
    <span style={{ display: 'inline-flex', gap: '2px', alignItems: 'center' }}>
      {[0, 1, 2].map(i => (
        <span key={i} style={{
          width: '3px', height: '3px',
          borderRadius: '50%',
          background: 'currentColor',
          animation: 'dotPulse 1.2s ease-in-out infinite',
          animationDelay: (i * 0.15) + 's'
        }} />
      ))}
    </span>
  );
}

// ============= DISCUSS PANEL =============
function DiscussPanel({ messages, context, input, setInput, onSend, onClose, isCompact, isTablet, isSmall }) {
  const messagesEndRef = useRef(null);
  
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollTop = messagesEndRef.current.scrollHeight;
    }
  }, [messages]);
  
  // Below ~1024px (isTablet), panel becomes overlay
  const isOverlay = isTablet;
  
  if (isOverlay) {
    return (
      <>
        <div
          onClick={onClose}
          style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            background: 'rgba(22,22,22,0.32)', backdropFilter: 'blur(4px)',
            zIndex: 70
          }}
        />
        <div style={{
          position: 'fixed',
          top: isSmall ? 0 : '40px',
          right: 0, bottom: 0,
          left: isSmall ? 0 : 'auto',
          width: isSmall ? '100%' : '420px',
          maxWidth: '100vw',
          background: t.bgPrimary,
          zIndex: 71,
          borderRadius: isSmall ? 0 : '16px 0 0 0',
          boxShadow: '-8px 0 32px rgba(22,22,22,0.12)',
          display: 'flex',
          flexDirection: 'column'
        }}>
          <DiscussPanelInner messages={messages} context={context} input={input} setInput={setInput} onSend={onSend} onClose={onClose} messagesEndRef={messagesEndRef} />
        </div>
      </>
    );
  }
  
  return (
    <aside style={{
      width: '400px',
      flexShrink: 0,
      background: t.bgPrimary,
      borderRadius: '16px',
      margin: '0 32px 24px 0',
      display: 'flex',
      flexDirection: 'column',
      boxShadow: '0 1px 3px rgba(22,22,22,0.04), 0 8px 24px rgba(22,22,22,0.06)',
      maxHeight: 'calc(100vh - 88px)',
      position: 'sticky',
      top: '24px',
      animation: 'slideInRight 0.25s ease'
    }}>
      <DiscussPanelInner messages={messages} context={context} input={input} setInput={setInput} onSend={onSend} onClose={onClose} messagesEndRef={messagesEndRef} />
    </aside>
  );
}

// Inline version for use inside a sheet container.
// No positioning, no shadow - it inherits placement from the parent column.
function DiscussPanelInline({ messages, context, input, setInput, onSend, onClose }) {
  const messagesEndRef = useRef(null);
  
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);
  
  return (
    <div style={{
      width: '100%',
      height: '100%',
      background: t.bgPrimary,
      display: 'flex',
      flexDirection: 'column'
    }}>
      <DiscussPanelInner messages={messages} context={context} input={input} setInput={setInput} onSend={onSend} onClose={onClose} messagesEndRef={messagesEndRef} />
    </div>
  );
}

function DiscussPanelInner({ messages, context, input, setInput, onSend, onClose, messagesEndRef }) {
  return (
    <>
      {/* Header */}
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '16px 20px',
        flexShrink: 0
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <img src={TEKION_AI_LOGO} alt="Tekion AI" style={{ width: '24px', height: '24px' }} />
          <div>
            <div style={{ fontSize: '13px', fontWeight: 600, color: t.textPrimary }}>Tekion AI</div>
            <div style={{ fontSize: '11px', color: t.textTertiary }}>Always here</div>
          </div>
        </div>
        <button
          onClick={onClose}
          aria-label="Close"
          style={{
            background: 'transparent', border: 'none', color: t.textTertiary,
            cursor: 'pointer', padding: '6px', borderRadius: '6px', display: 'flex'
          }}
          onMouseEnter={(e) => e.currentTarget.style.background = t.surfaceMuted}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <X size={16} />
        </button>
      </div>

      {/* Context chip */}
      {context && (
        <div style={{
          margin: '0 20px 8px',
          padding: '8px 12px',
          background: t.accentSoft,
          borderRadius: '8px',
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          fontSize: '12px',
          color: t.accent,
          fontWeight: 500
        }}>
          <MessageCircle size={12} />
          <span>Discussing: {context.label}</span>
        </div>
      )}

      {/* Messages */}
      <div ref={messagesEndRef} style={{
        flex: 1,
        overflowY: 'auto',
        padding: '8px 20px 16px',
        display: 'flex',
        flexDirection: 'column',
        gap: '14px'
      }}>
        {messages.length === 0 && (
          <div style={{ padding: '20px 0', fontSize: '13px', color: t.textTertiary, lineHeight: 1.6 }}>
            Edit the question below or send as-is. I will explain my reasoning, share data, and take feedback.
          </div>
        )}
        {messages.map((msg, i) => {
          // ai_thinking placeholder: shows while AI is composing a reply.
          // Appears briefly between the user message and the full AI
          // response when the panel is primed by AIWidget.
          if (msg.role === 'ai_thinking') {
            return (
              <div key={i} style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                <img src={TEKION_AI_LOGO} alt="" style={{
                  width: '24px', height: '24px', flexShrink: 0, borderRadius: '6px',
                  animation: 'aiOrbit 2.4s linear infinite'
                }} />
                <div style={{
                  fontSize: '13px', color: t.textSecondary,
                  display: 'flex', alignItems: 'center', gap: '8px',
                  fontStyle: 'italic'
                }}>
                  <span>Thinking</span>
                  <DotPulse />
                </div>
              </div>
            );
          }
          return (
            <div key={i} style={{
              display: 'flex', gap: '10px',
              justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start'
            }}>
              {msg.role === 'ai' && (
                <img src={TEKION_AI_LOGO} alt="" style={{ width: '24px', height: '24px', flexShrink: 0, borderRadius: '6px' }} />
              )}
              <div style={{
                maxWidth: msg.role === 'user' ? '80%' : '92%',
                padding: msg.role === 'user' ? '8px 12px' : '0',
                background: msg.role === 'user' ? t.accentSoft : 'transparent',
                color: msg.role === 'user' ? t.accent : t.textPrimary,
                borderRadius: msg.role === 'user' ? '10px' : 0,
                fontSize: '13px',
                lineHeight: 1.55,
                whiteSpace: 'pre-line',
                fontWeight: msg.role === 'user' ? 500 : 400
              }}
              dangerouslySetInnerHTML={{
                __html: (msg.content || '').replace(/\*\*(.*?)\*\*/g, `<strong style="color: ${t.textPrimary}; font-weight: 600;">$1</strong>`)
              }}
              />
            </div>
          );
        })}
      </div>

      {/* Input */}
      <div style={{ padding: '12px 16px 16px', flexShrink: 0 }}>
        <div style={{
          background: t.surface,
          borderRadius: '12px',
          padding: '8px 10px 8px 14px',
          display: 'flex',
          alignItems: 'center',
          gap: '8px'
        }}>
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') onSend(); }}
            placeholder="Ask, refine, or push back"
            autoFocus
            style={{
              flex: 1, background: 'transparent', border: 'none',
              color: t.textPrimary, fontSize: '13px', outline: 'none',
              fontFamily: fontStack, minWidth: 0
            }}
          />
          <button
            style={{
              width: '26px', height: '26px',
              background: 'transparent', border: 'none',
              borderRadius: '6px', cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              color: t.textTertiary, flexShrink: 0
            }}
          >
            <Mic size={14} />
          </button>
          <button
            onClick={onSend}
            aria-label="Send"
            style={{
              width: '26px', height: '26px',
              background: input.trim() ? t.accent : t.surfaceMuted,
              color: input.trim() ? t.textOnColor : t.textTertiary,
              border: 'none', borderRadius: '7px', cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
            }}
          >
            <SendIcon size={12} />
          </button>
        </div>
      </div>
    </>
  );
}

function generateAskResponse(q, context) {
  const lq = q.toLowerCase();
  // Context-aware responses
  if (context && context.label) {
    const label = context.label.toLowerCase();
    if (label.includes('civic') && label.includes('paus')) {
      return {
        role: 'ai',
        content: `I paused the Civic conquest campaign on Tuesday at 4pm. Here is the rationale:\n\n**Performance trigger:** CPA crept from $186 to $312 over 5 days, above your $250 threshold.\n\n**Diagnosis:** Audience saturation. We reached 78% of in-market Civic shoppers in your trade area at least 3 times this quarter. Diminishing returns hit hard.\n\n**What I did instead:** Reallocated the $4.2K to CR-V conquest, where we are under-indexed and CPA is running $134.\n\n**When I will resume:** Quarterly audience refresh in 18 days, or sooner if competitive triggers fire.\n\nWant me to refresh sooner, or change the threshold?`
      };
    }
    if (label.includes('lease-end') || (label.includes('shift') && label.includes('lease'))) {
      return {
        role: 'ai',
        content: `Here is my full reasoning on the $18K lease-end shift:\n\n**Why this audience:** 142 customers coming off lease in the next 60 days. Lease-end is your highest-converting service-to-sales pipeline historically.\n\n**Why now:** Facebook prospecting CPA is running $312, well above your typical $180. The same dollars in lease-end have delivered $89 CPA over the last 6 months.\n\n**The math:** $18K at $89 CPA gets ~202 conversions, vs ~58 at $312 CPA. Net +144 incremental engagements, projecting to +11 sales.\n\n**My confidence:** 87%. The audience is well-defined, creative is proven, and the timing window matches the 60-day decision cycle.\n\nIf you want me to be more conservative, I can do a smaller $10K test first.`
      };
    }
    if (label.includes('service')) {
      return {
        role: 'ai',
        content: `Service marketing context for what you are looking at:\n\n**$487K attributed gross MTD**, ROI 8.2x, your strongest engine.\n\nFour active audience layers: equity-positive due-for-service, lapsed 6-9 months, recall-affected, and warranty-expiring. The lapsed audience is testing 3 creative angles, none meaningfully outperforming yet.\n\nWant my read on what to try next, or shall we look at a specific layer?`
      };
    }
    if (label.includes('memorial')) {
      return {
        role: 'ai',
        content: `Here is what I prepared for Memorial Day:\n\n**3 creative concepts** drafted from last year top performer ($1.2M attributed gross). All three keep the family + adventure framing that worked, but each tests a different headline angle: savings-led, inventory-led, and lifestyle-led.\n\n**Production budget:** $42K, within your typical Q2 spend.\n\n**Launch:** May 20, runs through Memorial Day weekend.\n\nI need your eye on creative direction before we commit to production. Want to review the three concepts?`
      };
    }
  }
  
  // Generic responses
  if (lq.includes('used trucks') || lq.includes('truck')) {
    return {
      role: 'ai',
      content: `Used trucks are running hot. **$612K attributed gross MTD**, up 22% YoY. We are moving units 11 days faster than last quarter.\n\nThe biggest driver is the F-150 conquest audience I built last month, capturing customers shopping at Riverside Ford. CPA is $147 vs the segment average of $283.\n\nOne thing worth noting: inventory aging on Tundras is creeping. I have already rebalanced spend toward them. If they do not move in the next 14 days, I would recommend a price action conversation with your sales manager.`
    };
  }
  if (lq.includes('service')) {
    return {
      role: 'ai',
      content: `Service marketing is your strongest engine right now. **$487K attributed gross MTD**, ROI 8.2x.\n\nFour active audience layers: equity-positive due-for-service, lapsed 6-9 months, recall-affected, and warranty-expiring. The lapsed audience is testing 3 creative angles, none meaningfully outperforming yet. Want my read on what to try next?`
    };
  }
  if (lq.includes('budget') || lq.includes('spend')) {
    return {
      role: 'ai',
      content: `You have **$680K remaining for Q2** across 8 weeks. Pacing is on track at +2% vs plan.\n\nMy strongest recommendation: shift 8% from display to service campaigns. Display is at the lower end of historical efficiency, while service is generating disproportionate gross. Projected impact: +$72K incremental gross.\n\nWant me to model alternatives?`
    };
  }
  if (lq.includes('why') || lq.includes('explain')) {
    return {
      role: 'ai',
      content: `Happy to explain. Could you point me to the specific item, decision, or metric you would like me to walk through? I will share the data signals, my reasoning, the alternatives I considered, and my confidence level.`
    };
  }
  return {
    role: 'ai',
    content: `Let me look into that. In a real conversation I would query the underlying data and respond contextually with relevant insights, recommendations, or analysis.`
  };
}

// ============= INBOX SHEET =============
// Two-tab side sheet: "Needs your approval" and "Activity".
// Filter by Area. Auto-filter on entry via prefilterArea prop.
// Inline conversation panel reveals to the right when Discuss is triggered,
// matching the Objectives sheet pattern.
function InboxSheet({
  onClose, decisionStates, handleDecision, onDiscuss, onOpenCampaign, onApprovalRoute, prefilterArea = 'all',
  panelOpen, askMessages, askInput, setAskInput, handlePanelSend, handlePanelClose, discussContext
}) {
  const pending = PENDING_APPROVALS.filter(a => !decisionStates[a.id]);
  const [tab, setTab] = useState('approvals');
  const [filterArea, setFilterArea] = useState(prefilterArea);
  
  // Body scroll lock while sheet is open
  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = previousOverflow; };
  }, []);
  
  // Apply filters - Area only
  const matchFilters = (item) => {
    if (filterArea !== 'all' && item.area !== filterArea) return false;
    return true;
  };
  
  const filteredApprovals = pending.filter(matchFilters);
  const filteredActivity = ACTIVITY_LOG.filter(matchFilters);
  
  // Group activity entries by day for the Activity tab
  const dayLabels = {
    today: 'Today',
    yesterday: 'Yesterday',
    this_week: 'Earlier this week',
    older: 'Older'
  };
  const dayOrder = ['today', 'yesterday', 'this_week', 'older'];
  const groupedActivity = {};
  filteredActivity.forEach(e => {
    const d = e.day || 'older';
    if (!groupedActivity[d]) groupedActivity[d] = [];
    groupedActivity[d].push(e);
  });
  
  const anyFilterActive = filterArea !== 'all';
  
  // Sheet width expands when conversation panel is open
  const SHEET_W_BASE = 720;
  const PANEL_W = 380;
  const totalWidth = panelOpen ? SHEET_W_BASE + PANEL_W : SHEET_W_BASE;
  
  return (
    <>
      <div
        onClick={() => { if (panelOpen) handlePanelClose(); onClose(); }}
        style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(22,22,22,0.32)', backdropFilter: 'blur(4px)',
          zIndex: 200
        }}
      />
      <div style={{
        position: 'fixed', top: 0, right: 0, bottom: 0,
        width: totalWidth + 'px', maxWidth: '100vw',
        background: t.bgPrimary, zIndex: 201,
        boxShadow: '-8px 0 32px rgba(22,22,22,0.12)',
        display: 'flex', flexDirection: 'row',
        transition: 'width 0.2s ease-out'
      }}>
        {/* Sheet content column */}
        <div style={{
          width: SHEET_W_BASE + 'px',
          maxWidth: '100%',
          flexShrink: 0,
          display: 'flex',
          flexDirection: 'column',
          borderRight: panelOpen ? '1px solid ' + t.surfaceMuted : 'none'
        }}>
        {/* Header */}
        <div style={{
          padding: '24px 32px 0',
          paddingTop: '20px',
          paddingRight: '80px',
          position: 'relative',
          flexShrink: 0
        }}>
          <h2 style={{ fontSize: '20px', fontWeight: 600, margin: 0, color: t.textPrimary, letterSpacing: '-0.01em' }}>
            Inbox
          </h2>
          <div style={{ fontSize: '13px', color: t.textTertiary, marginTop: '4px', lineHeight: 1.5 }}>
            {tab === 'approvals' ? 'Decisions I need from you to keep going.' : 'Things I have done autonomously.'}
          </div>
          {/* Close button positioned to match the Inbox icon's screen coordinates exactly.
              Page header has height 64px with align-items: center, so the Inbox icon's
              vertical center sits at y=32px. X button (36px) needs top=14 to land at y=32. */}
          <button
            onClick={onClose}
            style={{
              position: 'absolute',
              top: '14px',
              right: '32px',
              width: '36px',
              height: '36px',
              background: 'transparent', border: 'none', color: t.textSecondary,
              cursor: 'pointer', borderRadius: '8px',
              display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = t.surface; e.currentTarget.style.color = t.textPrimary; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = t.textSecondary; }}
          >
            <X size={18} strokeWidth={1.75} />
          </button>
        </div>
        
        {/* Tab strip */}
        <div style={{
          display: 'flex',
          gap: '4px',
          padding: '20px 32px 0',
          borderBottom: '1px solid ' + t.surfaceMuted
        }}>
          <button
            onClick={() => setTab('approvals')}
            style={{
              padding: '10px 14px',
              background: 'transparent',
              color: tab === 'approvals' ? t.textPrimary : t.textSecondary,
              border: 'none',
              borderBottom: '2px solid ' + (tab === 'approvals' ? t.accent : 'transparent'),
              borderRadius: 0,
              fontSize: '13px',
              fontWeight: tab === 'approvals' ? 600 : 500,
              cursor: 'pointer',
              fontFamily: fontStack,
              marginBottom: '-1px',
              display: 'flex', alignItems: 'center', gap: '6px'
            }}
          >
            Needs your approval
            {pending.length > 0 && (
              <span style={{
                fontSize: '11px',
                fontWeight: 600,
                color: t.accent,
                background: t.accentSoft,
                padding: '1px 6px',
                borderRadius: '5px',
                fontFamily: fontStack,
                fontVariantNumeric: 'tabular-nums'
              }}>
                {pending.length}
              </span>
            )}
          </button>
          <button
            onClick={() => setTab('activity')}
            style={{
              padding: '10px 14px',
              background: 'transparent',
              color: tab === 'activity' ? t.textPrimary : t.textSecondary,
              border: 'none',
              borderBottom: '2px solid ' + (tab === 'activity' ? t.accent : 'transparent'),
              borderRadius: 0,
              fontSize: '13px',
              fontWeight: tab === 'activity' ? 600 : 500,
              cursor: 'pointer',
              fontFamily: fontStack,
              marginBottom: '-1px'
            }}
          >
            Activity
          </button>
        </div>
        
        {/* Tab content - filter scrolls with content, no border separator */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '20px 32px 32px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
            <FilterPill
              label="Area"
              value={filterArea}
              options={APPROVAL_AREAS}
              onChange={setFilterArea}
            />
            {anyFilterActive && (
              <button
                onClick={() => setFilterArea('all')}
                style={{
                  padding: '7px 10px',
                  background: 'transparent',
                  color: t.textTertiary,
                  border: 'none',
                  fontSize: '11px', fontWeight: 500,
                  cursor: 'pointer',
                  fontFamily: fontStack
                }}
                onMouseEnter={(e) => e.currentTarget.style.color = t.textPrimary}
                onMouseLeave={(e) => e.currentTarget.style.color = t.textTertiary}
              >
                Clear filter
              </button>
            )}
          </div>
          
          {tab === 'approvals' && (
            filteredApprovals.length === 0 ? (
              <div style={{ padding: '48px 32px', textAlign: 'center' }}>
                <div style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary, marginBottom: '6px' }}>
                  {pending.length === 0 ? 'All caught up' : 'No items match these filters'}
                </div>
                <div style={{ fontSize: '13px', color: t.textTertiary }}>
                  {pending.length === 0 ? 'Nothing pending right now.' : 'Adjust your filters to see more.'}
                </div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {filteredApprovals.map(item => (
                  <ApprovalCard
                    key={item.id}
                    type={item.type}
                    heading={item.heading}
                    description={item.description}
                    meta={item.meta}
                    ctaLabel={item.ctaLabel || 'Review'}
                    onView={() => {
                      if (item.route && onApprovalRoute) {
                        onApprovalRoute(item.route);
                      } else {
                        onDiscuss({ label: item.heading, prefilledQuestion: 'Tell me more about: ' + item.heading });
                      }
                    }}
                    onDismiss={() => handleDecision(item.id, 'declined')}
                  />
                ))}
              </div>
            )
          )}
          
          {tab === 'activity' && (
            filteredActivity.length === 0 ? (
              <div style={{ padding: '48px 32px', textAlign: 'center' }}>
                <div style={{ fontSize: '14px', fontWeight: 600, color: t.textPrimary, marginBottom: '6px' }}>
                  No activity matches these filters
                </div>
                <div style={{ fontSize: '13px', color: t.textTertiary }}>
                  Adjust your filters to see more.
                </div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
                {dayOrder.map(day => {
                  const items = groupedActivity[day];
                  if (!items || items.length === 0) return null;
                  return (
                    <div key={day}>
                      <div style={{
                        fontSize: '12px',
                        fontWeight: 600,
                        color: t.textTertiary,
                        marginBottom: '10px'
                      }}>
                        {dayLabels[day]}
                      </div>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                        {items.map(item => (
                          <Discussable
                            key={item.id}
                            label={item.headline}
                            prefilledQuestion={'Tell me about this action: ' + item.headline}
                            onDiscuss={onDiscuss}
                            style={{ borderRadius: '10px' }}
                          >
                            <ActivityRow item={item} />
                          </Discussable>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )
          )}
        </div>
        </div>
        {/* Inline conversation panel when active */}
        {panelOpen && (
          <div style={{
            width: PANEL_W + 'px',
            flexShrink: 0,
            display: 'flex',
            flexDirection: 'column'
          }}>
            <DiscussPanelInline
              messages={askMessages}
              context={discussContext}
              input={askInput}
              setInput={setAskInput}
              onSend={() => { if (askInput.trim()) handlePanelSend(askInput); }}
              onClose={handlePanelClose}
            />
          </div>
        )}
      </div>
    </>
  );
}

// ----- Activity row (compact log entry) -----
function ActivityRow({ item }) {
  const kindConfig = APPROVAL_CARD_KINDS[item.kind] || APPROVAL_CARD_KINDS['campaign-plan'];
  const Icon = kindConfig.icon;
  
  return (
    <div style={{
      padding: '14px 16px',
      background: t.surface,
      borderRadius: '10px',
      display: 'flex',
      gap: '12px',
      alignItems: 'flex-start'
    }}>
      <div style={{
        width: '32px', height: '32px',
        borderRadius: '7px',
        background: t.surfaceMuted,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        flexShrink: 0
      }}>
        <Icon size={15} color={t.textSecondary} strokeWidth={1.75} />
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
          <h4 style={{ fontSize: '13px', fontWeight: 600, color: t.textPrimary, margin: 0, lineHeight: 1.4 }}>
            {item.headline}
          </h4>
          <span style={{ fontSize: '11px', color: t.textTertiary, fontWeight: 500, flexShrink: 0 }}>
            {item.timestamp}
          </span>
        </div>
        {item.description && (
          <p style={{ fontSize: '12px', color: t.textSecondary, margin: '0 0 8px', lineHeight: 1.5 }}>
            {item.description}
          </p>
        )}
        {item.meta && item.meta.length > 0 && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap',
            fontSize: '11px', color: t.textTertiary,
            fontFamily: fontStack, fontVariantNumeric: 'tabular-nums'
          }}>
            {item.meta.map((m, i) => (
              <React.Fragment key={i}>
                {i > 0 && <span>·</span>}
                <span>{m}</span>
              </React.Fragment>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
